"webpack://proton-account/../../packages/shared/lib/calendar/shareUrl/helpers.ts","webpack://proton-account/../../packages/components/containers/calendar/shareURL/LinkTable.tsx","webpack://proton-account/../../packages/components/containers/calendar/shareURL/ShareTable.tsx","webpack://proton-account/../../packages/components/containers/calendar/shareURL/ShareLinkSuccessModal.tsx","webpack://proton-account/../../packages/components/containers/calendar/shareURL/DeleteLinkConfirmationModal.tsx","webpack://proton-account/../../packages/components/containers/calendar/shareURL/EditLinkModal.tsx","webpack://proton-account/../../packages/components/hooks/useGetCalendarPublicLinks.ts","webpack://proton-account/../../packages/components/containers/calendar/shareURL/useCalendarShareUrls.ts","webpack://proton-account/../../packages/components/containers/calendar/shareURL/ShareSection.tsx","webpack://proton-account/../../packages/components/containers/calendar/settings/InviteLocaleSelector.tsx","webpack://proton-account/../../packages/components/containers/calendar/settings/CalendarInvitationsSection.tsx","webpack://proton-account/./src/app/containers/calendar/CalendarSettingsRouter.tsx","webpack://proton-account/../../packages/components/components/input/TimeInput.tsx","webpack://proton-account/../../packages/components/containers/themes/ThemeCard.tsx","webpack://proton-account/../../packages/components/containers/themes/ThemeCards.tsx","webpack://proton-account/../../packages/components/containers/themes/ThemesSection.tsx"],"sourcesContent":["import { EVENT_ACTIONS } from '../constants';\nimport {\n    CalendarEventManager,\n    CalendarEventManagerCreate,\n    CalendarEventManagerDelete,\n    CalendarEventManagerUpdate,\n    CalendarMemberEventManager,\n    CalendarMemberEventManagerCreate,\n    CalendarMemberEventManagerDelete,\n    CalendarMemberEventManagerUpdate,\n} from '../interfaces/calendar/EventManager';\n\nexport const getIsCalendarEventManagerDelete = (event: CalendarEventManager): event is CalendarEventManagerDelete => {\n    return event.Action === EVENT_ACTIONS.DELETE;\n};\n\nexport const getIsCalendarEventManagerCreate = (event: CalendarEventManager): event is CalendarEventManagerCreate => {\n    return event.Action === EVENT_ACTIONS.CREATE;\n};\n\nexport const getIsCalendarEventManagerUpdate = (event: CalendarEventManager): event is CalendarEventManagerUpdate => {\n    return event.Action === EVENT_ACTIONS.UPDATE;\n};\n\nexport const getIsCalendarMemberEventManagerDelete = (\n    event: CalendarMemberEventManager\n): event is CalendarMemberEventManagerDelete => {\n    return event.Action === EVENT_ACTIONS.DELETE;\n};\n\nexport const getIsCalendarMemberEventManagerCreate = (\n    event: CalendarMemberEventManager\n): event is CalendarMemberEventManagerCreate => {\n    return event.Action === EVENT_ACTIONS.CREATE;\n};\n\nexport const getIsCalendarMemberEventManagerUpdate = (\n    event: CalendarMemberEventManager\n): event is CalendarMemberEventManagerUpdate => {\n    return event.Action === EVENT_ACTIONS.UPDATE;\n};\n","import {\n    getIsCalendarEventManagerCreate,\n    getIsCalendarEventManagerUpdate,\n    getIsCalendarEventManagerDelete,\n    getIsCalendarMemberEventManagerDelete,\n    getIsCalendarMemberEventManagerCreate,\n    getIsCalendarMemberEventManagerUpdate,\n} from '../eventManager/helpers';\nimport { CalendarWithMembers } from '../interfaces/calendar';\nimport { CalendarEventManager, CalendarMemberEventManager } from '../interfaces/calendar/EventManager';\nimport { STATUS } from './cache';\nimport { CALENDARS_CACHE_KEY } from './calendarsModel';\n\nexport const findMemberIndices = (\n    memberID: string,\n    calendarsWithMembers: CalendarWithMembers[],\n    memberCalendarID?: string\n) => {\n    let calendarIndex = -1;\n    let memberIndex = -1;\n\n    calendarsWithMembers.forEach(({ ID, Members }, i) => {\n        if (ID === memberCalendarID) {\n            calendarIndex = i;\n        }\n        Members.forEach(({ ID }, j) => {\n            if (ID === memberID) {\n                memberIndex = j;\n                calendarIndex = i;\n            }\n        });\n    });\n\n    return [calendarIndex, memberIndex];\n};\n\nexport const updateCalendarsWithMembers = (\n    cache: Map<string, any>,\n    {\n        Calendars = [],\n        CalendarMembers = [],\n    }: {\n        Calendars?: CalendarEventManager[];\n        CalendarMembers?: CalendarMemberEventManager[];\n    }\n) => {\n    const { value: oldCalendarsWithMembers, status } = cache.get(CALENDARS_CACHE_KEY) || {};\n    if (status !== STATUS.RESOLVED) {\n        return;\n    }\n\n    const newCalendarsWithMembers: CalendarWithMembers[] = [...oldCalendarsWithMembers];\n\n    if (Calendars.length) {\n        for (const event of Calendars) {\n            if (getIsCalendarEventManagerDelete(event)) {\n                const index = newCalendarsWithMembers.findIndex(({ ID }) => ID === event.ID);\n                if (index !== -1) {\n                    newCalendarsWithMembers.splice(index, 1);\n                }\n            } else if (getIsCalendarEventManagerCreate(event)) {\n                const { ID: calendarID, Calendar } = event;\n                const index = newCalendarsWithMembers.findIndex(({ ID }) => ID === calendarID);\n                if (index !== -1) {\n                    // The calendar already exists for a creation event. Ignore it.\n                    continue;\n                }\n                newCalendarsWithMembers.push({ ...Calendar });\n            } else if (getIsCalendarEventManagerUpdate(event)) {\n                const { ID: calendarID, Calendar } = event;\n                const index = newCalendarsWithMembers.findIndex(({ ID }) => ID === calendarID);\n                if (index !== -1) {\n                    // update only the calendar part. Members updated below if needed\n                    const oldCalendarWithMembers = oldCalendarsWithMembers[index];\n                    newCalendarsWithMembers.splice(index, 1, { ...oldCalendarWithMembers, ...Calendar });\n                }\n            }\n        }\n    }\n    if (CalendarMembers.length) {\n        for (const event of CalendarMembers) {\n            if (getIsCalendarMemberEventManagerDelete(event)) {\n                const [calendarIndex, memberIndex] = findMemberIndices(event.ID, newCalendarsWithMembers);\n                // Remove the member from the calendar if it exists.\n                if (calendarIndex !== -1 && memberIndex !== -1) {\n                    newCalendarsWithMembers[calendarIndex].Members.splice(memberIndex, 1);\n                }\n            } else {\n                const [calendarIndex, memberIndex] = findMemberIndices(\n                    event.ID,\n                    newCalendarsWithMembers,\n                    event.Member.CalendarID\n                );\n                // If the targeted calendar cannot be found, ignore this update. It will be dealt with when the calendar update happens.\n                if (calendarIndex === -1) {\n                    continue;\n                }\n                if (getIsCalendarMemberEventManagerCreate(event)) {\n                    if (memberIndex !== -1) {\n                        continue;\n                    }\n                    newCalendarsWithMembers[calendarIndex].Members.push(event.Member);\n                } else if (getIsCalendarMemberEventManagerUpdate(event)) {\n                    if (memberIndex === -1) {\n                        continue;\n                    }\n                    newCalendarsWithMembers[calendarIndex].Members.splice(memberIndex, 1, event.Member);\n                }\n            }\n        }\n    }\n    cache.set(CALENDARS_CACHE_KEY, {\n        status: STATUS.RESOLVED,\n        value: newCalendarsWithMembers,\n    });\n};\n","import {\n    getIsCalendarMemberEventManagerCreate,\n    getIsCalendarMemberEventManagerDelete,\n    getIsCalendarMemberEventManagerUpdate,\n} from '../eventManager/helpers';\nimport { CalendarKey, CalendarMember, CalendarSettings as tsCalendarSettings } from '../interfaces/calendar';\nimport { CalendarMemberEventManager } from '../interfaces/calendar/EventManager';\n\n/**\n * Find the calendar id for an event, since it's not always returned.\n */\nconst findCalendarID = (calendarBootstrapCache: Map<string, any>, cb: (value: any) => boolean) => {\n    for (const [calendarID, record] of calendarBootstrapCache) {\n        // The old bootstrapped result\n        if (record && record.value && cb(record.value)) {\n            return calendarID;\n        }\n    }\n};\n\n/**\n * Assumes that updates to the calendar bootstrap cache do not trigger UI updates\n * In other words, that the bootstrap is only used through callbacks but not needed to re-render UI\n * In consequence, no setCache is invoked, the cache is mutated directly\n */\nexport const updateBootstrapKeysAndSettings = (\n    {\n        CalendarKeys = [],\n        CalendarSettings = [],\n    }: {\n        CalendarKeys: { ID: string; Key: CalendarKey }[];\n        CalendarSettings: { ID: string; CalendarSettings: tsCalendarSettings }[];\n    },\n    calendarBootstrapCache: Map<string, any>,\n    calendarKeysCache: Map<string, any>\n) => {\n    if (!calendarBootstrapCache) {\n        return;\n    }\n\n    if (CalendarSettings.length) {\n        for (const { ID: CalendarID, CalendarSettings: newValue } of CalendarSettings) {\n            const oldRecord = calendarBootstrapCache.get(CalendarID);\n            if (oldRecord && oldRecord.value) {\n                // Mutation on purpose\n                oldRecord.value.CalendarSettings = newValue;\n            }\n        }\n    }\n\n    if (CalendarKeys.length) {\n        const deleteCalendarFromCache = (calendarID: string) => {\n            if (calendarBootstrapCache) {\n                calendarBootstrapCache.delete(calendarID);\n            }\n            if (calendarKeysCache) {\n                calendarKeysCache.delete(calendarID);\n            }\n        };\n\n        CalendarKeys.forEach(({ ID: KeyID, Key }) => {\n            // When a new calendar key is received, the entire calendar cache is invalidated.\n            // TODO: Merge the bootstrapped version.\n            if (Key && Key.CalendarID) {\n                deleteCalendarFromCache(Key.CalendarID);\n                return;\n            }\n            const calendarID = findCalendarID(calendarBootstrapCache, ({ Keys }) => {\n                return Array.isArray(Keys) && Keys.find(({ ID: otherID }) => otherID === KeyID);\n            });\n            if (calendarID) {\n                deleteCalendarFromCache(Key.CalendarID);\n            }\n        });\n    }\n};\n\n/**\n * Assumes that updates to the calendar bootstrap cache do not trigger UI updates\n * In other words, that the bootstrap is only used through callbacks but not needed to re-render UI\n * In consequence, no setCache is invoked, the cache is mutated directly\n */\nexport const updateBootstrapMembers = (\n    calendarBootstrapCache: Map<string, any>,\n    {\n        CalendarMembers = [],\n    }: {\n        CalendarMembers?: CalendarMemberEventManager[];\n    }\n) => {\n    if (!calendarBootstrapCache) {\n        return;\n    }\n\n    if (CalendarMembers.length) {\n        CalendarMembers.forEach((event) => {\n            if (getIsCalendarMemberEventManagerDelete(event)) {\n                const { ID: memberID } = event;\n                const calendarID = findCalendarID(calendarBootstrapCache, ({ Members }) => {\n                    return Members.find(({ ID }: { ID: string }) => ID === memberID);\n                });\n                if (!calendarID) {\n                    return;\n                }\n                const oldRecord = calendarBootstrapCache.get(calendarID);\n                const oldMembers = oldRecord.value.Members as CalendarMember[];\n                const memberIndex = oldMembers.findIndex(({ ID }) => memberID === ID);\n                if (memberIndex !== -1) {\n                    return;\n                }\n                // Mutation on purpose\n                oldMembers.splice(memberIndex, 1);\n            } else {\n                const { ID, Member } = event;\n                const oldRecord = calendarBootstrapCache.get(Member.CalendarID);\n                if (!oldRecord?.value) {\n                    return;\n                }\n                const oldMembers = oldRecord.value.Members as CalendarMember[];\n                const memberIndex = oldMembers.findIndex(({ ID: memberID }) => memberID === ID);\n                if (getIsCalendarMemberEventManagerCreate(event)) {\n                    if (memberIndex !== -1) {\n                        return;\n                    }\n                    // Mutation on purpose\n                    oldMembers.push(Member);\n                } else if (getIsCalendarMemberEventManagerUpdate(event)) {\n                    if (memberIndex === -1) {\n                        return;\n                    }\n                    // Mutation on purpose\n                    oldMembers.splice(memberIndex, 1, event.Member);\n                }\n            }\n        });\n    }\n};\n","import { EVENT_ACTIONS } from '@proton/shared/lib/constants';\nimport { CalendarUserSettingsModel } from '@proton/shared/lib/models';\nimport { useEffect } from 'react';\nimport { STATUS } from '@proton/shared/lib/models/cache';\nimport { CalendarEventManager } from '@proton/shared/lib/interfaces/calendar/EventManager';\nimport { updateCalendarsWithMembers as updateCalendarsWithMembers } from '@proton/shared/lib/models/calendarMembers';\nimport { updateBootstrapKeysAndSettings, updateBootstrapMembers } from '@proton/shared/lib/models/calendarBootstrap';\nimport { useCache, useEventManager } from '../../../hooks';\nimport { KEY as CALENDAR_BOOTSTRAP_CACHE } from '../../../hooks/useGetCalendarBootstrap';\nimport { CACHE_KEY as CALENDAR_KEYS_CACHE } from '../../../hooks/useGetDecryptedPassphraseAndCalendarKeys';\nimport { useCalendarModelEventManager } from './ModelEventManagerProvider';\n\n/**\n * Listen manually to updates to calendar members and user settings (via core event loop)\n */\nexport const useCalendarsInfoCoreListener = () => {\n    const { subscribe: standardSubscribe } = useEventManager();\n    const cache = useCache();\n\n    useEffect(() => {\n        // subscribe via the standard event loop to updates of CalendarsModel, CalendarMembersModel and CalendarUserSettingsModel\n        const calendarUserSettingsModelKey = CalendarUserSettingsModel.key;\n        return standardSubscribe((data) => {\n            if (data[calendarUserSettingsModelKey]) {\n                const { value: oldValue, status } = cache.get(calendarUserSettingsModelKey) || {};\n                if (status === STATUS.RESOLVED) {\n                    cache.set(calendarUserSettingsModelKey, {\n                        status: STATUS.RESOLVED,\n                        value: CalendarUserSettingsModel.update(oldValue, data[calendarUserSettingsModelKey]),\n                    });\n                }\n            }\n            updateCalendarsWithMembers(cache, data);\n            updateBootstrapMembers(cache.get(CALENDAR_BOOTSTRAP_CACHE), data);\n        });\n    }, []);\n};\n\nconst useCalendarsInfoCalendarListener = (calendarIDs: string[]) => {\n    const { subscribe: standardSubscribe } = useEventManager();\n    const { subscribe: calendarSubscribe, reset: calendarReset } = useCalendarModelEventManager();\n    const cache = useCache();\n\n    useEffect(() => {\n        // subscribe via the calendar event loop to updates of CalendarKeysModel and CalendarSettingsModel\n        return calendarSubscribe(calendarIDs, (data) => {\n            if (data) {\n                updateBootstrapKeysAndSettings(\n                    data,\n                    cache.get(CALENDAR_BOOTSTRAP_CACHE),\n                    cache.get(CALENDAR_KEYS_CACHE)\n                );\n            }\n        });\n    }, [calendarIDs]);\n\n    useEffect(() => {\n        // stop per-calendar event managers when calendars are deleted\n        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {\n            Calendars.forEach(({ ID, Action }) => {\n                if (Action === EVENT_ACTIONS.DELETE) {\n                    calendarReset([ID]);\n                }\n            });\n        });\n    }, []);\n};\n\n/**\n * Listen manually to updates to calendar members, keys and settings\n */\nconst useCalendarsInfoListener = (calendarIDs: string[]) => {\n    useCalendarsInfoCoreListener();\n    useCalendarsInfoCalendarListener(calendarIDs);\n};\n\nexport default useCalendarsInfoListener;\n","import {\n    useState,\n    useRef,\n    useMemo,\n    FormEvent,\n    KeyboardEvent,\n    MouseEvent,\n    ReactElement,\n    ComponentPropsWithoutRef,\n} from 'react';\nimport { c } from 'ttag';\nimport { normalize } from '@proton/shared/lib/helpers/string';\n\nimport { Dropdown } from '../dropdown';\nimport { Props as OptionProps } from '../option/Option';\nimport { classnames } from '../../helpers';\nimport { SearchInput } from '../input';\nimport SelectButton from './SelectButton';\nimport SelectOptions from './SelectOptions';\nimport useSelect, { SelectProvider } from './useSelect';\nimport { SelectChangeEvent } from './select';\n\nconst includesString = (str1: string, str2: string) => normalize(str1, true).indexOf(normalize(str2, true)) > -1;\n\nconst arrayIncludesString = (arrayToSearch: string[], keyword: string) =>\n    arrayToSearch.some((str) => includesString(str, keyword));\n\nconst defaultFilterFunction = <V,>(option: OptionProps<V>, keyword: string) =>\n    (option.title && includesString(option.title, keyword)) ||\n    (option.searchStrings && arrayIncludesString(option.searchStrings, keyword));\n\nexport interface Props<V>\n    extends Omit<ComponentPropsWithoutRef<'button'>, 'value' | 'onClick' | 'onChange' | 'onKeyDown' | 'aria-label'> {\n    value?: V;\n    /**\n     * Optionally allows controlling the Select's open state\n     */\n    isOpen?: boolean;\n    /**\n     * Children Options of the Select, have to be of type Option\n     * (or something that implements the same interface)\n     */\n    children: ReactElement<OptionProps<V>>[];\n    onChange?: (e: SelectChangeEvent<V>) => void;\n    onClose?: () => void;\n    onOpen?: () => void;\n    loading?: boolean;\n    search?: boolean | ((option: OptionProps<V>) => void);\n    searchPlaceholder?: string;\n    noSearchResults?: string;\n}\n\nconst SearchableSelect = <V extends any>({\n    children,\n    value,\n    placeholder,\n    isOpen: controlledOpen,\n    onClose,\n    onOpen,\n    onChange,\n    loading,\n    search,\n    searchPlaceholder,\n    noSearchResults = c('Select search results').t`No results found`,\n    ...rest\n}: Props<V>) => {\n    const [searchValue, setSearchValue] = useState('');\n\n    const anchorRef = useRef<HTMLButtonElement | null>(null);\n    const searchContainerRef = useRef<HTMLDivElement>(null);\n    const searchInputRef = useRef<HTMLInputElement>(null);\n\n    const optionValues = children.map((option) => option.props.value);\n\n    const select = useSelect<V>({\n        value,\n        options: optionValues,\n        onChange,\n        onClose,\n        onOpen,\n    });\n\n    const {\n        isOpen,\n        selectedIndex,\n        open,\n        close: handleClose,\n        setFocusedIndex,\n        handleChange,\n        focusNextIndex,\n        focusPreviousIndex,\n        focusedIndex,\n    } = select;\n\n    const close = (event?: MouseEvent<HTMLDivElement> | Event) => {\n        if (event?.target instanceof Node && searchContainerRef?.current?.contains(event.target)) {\n            return;\n        }\n\n        handleClose();\n    };\n\n    const focusSearchInput = () => {\n        searchInputRef?.current?.focus();\n    };\n\n    const handleAnchorClick = () => {\n        if (isOpen) {\n            close();\n        } else {\n            open();\n            setFocusedIndex(selectedIndex || 0);\n        }\n    };\n\n    const handleClosed = () => {\n        setSearchValue('');\n    };\n\n    const handleDropdownContentKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {\n        switch (e.key) {\n            case 'Escape': {\n                close();\n                anchorRef.current?.focus();\n                break;\n            }\n\n            default:\n        }\n    };\n\n    const onSearchChange = (event: FormEvent<HTMLInputElement>) => {\n        setSearchValue(event.currentTarget.value);\n\n        if (!event.currentTarget.value) {\n            focusSearchInput();\n        }\n    };\n\n    const selectedChild = selectedIndex || selectedIndex === 0 ? children[selectedIndex] : null;\n\n    const displayedValue = selectedChild?.props?.children || selectedChild?.props?.title || placeholder;\n\n    const ariaLabel = selectedChild?.props?.title;\n\n    const filteredOptions = useMemo(() => {\n        if (!searchValue) {\n            return children;\n        }\n\n        const filterFunction = typeof search === 'function' ? search : defaultFilterFunction;\n\n        const filteredOptions = children.filter((child) => filterFunction(child.props, searchValue));\n\n        return filteredOptions;\n    }, [children, search, searchValue]);\n\n    const selectedIndexInFilteredOptions =\n        typeof selectedIndex === 'number'\n            ? filteredOptions.findIndex((option) => children[selectedIndex] === option)\n            : null;\n\n    const pressedDown = useRef(false);\n\n    return (\n        <SelectProvider {...select}>\n            <SelectButton isOpen={isOpen} onClick={handleAnchorClick} aria-label={ariaLabel} ref={anchorRef} {...rest}>\n                {displayedValue}\n            </SelectButton>\n\n            <Dropdown\n                isOpen={isOpen}\n                onClosed={handleClosed}\n                anchorRef={anchorRef}\n                onClose={close}\n                offset={4}\n                noCaret\n                noMaxWidth\n                sameAnchorWidth\n                disableDefaultArrowNavigation={!searchValue}\n                className={classnames([searchContainerRef?.current && 'dropdown--is-searchable'])}\n            >\n                <div onKeyDown={handleDropdownContentKeyDown}>\n                    <div className=\"dropdown-search\" ref={searchContainerRef}>\n                        <SearchInput\n                            onKeyDown={(e) => {\n                                if (searchValue) {\n                                    return;\n                                }\n\n                                if (e.key === 'ArrowDown') {\n                                    focusNextIndex();\n                                }\n\n                                if (e.key === 'ArrowUp') {\n                                    focusPreviousIndex();\n                                }\n\n                                if (e.key === 'Tab') {\n                                    handleClose();\n                                }\n\n                                if (e.key === 'Enter') {\n                                    pressedDown.current = true;\n                                }\n                            }}\n                            onKeyUp={(e) => {\n                                if (searchValue) {\n                                    return;\n                                }\n\n                                if (e.key === 'Enter' && pressedDown.current) {\n                                    if (focusedIndex) {\n                                        handleChange({\n                                            value: optionValues[focusedIndex],\n                                            selectedIndex: focusedIndex,\n                                        });\n\n                                        handleClose();\n                                    }\n\n                                    pressedDown.current = false;\n                                }\n                            }}\n                            autoFocus\n                            ref={searchInputRef}\n                            value={searchValue}\n                            onInput={onSearchChange}\n                            placeholder={searchPlaceholder}\n                        />\n                    </div>\n\n                    {filteredOptions.length === 0 ? (\n                        <div className=\"dropdown-search-no-result text-center\">{noSearchResults}</div>\n                    ) : (\n                        <SelectOptions\n                            disableFocusOnActive\n                            selected={selectedIndexInFilteredOptions}\n                            onChange={handleChange}\n                        >\n                            {filteredOptions}\n                        </SelectOptions>\n                    )}\n                </div>\n            </Dropdown>\n        </SelectProvider>\n    );\n};\n\nexport default SearchableSelect;\n","import { useMemo } from 'react';\nimport { c } from 'ttag';\n\nimport { getTimeZoneOptions } from '@proton/shared/lib/date/timezone';\n\nimport { Props as SelectProps } from '../selectTwo/SelectTwo';\nimport { Option } from '../option';\nimport { SearchableSelect } from '../selectTwo';\n\ninterface Props extends Omit<SelectProps<string>, 'onChange' | 'children'> {\n    timezone?: string;\n    onChange: (tzid: string) => void;\n    className?: string;\n    defaultTimezone?: string;\n    disabled?: boolean;\n    date?: Date;\n    loading?: boolean;\n}\nexport const TimezoneSelector = ({ loading = false, disabled = false, date, timezone, onChange, ...rest }: Props) => {\n    const timezoneOptions = useMemo(() => {\n        const options = getTimeZoneOptions(date || new Date());\n\n        return options.map(({ text, value, key }) => <Option key={key} value={value} title={text} />);\n    }, [date]);\n\n    return (\n        <SearchableSelect\n            disabled={loading || disabled}\n            title={c('Action').t`Select timezone`}\n            value={timezone}\n            onChange={({ value }) => {\n                onChange(value);\n            }}\n            search\n            searchPlaceholder={c('Timezone search placeholder').t`Search timezones`}\n            {...rest}\n        >\n            {timezoneOptions}\n        </SearchableSelect>\n    );\n};\n\nexport default TimezoneSelector;\n","import { updateCalendarUserSettings } from '@proton/shared/lib/api/calendars';\nimport { CalendarUserSettings } from '@proton/shared/lib/interfaces/calendar';\nimport { c } from 'ttag';\n\nimport { useApi, useEventManager, useLoading, useNotifications } from '../../../hooks';\n\nimport { TimezoneSelector } from '../../../components';\n\nimport SettingsLayoutLeft from '../../account/SettingsLayoutLeft';\nimport SettingsLayout from '../../account/SettingsLayout';\nimport SettingsLayoutRight from '../../account/SettingsLayoutRight';\n\ninterface Props {\n    calendarUserSettings: CalendarUserSettings;\n}\n\nconst PrimaryTimezoneSection = ({ calendarUserSettings: { PrimaryTimezone } }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [loadingPrimaryTimeZone, withLoadingPrimaryTimeZone] = useLoading();\n\n    const handleChange = async (data: Partial<CalendarUserSettings>) => {\n        await api(updateCalendarUserSettings(data));\n        await call();\n        createNotification({ text: c('Success').t`Preference saved` });\n    };\n\n    return (\n        <SettingsLayout>\n            <SettingsLayoutLeft>\n                <label className=\"text-semibold\" htmlFor=\"primary-timezone\" id=\"label-primary-timezone\">\n                    <span className=\"mr0-5\">{c('Primary timezone').t`Primary time zone`}</span>\n                </label>\n            </SettingsLayoutLe