  Addresses: Address[];\n    AddressID: string;\n}\nexport const getCalendarModel = ({\n    Calendar,\n    CalendarSettings,\n    Addresses,\n    AddressID,\n}: GetCalendarModelArguments): Partial<CalendarViewModelFull> => {\n    const {\n        DefaultPartDayNotifications = DEFAULT_PART_DAY_NOTIFICATIONS,\n        DefaultFullDayNotifications = DEFAULT_FULL_DAY_NOTIFICATIONS,\n        DefaultEventDuration = DEFAULT_EVENT_DURATION,\n    } = CalendarSettings;\n\n    const partDayNotifications = notificationsToModel(DefaultPartDayNotifications, false);\n    const fullDayNotifications = notificationsToModel(DefaultFullDayNotifications, true);\n\n    return {\n        calendarID: Calendar.ID,\n        name: Calendar.Name,\n        display: !!Calendar.Display,\n        description: Calendar.Description,\n        color: (Calendar.Color || '').toLowerCase(),\n        addressID: AddressID,\n        addressOptions: Addresses.map(({ ID, Email = '' }) => ({ value: ID, text: Email })),\n        duration: DefaultEventDuration,\n        partDayNotifications,\n        fullDayNotifications,\n        type: Calendar.Type,\n    };\n};\n\nexport const getDefaultModel = (): CalendarViewModelFull => {\n    return {\n        calendarID: '',\n        name: '',\n        members: [],\n        description: '',\n        color: ACCENT_COLORS[randomIntFromInterval(0, ACCENT_COLORS.length - 1)],\n        display: true,\n        addressID: '',\n        addressOptions: [],\n        duration: DEFAULT_EVENT_DURATION,\n        defaultPartDayNotification: DEFAULT_PART_DAY_NOTIFICATION,\n        defaultFullDayNotification: DEFAULT_FULL_DAY_NOTIFICATION,\n        partDayNotifications: notificationsToModel(DEFAULT_PART_DAY_NOTIFICATIONS, false),\n        fullDayNotifications: notificationsToModel(DEFAULT_FULL_DAY_NOTIFICATIONS, true),\n        type: CALENDAR_TYPE.PERSONAL,\n    };\n};\n\nexport const validate = ({ name }: CalendarViewModelFull): CalendarErrors => {\n    const errors = {} as { [key: string]: string };\n\n    if (!name) {\n        errors.name = c('Error').t`Name required`;\n    }\n\n    return errors;\n};\n\nexport const getCalendarPayload = (model: CalendarViewModelFull): CalendarCreateData => {\n    return {\n        Name: model.name,\n        Color: model.color,\n        Display: model.display ? 1 : 0,\n        Description: model.description,\n        URL: model.url,\n    };\n};\n\nexport const getCalendarSettingsPayload = (model: CalendarViewModelFull) => {\n    const { duration, fullDayNotifications, partDayNotifications } = model;\n\n    return {\n        DefaultEventDuration: +duration,\n        DefaultFullDayNotifications: modelToNotifications(fullDayNotifications),\n        DefaultPartDayNotifications: modelToNotifications(partDayNotifications),\n    };\n};\n","import { c, msgid } from 'ttag';\nimport { clamp } from '@proton/shared/lib/helpers/math';\nimport { NOTIFICATION_UNITS, NOTIFICATION_UNITS_MAX, NOTIFICATION_WHEN } from '@proton/shared/lib/calendar/constants';\n\nexport const getDaysBefore = (value: number) => ({\n    text: c('Notification when').ngettext(msgid`day before`, `days before`, value),\n    value: clamp(value, 1, NOTIFICATION_UNITS_MAX[NOTIFICATION_UNITS.DAY]),\n    unit: NOTIFICATION_UNITS.DAY,\n    when: NOTIFICATION_WHEN.BEFORE,\n});\n\nexport const getSameDay = () => ({\n    text: c('Notification when').t`on the same day`,\n    value: 0,\n    unit: NOTIFICATION_UNITS.DAY,\n    when: NOTIFICATION_WHEN.AFTER,\n});\n\nexport const getSameTime = () => ({\n    text: c('Notification when').t`at time of event`,\n    value: 0,\n    unit: NOTIFICATION_UNITS.MINUTES,\n    when: NOTIFICATION_WHEN.AFTER,\n});\n\nexport const getWeeksBefore = (value: number) => ({\n    text: c('Notification when').ngettext(msgid`week before`, `weeks before`, value),\n    value: clamp(value, 1, NOTIFICATION_UNITS_MAX[NOTIFICATION_UNITS.WEEK]),\n    unit: NOTIFICATION_UNITS.WEEK,\n    when: NOTIFICATION_WHEN.BEFORE,\n});\n\nexport const getMinutesBefore = (value: number) => ({\n    text: c('Notification when').ngettext(msgid`minute before`, `minutes before`, value),\n    value: clamp(value, 1, NOTIFICATION_UNITS_MAX[NOTIFICATION_UNITS.MINUTES]),\n    unit: NOTIFICATION_UNITS.MINUTES,\n    when: NOTIFICATION_WHEN.BEFORE,\n});\n\nexport const getHoursBefore = (value: number) => ({\n    text: c('Notification when').ngettext(msgid`hour before`, `hours before`, value),\n    value: clamp(value, 1, NOTIFICATION_UNITS_MAX[NOTIFICATION_UNITS.HOURS]),\n    unit: NOTIFICATION_UNITS.HOURS,\n    when: NOTIFICATION_WHEN.BEFORE,\n});\n","import { useContext, useEffect } from 'react';\nimport { useInstance } from '../..';\n\nimport { generateUID } from '../../helpers';\nimport { SpotlightContext } from './Provider';\n\nconst useSpotlightShow = (show: boolean) => {\n    const uid = useInstance(() => generateUID());\n\n    const { spotlight, addSpotlight } = useContext(SpotlightContext);\n\n    useEffect(() => {\n        if (show) {\n            addSpotlight(uid);\n        }\n    }, [show]);\n\n    return spotlight === uid && show;\n};\n\nexport default useSpotlightShow;\n","import { ChangeEvent } from 'react';\nimport Input, { Props as InputProps } from './Input';\n\ninterface Props extends Omit<InputProps, 'onChange' | 'value' | 'min' | 'max'> {\n    max?: number;\n    min?: number;\n    value: number | undefined;\n    onChange: (value: number | undefined) => void;\n    step?: number;\n}\n\n/**\n * Small helper to transform a string or a number into a string\n * For other type of arguments, return undefined\n */\nconst toString = (x: any) => (['number', 'string'].includes(typeof x) ? `${x}` : undefined);\n\nconst IntegerInput = ({ value, onChange, max, min, step, ...rest }: Props) => {\n    const minStr = toString(min);\n    const maxStr = toString(max);\n    const stepStr = toString(step) || '1';\n    const intValue = parseInt(`${value}`, 10);\n\n    return (\n        <Input\n            type=\"number\"\n            step={stepStr}\n            min={minStr}\n            max={maxStr}\n            value={value === null || Number.isNaN(intValue) ? '' : intValue}\n            onInput={({ target, target: { value: newValue, validity } }: ChangeEvent<HTMLInputElement>) => {\n                const isClear = validity.valid;\n                // Prevent broken input on certain browsers since it allows to enter other characters than integer numbers\n                if (newValue === '') {\n                    const emptyOrOldValue = isClear ? undefined : value;\n                    target.value = `${emptyOrOldValue || ''}`;\n                    return onChange(emptyOrOldValue);\n                }\n                const newIntValue = parseInt(newValue, 10);\n                if (\n                    Number.isNaN(newIntValue) ||\n                    (minStr && newIntValue < +minStr) ||\n                    (maxStr && newIntValue > +maxStr)\n                ) {\n                    target.value = `${intValue}`;\n                    return;\n                }\n                target.value = `${newIntValue}`;\n                onChange(newIntValue);\n            }}\n            {...rest}\n        />\n    );\n};\n\nexport default IntegerInput;\n","import { c } from 'ttag';\n\nimport { NotificationModel } from '@proton/shared/lib/interfaces/calendar/Notification';\nimport {\n    NOTIFICATION_INPUT_ID,\n    NOTIFICATION_UNITS_MAX,\n    SETTINGS_NOTIFICATION_TYPE,\n} from '@proton/shared/lib/calendar/constants';\nimport {\n    getDaysBefore,\n    getHoursBefore,\n    getMinutesBefore,\n    getSameDay,\n    getSameTime,\n    getWeeksBefore,\n} from './notificationOptions';\nimport { classnames } from '../../../../helpers';\nimport { Option, SelectTwo, IntegerInput, TimeInput, Spotlight, useSpotlightShow } from '../../../../components';\nimport { FeatureCode } from '../../..';\nimport { useSpotlightOnFeature } from '../../../..';\n\nconst { EMAIL, DEVICE /* BOTH */ } = SETTINGS_NOTIFICATION_TYPE;\n\ninterface Props {\n    className?: string;\n    notification: NotificationModel;\n    hasWhen?: boolean;\n    hasType?: boolean;\n    onChange: (model: NotificationModel) => void;\n    error?: string;\n}\n\nconst getWhenOptions = (isAllDay: boolean, value = 0) => {\n    if (isAllDay) {\n        return [getSameDay(), getDaysBefore(value), getWeeksBefore(value)];\n    }\n\n    return [getSameTime(), getMinutesBefore(value), getHoursBefore(value), getDaysBefore(value), getWeeksBefore(value)];\n};\n\nconst NotificationInput = ({\n    className,\n    notification,\n    notification: { isAllDay, type, when, value, at, unit },\n    hasType = false,\n    onChange,\n    error,\n}: Props) => {\n    const safeValue = value === undefined ? 1 : value;\n\n    const options = getWhenOptions(isAllDay, safeValue);\n    const textOptions = options.map((option, i) => ({ text: option.text, value: i }));\n    const closestOption = options.findIndex((option) => {\n        return option.value === safeValue && option.unit === unit && option.when === when;\n    });\n    const optionsValue = closestOption === -1 ? 0 : closestOption;\n\n    const hasValueInput = value === undefined || value > 0;\n\n    const errorProps = typeof error === 'string' ? { 'aria-invalid': true } : {};\n\n    const {\n        show,\n        onDisplayed,\n        onClose: onCloseSpotlight,\n    } = useSpotlightOnFeature(FeatureCode.SpotlightEmailNotifications);\n    const shouldShowSpotlight = useSpotlightShow(show);\n\n    return (\n        <div className={classnames(['flex flex-nowrap flex-item-fluid on-mobile-flex-column', className])}>\n            {hasType && (\n                <Spotlight\n                    show={shouldShowSpotlight}\n                    onDisplayed={onDisplayed}\n                    type=\"new\"\n                    content={\n                        <>\n                            <div className=\"text-lg text-bold mb0-25\">{c('Spotlight')\n                                .t`No more missed appointments`}</div>\n                            <p className=\"m0\">\n                                {c('Spotlight')\n                                    .t`With email notifications, you decide which events to be notified about and when.`}\n                            </p>\n                        </>\n                    }\n                >\n                    <span\n                        className={classnames([\n                            'flex flex-nowrap on-mobile-mt0-5 on-mobile-mb0-5 mr0-5',\n                            isAllDay && at ? 'on-tiny-mobile-ml0' : 'w10e on-mobile-ml0',\n                        ])}\n                    >\n                        <SelectTwo\n                            value={type}\n                            onChange={({ value }) => onChange({ ...notification, type: +value })}\n                            title={c('Title').t`Select the way to send this notification`}\n                            onOpen={onCloseSpotlight}\n                            {...errorProps}\n                        >\n                            {[\n                                { text: c('Notification type').t`notification`, value: DEVICE },\n                                { text: c('Notification type').t`email`, value: EMAIL },\n                                // { text: c('Notification type').t`both notification and email`, value: BOTH },\n                            ].map(({ value, text }) => (\n                                <Option key={value} value={value} title={text} />\n                            ))}\n                        </SelectTwo>\n                    </span>\n                </Spotlight>\n            )}\n            <span className=\"flex flex-nowrap flex-item-fluid\">\n                {hasValueInput && (\n                    <span className=\"flex-item-noshrink mr0-5 w6e\">\n                        <IntegerInput\n                            id={NOTIFICATION_INPUT_ID}\n                            data-test-id=\"notification-time-input\"\n                            step={1}\n                            min={0}\n                            max={NOTIFICATION_UNITS_MAX[unit]}\n                            value={value}\n                            onChange={(newValue) => {\n                                if (newValue !== undefined && newValue === 0) {\n                                    return;\n                                }\n                                onChange({ ...notification, value: newValue });\n                            }}\n                            onBlur={() => {\n                                if (!value) {\n                                    onChange({ ...notification, value: 1 });\n                                }\n                            }}\n                            title={c('Title (number of minutes/hours/days/weeks)').t`Choose a number`}\n                            {...errorProps}\n                        />\n                    </span>\n                )}\n                <SelectTwo\n                    data-test-id=\"notification-time-dropdown\"\n                    className=\"flex-item-fluid\"\n                    value={optionsValue}\n                    onChange={({ value }) => {\n                        const optionIndex = +value;\n                        const option = options[optionIndex];\n                        if (!option) {\n                            return;\n                        }\n                        onChange({\n                            ...notification,\n                            ...option,\n                        });\n                    }}\n                    title={c('Title').t`Select when you want this notification to be sent`}\n                    {...errorProps}\n                >\n                    {textOptions.map(({ value, text }) => (\n                        <Option key={value} value={value} title={text} />\n                    ))}\n                </SelectTwo>\n            </span>\n            {isAllDay && at && (\n                <span className=\"flex on-tiny-mobile-flex-column flex-nowrap\">\n                    {isAllDay && at && (\n                        <span className=\"flex flex-nowrap flex-item-fluid flex-align-items-center on-mobile-mt0-5\">\n                            <span className=\"flex-item-noshrink ml0-5 on-mobile-ml0 mr0-5\">{c('Notification time input')\n                                .t`at`}</span>\n                            <span className=\"w8e\">\n                                <TimeInput\n                                    data-test-id=\"notification-time-at\"\n                                    value={at}\n                                    onChange={(at) => onChange({ ...notification, at })}\n                                    title={c('Title').t`Select the time to send this notification`}\n                                    {...errorProps}\n                                />\n                            </span>\n                        </span>\n                    )}\n                </span>\n            )}\n        </div>\n    );\n};\n\nexport default NotificationInput;\n","import { c } from 'ttag';\nimport { NotificationModel } from '@proton/shared/lib/interfaces/calendar/Notification';\nimport { EventModelErrors } from '@proton/shared/lib/interfaces/calendar';\nimport { addItem, removeItem, updateItem } from '@proton/shared/lib/helpers/array';\nimport { classnames, generateUID } from '../../../helpers';\nimport { ButtonLike, ErrorZone, Icon, UnderlineButton, Tooltip } from '../../../components';\nimport NotificationInput from './inputs/NotificationInput';\n\nexport const NOTIFICATION_ID = 'notifications';\n\ninterface Props {\n    notifications: NotificationModel[];\n    hasWhen?: boolean;\n    hasType?: boolean;\n    canAdd?: boolean;\n    defaultNotification: NotificationModel;\n    onChange: (value: NotificationModel[]) => void;\n    errors?: EventModelErrors;\n}\n\nconst Notifications = ({\n    notifications,\n    hasWhen,\n    hasType,\n    canAdd = true,\n    defaultNotification,\n    onChange,\n    errors,\n}: Props) => {\n    return (\n        <>\n            {notifications.map((notification, index) => {\n                return (\n                    <div className=\"mb0-5 flex flex-nowrap flex-align-items-center\" key={notification.id}>\n                        <NotificationInput\n                            hasWhen={hasWhen}\n                            hasType={hasType}\n                            notification={notification}\n                            onChange={(newNotification) => onChange(updateItem(notifications, index, newNotification))}\n                            error={errors?.notifications?.fields.includes(index) ? '' : undefined}\n                        />\n                        <Tooltip title={c('Action').t`Remove this notification`}>\n                            <ButtonLike\n                                data-test-id=\"delete-notification\"\n                                className=\"flex flex-item-noshrink ml0-5\"\n                                onClick={() => onChange(removeItem(notifications, index))}\n                                icon\n                                type=\"button\"\n                                shape=\"ghost\"\n                                color=\"norm\"\n                            >\n                                <Icon name=\"trash\" className=\"flex-item-noshrink\" />\n                                <span className=\"sr-only\">{c('Action').t`Remove this notification`}</span>\n                            </ButtonLike>\n                        </Tooltip>\n                    </div>\n                );\n            })}\n            {canAdd && (\n                <UnderlineButton\n                    className={classnames(['p0', notifications.length === 0 && 'mt0-5'])}\n                    data-test-id=\"add-notification\"\n                    title={c('Title').t`Add another notification to remind you of this event`}\n                    onClick={() =>\n                        onChange(addItem(notifications, { ...defaultNotification, id: generateUID('notification') }))\n                    }\n                >\n                    {c('Action').t`Add notification`}\n                </UnderlineButton>\n            )}\n            {errors?.notifications?.text && <ErrorZone id={NOTIFICATION_ID}>{errors.notifications.text}</ErrorZone>}\n        </>\n    );\n};\n\nexport default Notifications;\n","import { Dispatch, SetStateAction, useEffect, useState } from 'react';\nimport { c } from 'ttag';\n\nimport { getActiveAddresses } from '@proton/shared/lib/helpers/address';\nimport { VisualCalendar, CalendarViewModelFull, SubscribedCalendar } from '@proton/shared/lib/interfaces/calendar';\n\nimport { getCalendarModel } from '../calendarModal/calendarModalState';\nimport { useGetAddresses, useGetCalendarBootstrap, useLoading, useNotifications } from '../../../hooks';\n\ninterface Props {\n    calendar?: VisualCalendar | SubscribedCalendar;\n    setModel: Dispatch<SetStateAction<CalendarViewModelFull>>;\n}\n\nconst useGetCalendarSetup = ({ calendar: initialCalendar, setModel }: Props) => {\n    const getAddresses = useGetAddresses();\n    const getCalendarBootstrap = useGetCalendarBootstrap();\n\n    const [loading, withLoading] = useLoading(true);\n    const { createNotification } = useNotifications();\n\n    const [error, setError] = useState(false);\n\n    useEffect(() => {\n        const initializeEmptyCalendar = async () => {\n            const activeAdresses = getActiveAddresses(await getAddresses());\n            if (!activeAdresses.length) {\n                setError(true);\n                return createNotification({ text: c('Error').t`No valid address found`, type: 'error' });\n            }\n\n            setModel((prev) => ({\n                ...prev,\n                addressID: activeAdresses[0].ID,\n                addressOptions: activeAdresses.map(({ ID, Email = '' }) => ({ value: ID, text: Email })),\n            }));\n        };\n\n        const initializeCalendar = async () => {\n            if (!initialCalendar) {\n                throw new Error('No initial calendar');\n            }\n\n            const [{ Members, CalendarSettings }, Addresses] = await Promise.all([\n                getCalendarBootstrap(initialCalendar.ID),\n                getAddresses(),\n            ]);\n\n            const [{ Email: memberEmail } = { Email: '' }] = Members;\n            const { ID: AddressID } = Addresses.find(({ Email }) => memberEmail === Email) || {};\n\n            if (!AddressID) {\n                setError(true);\n                return createNotification({ text: c('Error').t`No valid address found`, type: 'error' });\n            }\n\n            setModel((prev) => ({\n                ...prev,\n                ...getCalendarModel({\n                    Calendar: initialCalendar,\n                    CalendarSettings,\n                    Addresses,\n                    AddressID,\n                }),\n            }));\n        };\n\n        const promise = initialCalendar ? initializeCalendar() : initializeEmptyCalendar();\n\n        void withLoading(\n            promise.catch(() => {\n                setError(true);\n            })\n        );\n    }, []);\n\n    return { loading, error };\n};\n\nexport default useGetCalendarSetup;\n","import { getPersonalCalendars } from '@proton/shared/lib/calendar/calendar';\nimport { getMemberAndAddress } from '@proton/shared/lib/calendar/members';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { omit } from '@proton/shared/lib/helpers/object';\nimport { Dispatch, SetStateAction } from 'react';\nimport { CalendarCreateData } from '@proton/shared/lib/interfaces/calendar/Api';\nimport {\n    CalendarNotificationSettings,\n    CalendarSettings,\n    SubscribedCalendar,\n    VisualCalendar,\n} from '@proton/shared/lib/interfaces/calendar';\nimport { getPrimaryKey } from '@proton/shared/lib/keys';\nimport { c } from 'ttag';\nimport {\n    createCalendar,\n    updateCalendar,\n    updateCalendarSettings,\n    updateCalendarUserSettings,\n    updateMember,\n} from '@proton/shared/lib/api/calendars';\nimport { loadModels } from '@proton/shared/lib/models/helper';\nimport { CalendarsModel } from '@proton/shared/lib/models';\nimport { setupCalendarKey } from '@proton/shared/lib/calendar/keys/setupCalendarKeys';\nimport {\n    useApi,\n    useCache,\n    useEventManager,\n    useGetAddresses,\n    useGetAddressKeys,\n    useNotifications,\n    useReadCalendarBootstrap,\n} from '../../../hooks';\nimport { useCalendarModelEventManager } from '../../eventManager';\n\nconst getHasChangedCalendarData = (calendarPayload: CalendarCreateData, calendar: VisualCalendar) => {\n    const { Name: oldName, Description: oldDescription } = calendar;\n    const { Name: newName, Description: newDescription } = calendarPayload;\n\n    return oldName !== newName || oldDescription !== newDescription;\n};\n\nconst getHasChangedCalendarMemberData = (\n    memberID: string,\n    calendarPayload: CalendarCreateData,\n    calendar: VisualCalendar\n) => {\n    const oldIndex = calendar.Members.findIndex(({ ID }) => ID === memberID);\n    if (oldIndex === -1) {\n        // we should not fall in here. If we do, assume changes are needed\n        return true;\n    }\n    const { Color: oldColor, Display: oldDisplay } = calendar.Members[oldIndex];\n    const { Color: newColor, Display: newDisplay } = calendarPayload;\n\n    return oldColor.toLowerCase() !== newColor.toLowerCase() || oldDisplay !== newDisplay;\n};\n\nconst getHasChangedCalendarNotifications = (\n    newNotifications: CalendarNotificationSettings[],\n    oldNotifications: CalendarNotificationSettings[]\n) => {\n    return (\n        newNotifications.length !== oldNotifications.length ||\n        newNotifications.some(\n            ({ Type: newType, Trigger: newTrigger }) =>\n                !oldNotifications.find(\n                    ({ Type: oldType, Trigger: oldTrigger }) => oldType === newType && oldTrigger === newTrigger\n                )\n        )\n    );\n};\n\nconst getHasChangedCalendarSettings = (\n    newSettings: Required<\n        Pick<CalendarSettings, 'DefaultEventDuration' | 'DefaultPartDayNotifications' | 'DefaultFullDayNotifications'>\n    >,\n    oldSettings?: CalendarSettings\n) => {\n    if (!oldSettings) {\n        // we should not fall in here. If we do, assume changes are needed\n        return true;\n    }\n    const {\n        DefaultEventDuration: newDuration,\n        DefaultPartDayNotifications: newPartDayNotifications,\n        DefaultFullDayNotifications: newFullDayNotifications,\n    } = newSettings;\n    const {\n        DefaultEventDuration: oldDuration,\n        DefaultPartDayNotifications: oldPartDayNotifications,\n        DefaultFullDayNotifications: oldFullDayNotifications,\n    } = oldSettings;\n    return (\n        newDuration !== oldDuration ||\n        getHasChangedCalendarNotifications(newPartDayNotifications, oldPartDayNotifications) ||\n        getHasChangedCalendarNotifications(newFullDayNotifications, oldFullDayNotifications)\n    );\n};\n\ninterface Props {\n    setCalendar: Dispatch<SetStateAction<VisualCalendar | undefined>>;\n    setError: Dispatch<SetStateAction<boolean>>;\n    defaultCalendarID?: string | null;\n    onClose?: () => void;\n    onCreateCalendar?: (id: string) => void;\n    activeCalendars?: VisualCalendar[];\n    isSubscribedCalendar?: boolean;\n}\n\nconst useGetCalendarActions = ({\n    setCalendar,\n    setError,\n    defaultCalendarID,\n    onClose,\n    onCreateCalendar,\n    activeCalendars,\n    isSubscribedCalendar = false,\n}: Props) => {\n    const api = useApi();\n    const getAddresses = useGetAddresses();\n    const { call } = useEventManager();\n    const { call: calendarCall } = useCalendarModelEventManager();\n    const cache = useCache();\n    const getAddressKeys = useGetAddressKeys();\n    const readCalendarBootstrap = useReadCalendarBootstrap();\n    const { createNotification } = useNotifications();\n\n    const handleCreateCalendar = async (\n        addressID: string,\n        calendarPayload: CalendarCreateData,\n        calendarSettingsPayload: Partial<CalendarSettings>\n    ) => {\n        const addressKeys = await getAddressKeys(addressID);\n\n        const { privateKey: primaryAddressKey } = getPrimaryKey(addressKeys) || {};\n        if (!primaryAddressKey) {\n            createNotification({ text: c('Error').t`Primary address key is not decrypted`, type: 'error' });\n            setError(true);\n            throw new Error('Missing primary key');\n        }\n\n        const {\n            Calendar,\n            Calendar: { ID: newCalendarID },\n        } = await api<{ Calendar: SubscribedCalendar }>(\n            createCalendar({\n                ...calendarPayload,\n                AddressID: addressID,\n            })\n        );\n\n        await setupCalendarKey({\n            api,\n            calendarID: newCalendarID,\n            addressID,\n            getAddressKeys,\n        }).catch((e: Error) => {\n            // Hard failure if the keys fail to setup. Force the user to reload.\n            setError(true);\n            throw e;\n        });\n\n        onCreateCalendar?.(newCalendarID);\n        // Set the calendar in case one of the following calls fails so that it ends up in the update function after this.\n        setCalendar(Calendar);\n\n        if (!isSubscribedCalendar) {\n            await Promise.all([\n                api(updateCalendarSettings(newCalendarID, calendarSettingsPayload)),\n                (() => {\n                    if (defaultCalendarID) {\n                        return;\n                    }\n                    const personalActiveCalendars = getPersonalCalendars(activeCalendars);\n                    const newDefaultCalendarID = personalActiveCalendars?.length\n                        ? personalActiveCalendars[0].ID\n                        : newCalendarID;\n                    return api(updateCalendarUserSettings({ DefaultCalendarID: newDefaultCalendarID }));\n                })(),\n            ]).catch(() => {\n                createNotification({\n                    type: 'warning',\n                    text: c('Settings update growler warning').t`Failed to update settings`,\n                });\n            });\n        }\n\n        // Refresh the calendar model in order to ensure flags are correct\n        await loadModels([CalendarsModel], { api, cache, useCache: false });\n        await call();\n\n        onClose?.();\n\n        createNotification({\n            text: isSubscribedCalendar\n                ? c('Success').t`Calendar added. It might take a few minutes to sync.`\n                : c('Success').t`Calendar created`,\n        });\n    };\n\n    const handleUpdateCalendar = async (\n        calendar: VisualCalendar,\n        calendarPayload: CalendarCreateData,\n        calendarSettingsPayload: Required<\n            Pick<\n                CalendarSettings,\n                'DefaultEventDuration' | 'DefaultPartDayNotifications' | 'DefaultFullDayNotifications'\n            >\n        >\n    ) => {\n        const calendarID = calendar.ID;\n        const { Color, Display } = calendarPayload;\n        const [{ ID: memberID }] = getMemberAndAddress(await getAddresses(), calendar.Members);\n        const hasChangedCalendarData = getHasChangedCalendarData(calendarPayload, calendar);\n        const hasChangedMemberData = getHasChangedCalendarMemberData(memberID, calendarPayload, calendar);\n        const hasChangedSettings = getHasChangedCalendarSettings(\n            calendarSettingsPayload,\n            readCalendarBootstrap(calendarID)?.CalendarSettings\n        );\n\n        await Promise.all(\n            [\n                hasChangedCalendarData && api(updateCalendar(calendarID, omit(calendarPayload, ['Color', 'Display']))),\n                hasChangedMemberData && api(updateMember(calendarID, memberID, { Display, Color })),\n                hasChangedSettings && api(updateCalendarSettings(calendarID, calendarSettingsPayload)),\n            ].filter(isTruthy)\n        );\n\n        await call();\n        await calendarCall([calendarID]);\n\n        onClose?.();\n\n        createNotification({ text: c('Success').t`Calendar updated` });\n    };\n\n    return { handleCreateCalendar, handleUpdateCalendar };\n};\n\nexport default useGetCalendarActions;\n","import { useState } from 'react';\nimport { c } from 'ttag';\n\nimport { truncate } from '@proton/shared/lib/helpers/string';\n\nimport { InlineLinkButton } from '../button';\n\ninterface Props {\n    children: string;\n    maxChars: number;\n}\n\nconst TruncatedText = ({ children, maxChars }: Props) => {\n    const [isShowingMore, setIsShowingMore] = useState(false);\n\n    return (\n        <>\n            {isShowingMore ? children : truncate(children, maxChars)}{' '}\n            {children.length > maxChars && (\n                <InlineLinkButton\n                    color=\"norm\"\n                    onClick={() => setIsShowingMore((prevState) => !prevState)}\n                    className=\"align-baseline\"\n                >\n                    {isShowingMore ? c('Action').t`Show less` : c('Action').t`Show more`}\n                </InlineLinkButton>\n            )}\n        </>\n    );\n};\n\nexport default TruncatedText;\n","import { getIsSubscribedCalendar } from '@proton/shared/lib/calendar/subscribe/helpers';\nimport { useState, useMemo, ChangeEvent } from 'react';\nimport { c } from 'ttag';\n\nimport { VisualCalendar, NotificationModel, SubscribedCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { dedupeNotifications, sortNotificationsByAscendingTrigger } from '@proton/shared/lib/calendar/alarms';\nimport { MAX_DEFAULT_NOTIFICATIONS, MAX_LENGTHS_API } from '@proton/shared/lib/calendar/constants';\n\nimport { Nullable } from '@proton/shared/lib/interfaces';\nimport {\n    ColorPicker,\n    Field,\n    Loader,\n    Option,\n    SelectTwo,\n    TextArea,\n    Form,\n    TooltipExclusive,\n    Toggle,\n    InputFieldTwo,\n    ModalTwo,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    ModalTwoContent,\n    Button,\n} from '../../../components';\nimport { getCalendarPayload, getCalendarSettingsPayload, getDefaultModel, validate } from './calendarModalState';\nimport { useLoading } from '../../../hooks';\nimport Notifications from '../notifications/Notifications';\nimport useGetCalendarSetup from '../hooks/useGetCalendarSetup';\nimport useGetCalendarActions from '../hooks/useGetCalendarActions';\nimport { TruncatedText } from '../../../components/truncatedText';\nimport { SelectChangeEvent } from '../../../components/selectTwo/select';\nimport GenericError from '../../error/GenericError';\n\nimport './CalendarModal.scss';\n\nconst URL_MAX_DISPLAY_LENGTH = 100;\n\nexport interface CalendarModalProps {\n    calendar?: VisualCalendar | SubscribedCalendar;\n    activeCalendars?: VisualCalendar[];\n    defaultCalendarID?: Nullable<string>;\n    onClose?: () => void;\n    onExit?: () => void;\n    onCreateCalendar?: (id: string) => void;\n    isOpen?: boolean;\n}\n\nexport const CalendarModal = ({\n    calendar: initialCalendar,\n    activeCalendars = [],\n    defaultCalendarID = '',\n    isOpen,\n    onClose,\n    onExit,\n    onCreateCalendar,\n}: CalendarModalProps) => {\n    const [loadingAction, withLoadingAction] = useLoading();\n\n    const [isSubmitted, setIsSubmitted] = useState(false);\n    const [error, setError] = useState(false);\n    const [calendar, setCalendar] = useState(initialCalendar);\n\n    const [model, setModel] = useState(() => getDefaultModel());\n\n    const addressText = useMemo(() => {\n        const option = model.addressOptions.find(({ value: ID }) => ID === model.addressID);\n        return (option && option.text) || '';\n    }, [model.addressID, model.addressOptions]);\n\n    const isSubscribedCalendar = initialCalendar && getIsSubscribedCalendar(initialCalendar);\n    const subscribeURL =\n        initialCalendar && getIsSubscribedCalendar(initialCalendar)\n            ? initialCalendar.SubscriptionParameters.URL\n            : undefined;\n\n    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ calendar: initialCalendar, setModel });\n    const { handleCreateCalendar, handleUpdateCalendar } = useGetCalendarActions({\n        setCalendar,\n        setError,\n        defaultCalendarID,\n        onClose,\n        onCreateCalendar,\n        activeCalendars,\n    });\n\n    const formattedModel = {\n        ...model,\n        name: model.name.trim(),\n        description: model.description.trim(),\n    };\n\n    const errors = validate(formattedModel);\n\n    const handleProcessCalendar = async () => {\n        const formattedModelWithFormattedNotifications = {\n            ...formattedModel,\n            partDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.partDayNotifications)),\n            fullDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.fullDayNotifications)),\n        };\n        const calendarPayload = getCalendarPayload(formattedModelWithFormattedNotifications);\n        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModelWithFormattedNotifications);\n        if (calendar) {\n            return handleUpdateCalendar(calendar, calendarPayload, calendarSettingsPayload);\n        }\n        return handleCreateCalendar(\n            formattedModelWithFormattedNotifications.addressID,\n            calendarPayload,\n            calendarSettingsPayload\n        );\n    };\n\n    const hasError = error || setupError;\n    const getTitle = () => {\n        if (hasError) {\n            return c('Title').t`Error`;\n        }\n\n        return initialCalendar ? c('Title').t`Edit calendar` : c('Title').t`Create calendar`;\n    };\n    const handleSubmit = () => {\n        if (hasError) {\n            window.location.reload();\n            return;\n        }\n\n        setIsSubmitted(true);\n\n        if (Object.keys(errors).length > 0) {\n            return;\n        }\n\n        void withLoadingAction(handleProcessCalendar());\n    };\n\n    const getFakeLabel = (labelText: string) => (\n        <span className=\"flex inputform-label flex-justify-space-between flex-nowrap flex-align-items-end\">\n            <span className=\"inputform-label-text\">{labelText}</span>\n        </span>\n    );\n\n    const getFakeInputTwo = ({ content, label }: { content: React.ReactNode; label: string }) => {\n        // classes taken from InputFieldTwo\n        return (\n            <div className=\"inputform-container w100\">\n                {getFakeLabel(label)}\n                <div className=\"inputform-field-container relative\">{content}</div>\n            </div>\n        );\n    };\n\n    const getAddressRow = () => {\n        if (model.calendarID) {\n            return getFakeInputTwo({ content: addressText, label: c('Label').t`Email address` });\n        }\n\n        return (\n            <InputFieldTwo\n                as={SelectTwo}\n                id=\"calendar-address-select\"\n                value={model.addressID}\n                // @ts-ignore\n                onChange={({ value }: SelectChangeEvent<string>) => setModel({ ...model, addressID: value })}\n                label={c('Label').t`Default email address`}\n            >\n                {model.addressOptions.map(({ value, text }) => (\n                    <Option key={value} value={value} title={text} />\n                ))}\n            </InputFieldTwo>\n        );\n    };\n\n    return (\n        <TooltipExclusive>\n            <ModalTwo\n                size=\"large\"\n                fullscreenOnMobile\n                className=\"w100\"\n                open={isOpen}\n                onClose={onClose}\n                as={Form}\n                dense\n                onSubmit={() => {\n                    if (!loadingAction) {\n                        handleSubmit();\n                    }\n                }}\n                onExit={onExit}\n            >\n                {loadingSetup ? (\n                    <Loader />\n                ) : (\n                    <>\n                        <ModalTwoHeader title={getTitle()} />\n                        <ModalTwoContent className=\"calendar-modal-content\">\n                            {hasError ? (\n                                <GenericError />\n                            ) : (\n                                <>\n                                    <InputFieldTwo\n                                        id=\"calendar-name-input\"\n                                        label={c('Label').t`Name`}\n                                        value={model.name}\n                                        error={isSubmitted && errors.name}\n                                        maxLength={MAX_LENGTHS_API.CALENDAR_NAME}\n                                        disableChange={loadingAction}\n                                        placeholder={c('Placeholder').t`Add a calendar name`}\n                                        onChange={({ target }: ChangeEvent<HTMLInputElement>) =>\n                                            setModel({ ...model, name: target.value })\n                                        }\n                                        autoFocus\n                                    />\n                                    <InputFieldTwo\n                                        as={ColorPicker}\n                                        label={c('Label').t`Color`}\n                                        id=\"calendar-color\"\n                                        color={model.color}\n                                        onChange={(color: string) => setModel({ ...model, color })}\n                                    />\n                                    {getAddressRow()}\n                                    <div className=\"flex flex-nowrap flex-align-items-center\">\n                                        {getFakeLabel(c('Label').t`Display`)}\n                                        <Field className=\"ml1\">\n                                            <Toggle\n                                                id=\"calendar-display-toggle\"\n                                                className=\"p0\"\n                                                checked={model.display}\n                                                onChange={({ target }: ChangeEvent<HTMLInputElement>) =>\n                                                    setModel({ ...model, display: target.checked })\n                                                }\n                                            />\n                                        </Field>\n                                    </div>\n                                    <InputFieldTwo\n                                        as={TextArea}\n                                        label={c('Label').t`Description`}\n                                        autoGrow\n                                        id=\"calendar-description-textarea\"\n                                        value={model.description}\n                                        placeholder={c('Placeholder').t`Add a calendar description`}\n                                        onChange={({ target }: ChangeEvent<HTMLTextAreaElement>) =>\n                                            setModel({ ...model, description: target.value })\n                                        }\n                                        maxLength={MAX_LENGTHS_API.CALENDAR_DESCRIPTION}\n                                        isSubmitted={isSubmitted}\n                                        error={errors.description}\n                                    />\n                                    {!isSubscribedCalendar && (\n                                        <InputFieldTwo\n                                            as={SelectTwo}\n                                            label={c('Label').t`Default event duration`}\n                                            id=\"duration-select\"\n                                            data-test-id=\"create-calendar/event-settings:event-duration\"\n                                            value={model.duration}\n                                            // @ts-ignore\n                                            onChange={({ value }: SelectChangeEvent<string>) =>\n                                                setModel({ ...model, duration: +value })\n                                            }\n                                        >\n                                            {[\n                                                { text: c('Duration').t`30 minutes`, value: 30 },\n                                                { text: c('Duration').t`60 minutes`, value: 60 },\n                                                { text: c('Duration').t`90 minutes`, value: 90 },\n                                                { text: c('Duration').t`120 minutes`, value: 120 },\n                                            ].map(({ value, text }) => (\n                                                <Option key={value} value={value} title={text} />\n                                            ))}\n                                        </InputFieldTwo>\n                                    )}\n                                    {subscribeURL &&\n                                        getFakeInputTwo({\n                                            content: (\n                                                <span className=\"text-break-all\">\n                                                    <TruncatedText maxChars={URL_MAX_DISPLAY_LENGTH}>\n                                                        {subscribeURL}\n                                                    </TruncatedText>\n                                                </span>\n                                            ),\n                                            label: c('Label').t`URL`,\n                                        })}\n                                    {!isSubscribedCalendar && (\n                                        <>\n                                            <InputFieldTwo\n                                                as={Notifications}\n                                                label={c('Label').t`Default notifications`}\n                                                data-test-id=\"create-calendar/event-settings:default-notification\"\n                                                hasType\n                                                notifications={model.partDayNotifications}\n                                                canAdd={model.partDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}\n                                                defaultNotification={model.defaultPartDayNotification}\n                                                onChange={(notifications: NotificationModel[]) => {\n                                                    setModel({\n                                                        ...model,\n                                                        partDayNotifications: notifications,\n                                                    });\n                                                }}\n                                            />\n\n                                            <InputFieldTwo\n                                                as={Notifications}\n                                                label={c('Label').t`Default full day notifications`}\n                                                data-test-id=\"create-calendar/event-settings:default-full-day-notification\"\n                                                hasType\n                                                notifications={model.fullDayNotifications}\n                                                canAdd={model.fullDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}\n                                                defaultNotification={model.defaultFullDayNotification}\n                                                onChange={(notifications: NotificationModel[]) => {\n                                                    setModel({\n                                                        ...model,\n                                                        fullDayNotifications: notifications,\n                                                    });\n                                                }}\n                                            />\n                                        </>\n                                    )}\n                                </>\n                            )}\n                        </ModalTwoContent>\n                        <ModalTwoFooter>\n                            {hasError ? (\n                                <Button onClick={() => window.location.reload()} className=\"mlauto\" color=\"norm\">{c(\n                                    'Action'\n                                ).t`Close`}</Button>\n                            ) : (\n                                <>\n                                    <Button onClick={onClose} disabled={loadingAction}>\n                                        {c('Action').t`Cancel`}\n                                    </Button>\n                                    <Button loading={loadingAction} type=\"submit\" color=\"norm\">{c('Action')\n                                        .t`Save`}</Button>\n                                </>\n                            )}\n                        </ModalTwoFooter>\n                    </>\n                )}\n            </ModalTwo>\n        </TooltipExclusive>\n    );\n};\n\nexport default CalendarModal;\n","import { Calendar } from './Calendar';\nimport { WeekStartsOn } from '../../date-fns-utc/interface';\n\nexport enum EXPORT_STEPS {\n    EXPORTING,\n    FINISHED,\n}\n\nexport enum EXPORT_ERRORS {\n    NETWORK_ERROR,\n}\n\nexport enum EXPORT_EVENT_ERROR_TYPES {\n    DECRYPTION_ERROR,\n    PASSWORD_RESET,\n}\n\nexport type ExportError = [string, EXPORT_EVENT_ERROR_TYPES];\n\nexport interface ExportCalendarModel {\n    step: EXPORT_STEPS;\n    totalFetched: number;\n    totalProcessed: number;\n    totalToProcess: number;\n    calendar: Calendar;\n    exportErrors: ExportError[];\n    error?: EXPORT_ERRORS;\n    weekStartsOn: WeekStartsOn;\n}\n","import { getVtimezones } from '@proton/shared/lib/api/calendars';\nimport { parse } from '@proton/shared/lib/calendar/vcal';\nimport { GET_VTIMEZONES_API_LIMIT } from '@proton/shared/lib/constants';\nimport { chunk, unique } from '@proton/shared/lib/helpers/array';\nimport { GetVTimezonesMap, VTimezoneObject } from '@proton/shared/lib/interfaces/hooks/GetVTimezonesMap';\nimport { VcalVtimezoneComponent } from '@proton/shared/lib/interfaces/calendar';\nimport { SimpleMap } from '@proton/shared/lib/interfaces/utils';\nimport { useCallback } from 'react';\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport { getIsRecordInvalid, getPromiseValue } from './useCachedModelResult';\n\nconst CACHE_KEY = 'VTIMEZONES';\n\nexport const useGetVtimezonesMap = () => {\n    const api = useApi();\n    const cache = useCache();\n\n    const getVTimezonesMap = useCallback(\n        async (tzids: string[]) => {\n            const uniqueTzids = unique(tzids.filter((tzid) => tzid.toLowerCase() !== 'utc'));\n            const encodedTzids = uniqueTzids.map((tzid) => encodeURIComponent(tzid));\n\n            if (!uniqueTzids.length) {\n                return Promise.resolve({});\n            }\n\n            const batchedTimezones = chunk(encodedTzids, GET_VTIMEZONES_API_LIMIT);\n\n            return (\n                await Promise.all(\n                    batchedTimezones.map(async (batch) => {\n                        const { Timezones = {} } = await api<{ Timezones: SimpleMap<string> }>(getVtimezones(batch));\n\n                        return tzids.reduce<SimpleMap<VTimezoneObject>>((acc, tzid) => {\n                            const vtimezoneString = Timezones[tzid];\n\n                            if (vtimezoneString) {\n                                acc[tzid] = {\n                                    vtimezoneString,\n                                    vtimezone: parse(vtimezoneString) as VcalVtimezoneComponent,\n                                };\n                            }\n\n                            return acc;\n                        }, {});\n                    })\n                )\n            ).reduce<SimpleMap<VTimezoneObject>>((acc, curr) => ({ ...acc, ...curr }), {});\n        },\n        [api, cache]\n    );\n\n    return useCallback<GetVTimezonesMap>(\n        (tzids: string[]) => {\n            if (!cache.has(CACHE_KEY)) {\n                cache.set(CACHE_KEY, new Map());\n            }\n            const subCache = cache.get(CACHE_KEY);\n            const missing = tzids.filter((tzid) => {\n                return getIsRecordInvalid(subCache.get(tzid));\n            });\n            const promise = getVTimezonesMap(missing);\n            const miss = async (tzid: string) => {\n                const map = await promise;\n                return map[tzid];\n            };\n            return Promise.all(\n                tzids.map(async (tzid) => {\n                    const result = await getPromiseValue(subCache, tzid, miss);\n                    return {\n                        tzid,\n                        result: result as VTimezoneObject,\n                    };\n                })\n            ).then((result) => {\n                return result.reduce<SimpleMap<VTimezoneObject>>((acc, { tzid, result }) => {\n                    acc[tzid] = result;\n                    return acc;\n                }, {});\n            });\n        },\n        [cache, getVTimezonesMap]\n    );\n};\n","import { OpenPGPKey } from 'pmcrypto';\nimport { unique } from '../helpers/array';\nimport { canonizeInternalEmail } from '../helpers/email';\nimport isTruthy from '../helpers/isTruthy';\nimport { Address } from '../interfaces';\nimport { CalendarEvent, CalendarEventData } from '../interfaces/calendar';\nimport { GetAddressKeys } from '../interfaces/hooks/GetAddressKeys';\nimport { GetEncryptionPreferences } from '../interfaces/hooks/GetEncryptionPreferences';\nimport { SimpleMap } from '../interfaces/utils';\nimport { splitKeys } from '../keys';\nimport { CALENDAR_CARD_TYPE } from './constants';\n\nconst { SIGNED, ENCRYPTED_AND_SIGNED } = CALENDAR_CARD_TYPE;\n\nexport const withNormalizedAuthor = (x: CalendarEventData) => ({\n    ...x,\n    Author: canonizeInternalEmail(x.Author),\n});\nexport const withNormalizedAuthors = (x: CalendarEventData[]) => {\n    if (!x) {\n        return [];\n    }\n    return x.map(withNormalizedAuthor);\n};\n\ninterface GetAuthorPublicKeysMap {\n    event: CalendarEvent;\n    addresses: Address[];\n    getAddressKeys: GetAddressKeys;\n    getEncryptionPreferences: GetEncryptionPreferences;\n}\n\nexport const getAuthorPublicKeysMap = async ({\n    event,\n    addresses,\n    getAddressKeys,\n    getEncryptionPreferences,\n}: GetAuthorPublicKeysMap) => {\n    const publicKeysMap: SimpleMap<OpenPGPKey | OpenPGPKey[]> = {};\n    const authors = unique(\n        [...event.SharedEvents, ...event.CalendarEvents]\n            .map(({ Author, Type }) => {\n                if (![SIGNED, ENCRYPTED_AND_SIGNED].includes(Type)) {\n                    // no need to fetch keys in this case\n                    return;\n                }\n                return canonizeInternalEmail(Author);\n            })\n            .filter(isTruthy)\n    );\n    const normalizedAddresses = addresses.map((address) => ({\n        ...address,\n        normalizedEmailAddress: canonizeInternalEmail(address.Email),\n    }));\n    const promises = authors.map(async (author) => {\n        const ownAddress = normalizedAddresses.find(({ normalizedEmailAddress }) => normalizedEmailAddress === author);\n        if (ownAddress) {\n            const result = await getAddressKeys(ownAddress.ID);\n            publicKeysMap[author] = splitKeys(result).publicKeys;\n        } else {\n            const { pinnedKeys } = await getEncryptionPreferences(author);\n            publicKeysMap[author] = pinnedKeys;\n        }\n    });\n    await Promise.all(promises);\n\n    return publicKeysMap;\n};\n","import { VcalDateOrDateTimeValue, VcalDateTimeValue, VcalDays } from '../../interfaces/calendar/VcalModel';\nimport { END_TYPE, MONTHLY_TYPE } from '../constants';\nimport { getDayAndSetpos, getIsStandardBydayArray } from '../rrule';\nimport { dayToNumericDay, propertyToUTCDate } from '../vcalConverter';\nimport { convertUTCDateTimeToZone, fromUTCDate } from '../../date/timezone';\nimport { unique } from '../../helpers/array';\n\nexport const getEndType = (count?: number, until?: VcalDateOrDateTimeValue) => {\n    // count and until cannot occur at the same time (see https://tools.ietf.org/html/rfc5545#page-37)\n    if (count && count >= 1) {\n        return END_TYPE.AFTER_N_TIMES;\n    }\n    if (until) {\n        return END_TYPE.UNTIL;\n    }\n    return END_TYPE.NEVER;\n};\n\nexport const getMonthType = (byday?: string | string[], bysetpos?: number | number[]) => {\n    if (typeof byday === 'string' && !Array.isArray(bysetpos)) {\n        const { setpos } = getDayAndSetpos(byday, bysetpos);\n        if (setpos) {\n            return setpos > 0 ? MONTHLY_TYPE.ON_NTH_DAY : MONTHLY_TYPE.ON_MINUS_NTH_DAY;\n        }\n    }\n    return MONTHLY_TYPE.ON_MONTH_DAY;\n};\n\nexport const getUntilDate = (until?: VcalDateOrDateTimeValue, startTzid?: string) => {\n    if (!until) {\n        return undefined;\n    }\n    if (!(until as Vcal