ng}`,\n            `Every ${interval} years, ${untilString}`,\n            interval\n        );\n    }\n};\n\nexport const getFrequencyString = (\n    rruleValue: VcalRrulePropertyValue,\n    dtstart: VcalDateOrDateTimeProperty,\n    { weekStartsOn, locale }: Pick<GetTimezonedFrequencyStringOptions, 'weekStartsOn' | 'locale'>\n) => {\n    const { freq, count, until } = rruleValue;\n\n    const isSimple = getIsRruleSimple(rruleValue);\n    const isCustom = getIsRruleCustom(rruleValue);\n    const startFakeUtcDate = toUTCDate(dtstart.value);\n    const startDay = startFakeUtcDate.getUTCDay();\n    const end = {\n        type: getEndType(count, until),\n        count,\n        until: getUntilDate(until, getPropertyTzid(dtstart)),\n    };\n\n    if (!isSimple) {\n        if (!isCustom) {\n            if (freq === FREQUENCY.DAILY) {\n                return c('Info').t`Custom daily`;\n            }\n            if (freq === FREQUENCY.WEEKLY) {\n                return c('Info').t`Custom weekly`;\n            }\n            if (freq === FREQUENCY.MONTHLY) {\n                return c('Info').t`Custom monthly`;\n            }\n            if (freq === FREQUENCY.YEARLY) {\n                return c('Info').t`Custom yearly`;\n            }\n            return c('Info').t`Custom`;\n        }\n        if (freq === FREQUENCY.DAILY) {\n            return getCustomDailyString(rruleValue, end, locale);\n        }\n        if (freq === FREQUENCY.WEEKLY) {\n            return getCustomWeeklyString(rruleValue, end, weekStartsOn, startFakeUtcDate, locale);\n        }\n        if (freq === FREQUENCY.MONTHLY) {\n            const { byday, bysetpos } = rruleValue;\n            const monthType = getMonthType(byday, bysetpos);\n            return getCustomMonthlyString(rruleValue, end, monthType, startFakeUtcDate, locale);\n        }\n        if (freq === FREQUENCY.YEARLY) {\n            return getCustomYearlyString(rruleValue, end, locale);\n        }\n    }\n    if (freq === FREQUENCY.DAILY) {\n        return c('Info').t`Daily`;\n    }\n    if (freq === FREQUENCY.WEEKLY) {\n        if (startDay === 0) {\n            return c('Weekly recurring event, frequency').t`Weekly on Sunday`;\n        }\n        if (startDay === 1) {\n            return c('Weekly recurring event, frequency').t`Weekly on Monday`;\n        }\n        if (startDay === 2) {\n            return c('Weekly recurring event, frequency').t`Weekly on Tuesday`;\n        }\n        if (startDay === 3) {\n            return c('Weekly recurring event, frequency').t`Weekly on Wednesday`;\n        }\n        if (startDay === 4) {\n            return c('Weekly recurring event, frequency').t`Weekly on Thursday`;\n        }\n        if (startDay === 5) {\n            return c('Weekly recurring event, frequency').t`Weekly on Friday`;\n        }\n        if (startDay === 6) {\n            return c('Weekly recurring event, frequency').t`Weekly on Saturday`;\n        }\n    }\n    if (freq === FREQUENCY.MONTHLY) {\n        const { byday, bysetpos } = rruleValue;\n        const monthType = getMonthType(byday, bysetpos);\n        const onDayString = getOnDayString(startFakeUtcDate, monthType);\n        return c('Info').t`Monthly ${onDayString}`;\n    }\n    if (freq === FREQUENCY.YEARLY) {\n        return c('Info').t`Yearly`;\n    }\n    return '';\n};\n\nexport const getTimezonedFrequencyString = (\n    rrule: VcalRruleProperty | undefined,\n    dtstart: VcalDateOrDateTimeProperty,\n    options: GetTimezonedFrequencyStringOptions\n) => {\n    if (!rrule) {\n        return '';\n    }\n    const { value: rruleValue } = rrule;\n    const startTzid = getPropertyTzid(dtstart);\n    const { currentTzid } = options;\n\n    if (!startTzid || startTzid === currentTzid) {\n        return getFrequencyString(rruleValue, dtstart, options);\n    }\n\n    const isTimezoneStringNeeded = (() => {\n        const { freq, count, until, byday } = rruleValue;\n\n        const isCustom = getIsRruleCustom(rruleValue);\n        const endType = getEndType(count, until);\n\n        if (!freq) {\n            return false;\n        }\n        if ([FREQUENCY.DAILY, FREQUENCY.YEARLY].includes(freq as FREQUENCY)) {\n            return isCustom && endType === END_TYPE.UNTIL;\n        }\n        if (freq === FREQUENCY.WEEKLY) {\n            const days = getWeeklyDays(byday);\n            const hasCustomUntil = isCustom && endType === END_TYPE.UNTIL;\n            const hasDays = days.length !== 7;\n            return hasCustomUntil || hasDays;\n        }\n        if (freq === FREQUENCY.MONTHLY) {\n            return true;\n        }\n        return false;\n    })();\n\n    const timezoneString = isTimezoneStringNeeded ? ` (${startTzid})` : '';\n    return getFrequencyString(rruleValue, dtstart, options) + timezoneString;\n};\n","import { c } from 'ttag';\nimport { arrayToHexString, binaryStringToArray, getKeys, getSignature } from 'pmcrypto';\nimport { fromUnixTime } from 'date-fns';\nimport { queryEvents } from '../../api/calendars';\nimport { wait } from '../../helpers/promise';\nimport { partition, unique } from '../../helpers/array';\nimport { Address, Api, Key } from '../../interfaces';\nimport {\n    CalendarEvent,\n    CalendarEventWithMetadata,\n    EXPORT_EVENT_ERROR_TYPES,\n    ExportError,\n    VcalVeventComponent,\n} from '../../interfaces/calendar';\nimport { CalendarExportEventsQuery } from '../../interfaces/calendar/Api';\nimport { GetAddressKeys } from '../../interfaces/hooks/GetAddressKeys';\nimport { GetCalendarEventPersonal } from '../../interfaces/hooks/GetCalendarEventPersonal';\nimport { GetCalendarKeys } from '../../interfaces/hooks/GetCalendarKeys';\nimport { withNormalizedAuthors } from '../author';\nimport { readCalendarEvent, readSessionKeys } from '../deserialize';\nimport { getCalendarEventDecryptionKeys } from '../keys/getCalendarEventDecryptionKeys';\nimport { fromRruleString } from '../vcal';\nimport { getTimezonedFrequencyString } from '../integration/getFrequencyString';\nimport { getDateProperty } from '../vcalConverter';\nimport {\n    convertUTCDateTimeToZone,\n    formatGMTOffsetAbbreviation,\n    fromUTCDate,\n    getTimezoneOffset,\n    toUTCDate,\n} from '../../date/timezone';\nimport { dateLocale } from '../../i18n';\nimport { WeekStartsOn } from '../../date-fns-utc/interface';\nimport { SECOND } from '../../constants';\nimport formatUTC from '../../date-fns-utc/format';\nimport { withSummary } from '../veventHelper';\n\nexport const getHasCalendarEventMatchingSigningKeys = async (event: CalendarEvent, keys: Key[]) => {\n    // OpenPGP types are broken\n    const allEventSignatures = [...event.SharedEvents, ...event.CalendarEvents, ...event.AttendeesEvents].flatMap(\n        (event) => (event.Signature ? [event.Signature] : [])\n    );\n\n    const allSignaturesPromises = Promise.all(allEventSignatures.map((signature) => getSignature(signature)));\n    const allKeyIdsPromises = Promise.all(\n        keys.map(async (key) => {\n            const [signingKey] = await getKeys(key.PrivateKey);\n            // @ts-ignore\n            return arrayToHexString(binaryStringToArray(signingKey.getKeyId().bytes as string));\n        })\n    );\n    const [allSignatures, allKeyIds] = await Promise.all([allSignaturesPromises, allKeyIdsPromises]);\n    const allSignatureKeyIds: string[] = unique(\n        // @ts-ignore\n        allSignatures.flatMap((signature) => signature.packets.map(({ issuerKeyId }) => issuerKeyId.toHex()))\n    );\n    return allSignatureKeyIds.some((id) => allKeyIds.includes(id));\n};\n\nexport interface GetErrorProps {\n    event: CalendarEventWithMetadata;\n    errorType: EXPORT_EVENT_ERROR_TYPES;\n    weekStartsOn: WeekStartsOn;\n    defaultTzid: string;\n}\n\nexport const getError = ({ event, errorType, weekStartsOn, defaultTzid }: GetErrorProps): ExportError => {\n    const { StartTime, RRule, FullDay } = event;\n    const startDate = new Date(StartTime * SECOND);\n    const fakeUTCStartDate = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(startDate), defaultTzid));\n    const startDateString = formatUTC(fakeUTCStartDate, FullDay ? 'P' : 'Pp', { locale: dateLocale });\n    const { offset } = getTimezoneOffset(startDate, defaultTzid);\n    const offsetString = formatGMTOffsetAbbreviation(offset);\n    const timeString = `${startDateString}${FullDay ? '' : ` ${offsetString}`}`;\n\n    const rruleValueFromString = RRule ? fromRruleString(RRule) : undefined;\n    const utcStartDate = fromUnixTime(StartTime);\n    const dtstart = getDateProperty(fromUTCDate(utcStartDate));\n\n    if (rruleValueFromString) {\n        const rruleString = getTimezonedFrequencyString({ value: rruleValueFromString }, dtstart, {\n            currentTzid: defaultTzid,\n            locale: dateLocale,\n            weekStartsOn,\n        });\n\n        return [c('Error when exporting event from calendar').t`Event from ${timeString}, ${rruleString}`, errorType];\n    }\n\n    return [c('Error when exporting event from calendar').t`Event @ ${timeString}`, errorType];\n};\n\nconst getDecryptionErrorType = async (event: CalendarEventWithMetadata, keys: Key[]) => {\n    try {\n        const HasMatchingKeys = await getHasCalendarEventMatchingSigningKeys(event, keys);\n        if (HasMatchingKeys) {\n            return EXPORT_EVENT_ERROR_TYPES.PASSWORD_RESET;\n        }\n        return EXPORT_EVENT_ERROR_TYPES.DECRYPTION_ERROR;\n    } catch {\n        return EXPORT_EVENT_ERROR_TYPES.DECRYPTION_ERROR;\n    }\n};\n\nconst decryptEvent = async ({\n    event,\n    defaultTzid,\n    weekStartsOn,\n    addresses,\n    getAddressKeys,\n    getCalendarKeys,\n    getCalendarEventPersonal,\n    memberID,\n}: {\n    event: CalendarEventWithMetadata;\n    addresses: Address[];\n    getAddressKeys: GetAddressKeys;\n    getCalendarKeys: GetCalendarKeys;\n    getCalendarEventPersonal: GetCalendarEventPersonal;\n    memberID: string;\n    weekStartsOn: WeekStartsOn;\n    defaultTzid: string;\n}) => {\n    const defaultParams = { event, defaultTzid, weekStartsOn };\n    const [eventDecryptionKeys, eventPersonalMap] = await Promise.all([\n        getCalendarEventDecryptionKeys({\n            calendarEvent: event,\n            getAddressKeys,\n            getCalendarKeys,\n        }),\n        getCalendarEventPersonal(event),\n    ]);\n\n    try {\n        const personalVevent = memberID ? eventPersonalMap[memberID] : undefined;\n        const valarms = personalVevent ? personalVevent.veventComponent : {};\n\n        const [sharedSessionKey, calendarSessionKey] = await readSessionKeys({\n            calendarEvent: event,\n            privateKeys: eventDecryptionKeys,\n        });\n\n        const { IsOrganizer, SharedEvents, CalendarEvents, AttendeesEvents, Attendees, AddressKeyPacket, AddressID } =\n            event;\n        const { veventComponent } = await readCalendarEvent({\n            isOrganizer: !!IsOrganizer,\n            event: {\n                SharedEvents: withNormalizedAuthors(SharedEvents),\n                CalendarEvents: withNormalizedAuthors(CalendarEvents),\n                AttendeesEvents: withNormalizedAuthors(AttendeesEvents),\n                Attendees: Attendees,\n            },\n            sharedSessionKey,\n            calendarSessionKey,\n            addresses,\n            encryptingAddressID: AddressKeyPacket && AddressID ? AddressID : undefined,\n        });\n        const veventWithAlarmsAndSummary: VcalVeventComponent = {\n            ...valarms,\n            // SUMMARY is mandatory in a PUBLISH ics\n            ...withSummary(veventComponent),\n        };\n\n        return veventWithAlarmsAndSummary;\n    } catch (error: any) {\n        const inactiveKeys = addresses.flatMap(({ Keys }) => Keys.filter(({ Active }) => !Active));\n        return getError({\n            ...defaultParams,\n            errorType: await getDecryptionErrorType(event, inactiveKeys),\n        });\n    }\n};\n\ninterface ProcessData {\n    calendarID: string;\n    addresses: Address[];\n    getAddressKeys: GetAddressKeys;\n    getCalendarKeys: GetCalendarKeys;\n    getCalendarEventPersonal: GetCalendarEventPersonal;\n    api: Api;\n    signal: AbortSignal;\n    onProgress: (\n        calendarEvents: CalendarEventWithMetadata[],\n        veventComponents: VcalVeventComponent[],\n        exportErrors: ExportError[]\n    ) => void;\n    totalToProcess: number;\n    memberID: string;\n    weekStartsOn: WeekStartsOn;\n    defaultTzid: string;\n}\n\nexport const processInBatches = async ({\n    calendarID,\n    api,\n    signal,\n    onProgress,\n    addresses,\n    getCalendarEventPersonal,\n    totalToProcess,\n    memberID,\n    getAddressKeys,\n    getCalendarKeys,\n    weekStartsOn,\n    defaultTzid,\n}: ProcessData): Promise<[VcalVeventComponent[], ExportError[], number]> => {\n    const PAGE_SIZE = 10;\n    const DELAY = 100;\n    const batchesLength = Math.ceil(totalToProcess / PAGE_SIZE);\n    const processed: VcalVeventComponent[] = [];\n    const errors: ExportError[] = [];\n    const promises: Promise<void>[] = [];\n    let totalEventsFetched = 0;\n\n    let lastId;\n\n    for (let i = 0; i < batchesLength; i++) {\n        if (signal.aborted) {\n            return [[], [], totalToProcess];\n        }\n\n        const params: CalendarExportEventsQuery = {\n            PageSize: PAGE_SIZE,\n            BeginID: lastId,\n        };\n\n        const [{ Events }] = await Promise.all([\n            api<{ Events: CalendarEventWithMetadata[] }>(queryEvents(calendarID, params)),\n            wait(DELAY),\n        ]);\n\n        if (signal.aborted) {\n            return [[], [], totalToProcess];\n        }\n        onProgress(Events, [], []);\n\n        const { length: eventsLength } = Events;\n\n        lastId = Events[eventsLength - 1].ID;\n\n        totalEventsFetched += eventsLength;\n\n        const promise = Promise.all(\n            Events.map((event) =>\n                decryptEvent({\n                    event,\n                    defaultTzid,\n                    weekStartsOn,\n                    addresses,\n                    getAddressKeys,\n                    getCalendarKeys,\n                    getCalendarEventPersonal,\n                    memberID,\n                })\n            )\n        )\n            .then((veventsOrErrors) => {\n                const [veventComponents, exportErrors] = partition<VcalVeventComponent, ExportError>(\n                    veventsOrErrors,\n                    (item): item is VcalVeventComponent => !Array.isArray(item)\n                );\n\n                processed.push(...veventComponents);\n                errors.push(...exportErrors);\n                onProgress([], veventComponents, exportErrors);\n            })\n            .catch((e) => {\n                const exportErrors: ExportError[] = Events.map(() => [\n                    e.message,\n                    EXPORT_EVENT_ERROR_TYPES.DECRYPTION_ERROR,\n                ]);\n                errors.push(...exportErrors);\n                onProgress([], [], exportErrors);\n            });\n\n        promises.push(promise);\n    }\n\n    await Promise.all(promises);\n\n    return [processed, errors, totalEventsFetched];\n};\n","import { useCallback } from 'react';\nimport { getPersonalPartMap, readPersonalPart } from '@proton/shared/lib/calendar/deserialize';\nimport { splitKeys } from '@proton/shared/lib/keys';\nimport { getAddressesMembersMap } from '@proton/shared/lib/keys/calendarKeys';\nimport {\n    CalendarEvent,\n    DecryptedPersonalVeventMapResult,\n    DecryptedVeventResult,\n} from '@proton/shared/lib/interfaces/calendar';\nimport { useGetAddresses } from './useAddresses';\nimport { useGetAddressKeys } from './useGetAddressKeys';\nimport { useGetCalendarBootstrap } from './useGetCalendarBootstrap';\n\nconst useGetCalendarEventPersonal = () => {\n    const getCalendarBootstrap = useGetCalendarBootstrap();\n    const getAddresses = useGetAddresses();\n    const getAddressKeys = useGetAddressKeys();\n\n    return useCallback(\n        async (Event: CalendarEvent) => {\n            const [Addresses, { Members }] = await Promise.all([\n                getAddresses(),\n                getCalendarBootstrap(Event.CalendarID),\n            ]);\n\n            const addressesMembersMap = getAddressesMembersMap(Members, Addresses);\n            const personalPartMap = getPersonalPartMap(Event);\n            const personalPartMapKeys = Object.keys(personalPartMap);\n            const result: DecryptedVeventResult[] = await Promise.all(\n                personalPartMapKeys.map(async (memberID) => {\n                    const { ID: addressID } = addressesMembersMap[memberID] || {};\n                    if (!addressID) {\n                        return undefined;\n                    }\n                    const personalPart = personalPartMap[memberID];\n                    const addressKeys = await getAddressKeys(addressID);\n                    return readPersonalPart(personalPart, splitKeys(addressKeys).publicKeys).catch((e) => e);\n                })\n            );\n\n            return personalPartMapKeys.reduce<DecryptedPersonalVeventMapResult>((acc, memberID, i) => {\n                acc[memberID] = result[i];\n                return acc;\n            }, {});\n        },\n        [getAddresses, getAddressKeys, getCalendarBootstrap]\n    );\n};\n\nexport default useGetCalendarEventPersonal;\n","import { processInBatches } from '@proton/shared/lib/calendar/export/export';\nimport { Dispatch, SetStateAction, useEffect } from 'react';\nimport { c } from 'ttag';\n\nimport {\n    CalendarEventWithMetadata,\n    EXPORT_ERRORS,\n    EXPORT_STEPS,\n    ExportCalendarModel,\n    ExportError,\n    VcalVeventComponent,\n} from '@proton/shared/lib/interfaces/calendar';\n\nimport { getEventsCount } from '@proton/shared/lib/api/calendars';\nimport { DynamicProgress } from '../../../components';\nimport useGetCalendarEventPersonal from '../../../hooks/useGetCalendarEventPersonal';\nimport {\n    useGetCalendarInfo,\n    useApi,\n    useGetAddresses,\n    useGetAddressKeys,\n    useGetCalendarKeys,\n    useGetCalendarUserSettings,\n} from '../../../hooks';\n\ninterface Props {\n    model: ExportCalendarModel;\n    setModel: Dispatch<SetStateAction<ExportCalendarModel>>;\n    onFinish: (vevents: VcalVeventComponent[], exportErrors: ExportError[], keepError?: boolean) => void;\n}\nconst ExportingModalContent = ({ model, setModel, onFinish }: Props) => {\n    const api = useApi();\n    const getAddresses = useGetAddresses();\n    const getCalendarInfo = useGetCalendarInfo();\n    const getCalendarEventPersonal = useGetCalendarEventPersonal();\n    const getAddressKeys = useGetAddressKeys();\n    const getCalendarKeys = useGetCalendarKeys();\n    const getCalendarUserSettings = useGetCalendarUserSettings();\n\n    const { totalFetched, totalToProcess, totalProcessed, exportErrors } = model;\n    const totalErrors = exportErrors.length;\n\n    useEffect(() => {\n        // Prepare api for allowing cancellation in the middle of the export\n        const abortController = new AbortController();\n        const { signal } = abortController;\n\n        const apiWithAbort: <T>(config: object) => Promise<T> = (config) => api({ ...config, signal });\n\n        const setModelWithAbort = (set: (currentModel: ExportCalendarModel) => ExportCalendarModel) => {\n            if (signal.aborted) {\n                return;\n            }\n            setModel(set);\n        };\n\n        const handleExportProgress = (\n            events: CalendarEventWithMetadata[],\n            veventComponents: VcalVeventComponent[],\n            exportErrors: ExportError[]\n        ) => {\n            setModelWithAbort((currentModel) => ({\n                ...currentModel,\n                totalFetched: currentModel.totalFetched + events.length,\n                totalProcessed: currentModel.totalProcessed + veventComponents.length,\n                exportErrors: [...currentModel.exportErrors, ...exportErrors],\n            }));\n        };\n\n        const process = async () => {\n            try {\n                const [addresses, { memberID }, calendarUserSettings] = await Promise.all([\n                    getAddresses(),\n                    getCalendarInfo(model.calendar.ID),\n                    getCalendarUserSettings(),\n                ]);\n\n                if (!addresses) {\n                    throw new Error('No addresses');\n                }\n\n                const { Total: totalToProcess } = await api<{ Total: number }>(getEventsCount(model.calendar.ID));\n\n                setModelWithAbort((currentModel) => ({\n                    ...currentModel,\n                    totalToProcess,\n                }));\n\n                const [exportedEvents, exportErrors, totalEventsFetched] = await processInBatches({\n                    calendarID: model.calendar.ID,\n                    addresses,\n                    api: apiWithAbort,\n                    signal,\n                    onProgress: handleExportProgress,\n                    getAddressKeys,\n                    getCalendarKeys,\n                    getCalendarEventPersonal,\n                    memberID,\n                    totalToProcess,\n                    weekStartsOn: model.weekStartsOn,\n                    defaultTzid: calendarUserSettings.PrimaryTimezone,\n                });\n\n                if (totalToProcess !== totalEventsFetched) {\n                    setModelWithAbort((currentModel) => ({\n                        ...currentModel,\n                        totalToProcess: totalEventsFetched,\n                    }));\n                }\n\n                if (signal.aborted) {\n                    return;\n                }\n\n                onFinish(exportedEvents, exportErrors);\n            } catch (error: any) {\n                setModelWithAbort((currentModel) => ({\n                    ...currentModel,\n                    step: EXPORT_STEPS.FINISHED,\n                    totalProcessed: 0,\n                    totalToProcess: 0,\n                    exportErrors: [],\n                    error: EXPORT_ERRORS.NETWORK_ERROR,\n                }));\n\n                if (signal.aborted) {\n                    return;\n                }\n\n                onFinish([], [], true);\n            }\n        };\n\n        process();\n\n        return () => {\n            abortController.abort();\n        };\n    }, []);\n\n    const display = !totalProcessed\n        ? c('Export calendar').t`Loading events`\n        : c('Export calendar').t`Decrypting events from your calendar: ${totalProcessed}/${totalToProcess}`;\n\n    return (\n        <>\n            <div className=\"mb1\">\n                {c('Export calendar').t`Please don't close the tab before the exporting process is finished.`}\n            </div>\n            <DynamicProgress\n                id=\"progress-export-calendar\"\n                value={totalFetched + totalProcessed + totalErrors}\n                display={display}\n                max={2 * totalToProcess}\n                loading\n            />\n        </>\n    );\n};\n\nexport default ExportingModalContent;\n","import { c, msgid } from 'ttag';\n\nimport {\n    EXPORT_ERRORS,\n    EXPORT_EVENT_ERROR_TYPES,\n    ExportCalendarModel,\n    ExportError,\n} from '@proton/shared/lib/interfaces/calendar';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { partition } from '@proton/shared/lib/helpers/array';\nimport { Alert, Bordered, Details, DynamicProgress, Href, Summary } from '../../../components';\n\nconst getErrorMessage = (hasMultiplePasswordResetErrors: boolean) => (type: EXPORT_EVENT_ERROR_TYPES) => {\n    const errorMessagesMap: { [key in EXPORT_EVENT_ERROR_TYPES]: string } = {\n        [EXPORT_EVENT_ERROR_TYPES.DECRYPTION_ERROR]: c('Export calendar').t`Error decrypting event`,\n        [EXPORT_EVENT_ERROR_TYPES.PASSWORD_RESET]: hasMultiplePasswordResetErrors\n            ? c('Export calendar').t`Password reset - multiple events cannot be decrypted`\n            : c('Export calendar').t`Password reset - event cannot be decrypted`,\n    };\n\n    return errorMessagesMap[type];\n};\n\ninterface Props {\n    model: ExportCalendarModel;\n}\n\nconst ExportSummaryModalContent = ({ model }: Props) => {\n    const { totalFetched, totalProcessed, totalToProcess, exportErrors, error } = model;\n    const isSuccess = totalProcessed === totalToProcess && error === undefined;\n    const isPartialSuccess = totalProcessed > 0 && !isSuccess;\n    const totalErrors = exportErrors.length;\n\n    const displayMessage =\n        isPartialSuccess || isSuccess\n            ? c('Export calendar').ngettext(\n                  msgid`${totalProcessed}/${totalToProcess} event exported`,\n                  `${totalProcessed}/${totalToProcess} events exported`,\n                  totalToProcess\n              )\n            : '';\n\n    const [passwordResetErrors, otherErrors] = partition<ExportError>(\n        exportErrors,\n        (item): item is ExportError => item[1] === EXPORT_EVENT_ERROR_TYPES.PASSWORD_RESET\n    );\n    const hasMultiplePasswordResetErrors = passwordResetErrors.length > 1;\n    const filteredErrors: ExportError[] = hasMultiplePasswordResetErrors\n        ? [...otherErrors, ['', EXPORT_EVENT_ERROR_TYPES.PASSWORD_RESET]]\n        : exportErrors;\n    const hasOnlyPasswordResetErrors = passwordResetErrors.length === exportErrors.length;\n\n    const kbLink = getKnowledgeBaseUrl('/restoring-encrypted-calendar');\n    const getAlertMessage = () => {\n        if (isSuccess) {\n            return c('Export calendar').t`Calendar successfully exported. You can now save the ICS file.`;\n        }\n\n        if (isPartialSuccess) {\n            if (hasOnlyPasswordResetErrors) {\n                return (\n                    <>\n                        <div>\n                            {c('Export calendar')\n                                .t`Due to a password reset, some of your events could not be decrypted and exported.`}\n                        </div>\n                        <div>\n                            {c('Export calendar')\n                                .t`You can save an ICS file of the events that were successfully exported.`}\n                        </div>\n                        <div>\n                            <Href url={kbLink}>{c('Export calendar')\n                                .t`Learn how to restore encrypted events with old password`}</Href>\n                        </div>\n                    </>\n                );\n            }\n\n            return (\n                <>\n                    <div>{c('Export calendar').t`Some of your events could not be exported.`}</div>\n                    <div>{c('Export calendar')\n                        .t`You can save an ICS file of the events that were successfully exported.`}</div>\n                </>\n            );\n        }\n\n        if (model.error === EXPORT_ERRORS.NETWORK_ERROR) {\n            return c('Export calendar')\n                .t`The internet connection was interrupted, causing the export process to fail. Please try again.`;\n        }\n\n        if (hasOnlyPasswordResetErrors) {\n            return (\n                <>\n                    <div>\n                        {c('Export calendar')\n                            .t`Due to a password reset, none of your events could be decrypted and exported.`}\n                    </div>\n                    <div>\n                        <Href url={kbLink}>{c('Export calendar')\n                            .t`Learn how to restore encrypted events with old password`}</Href>\n                    </div>\n                </>\n            );\n        }\n\n        return c('Export calendar').t`None of the events could be exported.`;\n    };\n\n    const shouldShowErrorDetails = !!filteredErrors.length && !hasOnlyPasswordResetErrors;\n    const getError = getErrorMessage(hasMultiplePasswordResetErrors);\n\n    const getMessage = () => {\n        const message = getAlertMessage();\n\n        if (isSuccess) {\n            return <div className=\"mb1\">{message}</div>;\n        }\n\n        return (\n            <Alert className=\"mb1\" type={isPartialSuccess ? 'warning' : 'error'}>\n                {message}\n            </Alert>\n        );\n    };\n\n    return (\n        <>\n            {getMessage()}\n            <DynamicProgress\n                id=\"progress-export-calendar\"\n                value={totalFetched + totalProcessed + totalErrors}\n                display={displayMessage}\n                max={2 * totalToProcess}\n                loading={false}\n                success={isSuccess}\n                partialSuccess={isPartialSuccess}\n            />\n            {shouldShowErrorDetails && (\n                <Details>\n                    <Summary>{c('Summary of errors during export calendar')\n                        .t`Details about events that couldn't be exported`}</Summary>\n                    <Bordered>\n                        {filteredErrors.map(([details, error], index) => (\n                            <div key={index}>\n                                {details && <span>{details}: </span>}\n                                <span className=\"color-danger\">{getError(error)}</span>\n                            </div>\n                        ))}\n                    </Bordered>\n                </Details>\n            )}\n        </>\n    );\n};\n\nexport default ExportSummaryModalContent;\n","import { createExportIcs } from '@proton/shared/lib/calendar/export/createExportIcs';\nimport { getProdIdFromNameAndVersion } from '@proton/shared/lib/calendar/vcalConfig';\nimport { getUniqueVtimezones } from '@proton/shared/lib/calendar/vtimezoneHelper';\nimport {\n    Calendar,\n    EXPORT_ERRORS,\n    EXPORT_STEPS,\n    ExportCalendarModel,\n    ExportError,\n    VcalVeventComponent,\n} from '@proton/shared/lib/interfaces/calendar';\nimport { getWeekStartsOn } from '@proton/shared/lib/settings/helper';\nimport { useState } from 'react';\nimport { c } from 'ttag';\n\nimport downloadFile from '@proton/shared/lib/helpers/downloadFile';\nimport { format } from 'date-fns';\nimport { Button, BasicModal } from '../../../components';\nimport { useGetVtimezonesMap } from '../../../hooks/useGetVtimezonesMap';\nimport ExportingModalContent from './ExportingModalContent';\nimport ExportSummaryModalContent from './ExportSummaryModalContent';\nimport { useConfig, useGetCalendarUserSettings, useUserSettings } from '../../../hooks';\nimport { getAppVersion } from '../../..';\n\ninterface Props {\n    calendar: Calendar;\n    onClose?: () => void;\n    onExit?: () => void;\n    isOpen?: boolean;\n}\n\nexport const ExportModal = ({ calendar, onClose, onExit, isOpen = false }: Props) => {\n    const getVTimezonesMap = useGetVtimezonesMap();\n    const getCalendarUserSettings = useGetCalendarUserSettings();\n    const [userSettings] = useUserSettings();\n    const weekStartsOn = getWeekStartsOn(userSettings);\n    const { APP_VERSION } = useConfig();\n    const appVersion = getAppVersion(APP_VERSION);\n\n    const [model, setModel] = useState<ExportCalendarModel>({\n        step: EXPORT_STEPS.EXPORTING,\n        totalFetched: 0,\n        totalProcessed: 0,\n        exportErrors: [],\n        totalToProcess: 0,\n        weekStartsOn,\n        calendar,\n    });\n    const updateModel = (changes: Partial<ExportCalendarModel>) =>\n        setModel((currentModel: ExportCalendarModel) => ({ ...currentModel, ...changes }));\n\n    const [calendarBlob, setCalendarBlob] = useState<Blob>();\n\n    const { content, onSubmit } = (() => {\n        if (model.step === EXPORT_STEPS.EXPORTING) {\n            const handleFinish = async (\n                exportedEvents: VcalVeventComponent[],\n                exportErrors: ExportError[],\n                keepError?: boolean\n            ) => {\n                // we don't catch errors here as they're caught into a NETWORK error on ExportingModalContent\n                const { PrimaryTimezone: defaultTzid } = await getCalendarUserSettings();\n                const uniqueTimezones = await getUniqueVtimezones({\n                    vevents: exportedEvents,\n                    tzids: [defaultTzid],\n                    getVTimezonesMap,\n                }).catch(() => {\n                    return [];\n                });\n\n                const ics = createExportIcs({\n                    calendar,\n                    // We use the ProtonAccount version here,\n                    // but we do not want to display 'Web Account' in this public PRODID\n                    // As a compromise between a \"marketing display\" and traceability,\n                    // we add a '.a' suffix to indicate that the version refers to Proton Account\n                    prodId: getProdIdFromNameAndVersion('WebCalendar', `${appVersion}.a`),\n                    eventsWithSummary: exportedEvents,\n                    defaultTzid,\n                    vtimezones: uniqueTimezones,\n                });\n                updateModel({\n                    step: EXPORT_STEPS.FINISHED,\n                    exportErrors,\n                    ...(!keepError && { error: undefined }),\n                });\n                setCalendarBlob(new Blob([ics], { type: 'text/plain;charset=utf-8' }));\n            };\n\n            return {\n                content: <ExportingModalContent model={model} setModel={setModel} onFinish={handleFinish} />,\n                onSubmit: null,\n            };\n        }\n\n        return {\n            content: <ExportSummaryModalContent model={model} />,\n            onSubmit: () => {\n                if (model.error === EXPORT_ERRORS.NETWORK_ERROR) {\n                    updateModel({ step: EXPORT_STEPS.EXPORTING });\n                    return;\n                }\n\n                downloadFile(calendarBlob, `${calendar.Name}-${format(Date.now(), 'yyyy-MM-dd')}.ics`);\n                onClose?.();\n            },\n        };\n    })();\n\n    return (\n        <BasicModal\n            title={c('Title').t`Export calendar`}\n            footer={\n                <>\n                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                    {!!onSubmit && (\n                        <Button color=\"norm\" onClick={onSubmit} type=\"submit\">\n                            {model.error === EXPORT_ERRORS.NETWORK_ERROR\n                                ? c('Action').t`Try again`\n                                : c('Action').t`Save ICS file`}\n                        </Button>\n                    )}\n                </>\n            }\n            isOpen={isOpen}\n            size=\"large\"\n            fullscreenOnMobile\n            onClose={onClose}\n            onExit={onExit}\n        >\n            {content}\n        </BasicModal>\n    );\n};\n\nexport default ExportModal;\n","import isTruthy from '../helpers/isTruthy';\nimport { SimpleMap } from '../interfaces';\nimport { VcalVeventComponent } from '../interfaces/calendar';\nimport { GetVTimezonesMap } from '../interfaces/hooks/GetVTimezonesMap';\nimport { getPropertyTzid } from './vcalHelper';\n\ninterface Params {\n    vevents?: VcalVeventComponent[];\n    tzids?: string[];\n    getVTimezonesMap: GetVTimezonesMap;\n}\nexport const getUniqueVtimezones = async ({ vevents = [], tzids = [], getVTimezonesMap }: Params) => {\n    const uniqueTzidsMap = [...tzids, ...vevents].reduce<SimpleMap<boolean>>((acc, item) => {\n        if (typeof item === 'string') {\n            acc[item] = true;\n            return acc;\n        }\n        const { dtstart, dtend } = item;\n        const startTzid = getPropertyTzid(dtstart);\n        if (startTzid) {\n            acc[startTzid] = true;\n        }\n        const endTzid = dtend ? getPropertyTzid(dtend) : undefined;\n        if (endTzid) {\n            acc[endTzid] = true;\n        }\n        return acc;\n    }, {});\n    const vtimezoneObjects = Object.values(await getVTimezonesMap(Object.keys(uniqueTzidsMap))).filter(isTruthy);\n\n    return vtimezoneObjects.map(({ vtimezone }) => vtimezone);\n};\n","import { RequireSome } from '../../interfaces';\nimport { Calendar, VcalVcalendar, VcalVeventComponent, VcalVtimezoneComponent } from '../../interfaces/calendar';\nimport { serialize } from '../vcal';\nimport { ICAL_METHOD } from '../constants';\n\ninterface CreateExportIcsParams {\n    prodId: string;\n    eventsWithSummary: VcalVeventComponent[];\n    vtimezones?: VcalVtimezoneComponent[];\n    calendar: Calendar;\n    defaultTzid: string;\n}\n\ntype ExportVcal = RequireSome<VcalVcalendar, 'components'> & {\n    'X-WR-TIMEZONE': { value: string };\n    'X-WR-CALNAME': { value: string };\n    'X-WR-CALDESC'?: { value: string };\n};\n\nexport const createExportIcs = ({\n    calendar,\n    prodId,\n    eventsWithSummary,\n    vtimezones = [],\n    defaultTzid,\n}: CreateExportIcsParams): string => {\n    const exportVcal: ExportVcal = {\n        component: 'vcalendar',\n        components: [...vtimezones, ...eventsWithSummary],\n        prodid: { value: prodId },\n        version: { value: '2.0' },\n        method: { value: ICAL_METHOD.PUBLISH },\n        calscale: { value: 'GREGORIAN' },\n        'X-WR-TIMEZONE': { value: defaultTzid },\n        'X-WR-CALNAME': { value: calendar.Name },\n    };\n\n    if (calendar.Description) {\n        exportVcal['X-WR-CALDESC'] = { value: calendar.Description };\n    }\n\n    return serialize(exportVcal);\n};\n","import { useEffect, useReducer } from 'react';\nimport { SimpleMap } from '@proton/shared/lib/interfaces';\nimport { Calendar } from '@proton/shared/lib/interfaces/calendar';\n\nimport { useGetCalendarBootstrap } from '../../../hooks';\n\nconst reducer = (oldState: SimpleMap<string>, tuples: string[][]) => {\n    const newTuples = tuples.filter(([ID, email]) => {\n        return oldState[ID] !== email;\n    });\n    if (!newTuples.length) {\n        return oldState;\n    }\n    return newTuples.reduce(\n        (acc, [ID, email]) => {\n            acc[ID] = email;\n            return acc;\n        },\n        { ...oldState }\n    );\n};\n\nconst useGetCalendarsEmails = (calendars: Calendar[]) => {\n    const getCalendarBootstrap = useGetCalendarBootstrap();\n\n    const [calendarsEmailsMap, updateCalendarsEmailsMap] = useReducer(reducer, {});\n\n    useEffect(() => {\n        (async () => {\n            const calendarsEmailsTuples = await Promise.all(\n                calendars.map(async ({ ID }) => {\n                    const { Members } = await getCalendarBootstrap(ID);\n                    const [{ Email = '' }] = Members;\n                    return [ID, Email];\n                })\n            );\n            updateCalendarsEmailsMap(calendarsEmailsTuples);\n        })();\n    }, [calendars]);\n\n    return calendarsEmailsMap;\n};\n\nexport default useGetCalendarsEmails;\n","import {\n    getCalendarHasSubscriptionParameters,\n    getCalendarIsNotSyncedInfo,\n    getIsSubscribedCalendar,\n} from '@proton/shared/lib/calendar/subscribe/helpers';\nimport { c } from 'ttag';\nimport { getIsCalendarDisabled, getIsCalendarProbablyActive } from '@proton/shared/lib/calendar/calendar';\nimport { VisualCalendar, SubscribedCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { SimpleMap, UserModel } from '@proton/shared/lib/interfaces';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport React from 'react';\nimport { Badge, DropdownActions, Info, Table, TableBody, TableHeader, TableRow, Tooltip } from '../../../components';\nimport useGetCalendarsEmails from '../hooks/useGetCalendarsEmails';\n\nimport './CalendarsTable.scss';\nimport { classnames } from '../../../helpers';\nimport CalendarSelectIcon from '../../../components/calendarSelect/CalendarSelectIcon';\n\ninterface Props {\n    calendars: (VisualCalendar | SubscribedCalendar)[];\n    defaultCalendarID?: string;\n    user: UserModel;\n    onEdit: (calendar: VisualCalendar) => void;\n    onSetDefault?: (id: string) => void;\n    onDelete: (id: string) => void;\n    onExport?: (calendar: VisualCalendar) => void;\n    loadingMap: SimpleMap<boolean>;\n    actionsDisabled: boolean;\n}\n\nconst CalendarsTable = ({\n    calendars = [],\n    defaultCalendarID,\n    user,\n    onEdit,\n    onSetDefault,\n    onDelete,\n    onExport,\n    loadingMap,\n    actionsDisabled = false,\n}: Props) => {\n    const { hasNonDelinquentScope } = user;\n    const calendarAddressMap = useGetCalendarsEmails(calendars);\n\n    return (\n        <Table className=\"simple-table--has-actions\">\n            <TableHeader\n                cells={[\n                    c('Header').t`Name`,\n                    <div className=\"flex flex-align-items-center\">\n                        <span className=\"mr0-5\">{c('Header').t`Status`}</span>\n                        <Info url={getKnowledgeBaseUrl('/calendar-status')} />\n                    </div>,\n                    c('Header').t`Actions`,\n                ]}\n            />\n            <TableBody>\n                {(calendars || []).map((calendar, index) => {\n                    const { ID, Name, Color } = calendar;\n\n                    const isDisabled = getIsCalendarDisabled(calendar);\n                    const isActive = getIsCalendarProbablyActive(calendar);\n                    const isDefault = ID === defaultCalendarID;\n                    const isSubscribed = getIsSubscribedCalendar(calendar);\n                    const isNotSyncedInfo = getCalendarHasSubscriptionParameters(calendar)\n                        ? getCalendarIsNotSyncedInfo(calendar)\n                        : undefined;\n\n                    const list: { text: string; onClick: () => void }[] = [\n                        hasNonDelinquentScope && {\n                            text: c('Action').t`Edit`,\n                            onClick: () => onEdit(calendar),\n                        },\n                        !isSubscribed &&\n                            !isDisabled &&\n                            !isDefault &&\n                            hasNonDelinquentScope &&\n                            onSetDefault && {\n                                text: c('Action').t`Set as default`,\n                                onClick: () => onSetDefault(ID),\n                            },\n                        !isSubscribed &&\n                            onExport && {\n                                text: c('Action').t`Export ICS`,\n                                onClick: () => onExport(calendar),\n                            },\n                        {\n                            text: isSubscribed ? c('Action').t`Remove` : c('Action').t`Delete`,\n                            actionType: 'delete',\n                            onClick: () => onDelete(ID),\n                        },\n                    ].filter(isTruthy);\n\n                    return (\n                        <TableRow\n                            key={ID}\n                            cells={[\n                                <div key=\"id\">\n                                    <div className=\"grid-align-icon\">\n                                        <CalendarSelectIcon\n                                            color={Color}\n                                            className=\"mr0-75 flex-item-noshrink keep-left\"\n                                        />\n                                        <div className=\"text-ellipsis\" title={Name}>\n                                            {Name}\n                                        </div>\n                                        <div\n                                            className={classnames([\n                                                'text-ellipsis text-sm m0 color-weak',\n                                                !calendarAddressMap[ID] && 'calendar-email',\n                                            ])}\n                                            style={{ '--index': index }}\n                                        >\n                                            {calendarAddressMap[ID] || ''}\n                                        </div>\n                                    </div>\n                                </div>,\n                                <div data-test-id=\"calendar-settings-page:calendar-status\" key=\"status\">\n                                    {isDefault && <Badge type=\"primary\">{c('Calendar status').t`Default`}</Badge>}\n                                    {isActive && <Badge type=\"success\">{c('Calendar status').t`Active`}</Badge>}\n                                    {isDisabled && <Badge type=\"light\">{c('Calendar status').t`Disabled`}</Badge>}\n                                    {isSubscribed && isNotSyncedInfo && (\n                                        <Tooltip title={isNotSyncedInfo.text}>\n                                            <span>\n                                                <Badge type=\"warning\">{isNotSyncedInfo.label}</Badge>\n                                            </span>\n                                        </Tooltip>\n                                    )}\n                                </div>,\n                                <DropdownActions\n                                    className=\"button--small\"\n                                    key=\"actions\"\n                                    list={list}\n                                    disabled={actionsDisabled}\n                                    loading={!!loadingMap[ID]}\n                                />,\n                            ]}\n                        />\n                    );\n                })}\n            </TableBody>\n        </Table>\n    );\n};\n\nexport default CalendarsTable;\n","import { ReactNode } from 'react';\nimport { c, msgid } from 'ttag';\n\nimport { VisualCalendar, SubscribedCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { SimpleMap, UserModel } from '@proton/shared/lib/interfaces';\nimport { MAX_CALENDARS_PER_USER } from '@proton/shared/lib/calendar/constants';\nimport { Card } from '@proton/atoms';\n\nimport { Alert, ButtonLike, PrimaryButton, SettingsLink, Tooltip } from '../../../components';\nimport { SettingsSection } from '../../account';\nimport CalendarsTable from './CalendarsTable';\n\nexport interface CalendarsSectionProps {\n    calendars: (VisualCalendar | SubscribedCalendar)[];\n    defaultCalendarID?: string;\n    user: UserModel;\n    loading?: boolean;\n    loadingMap: SimpleMap<boolean>;\n    canAdd: boolean;\n    isFeatureUnavailable?: boolean;\n    add: string;\n    description?: ReactNode;\n    onAdd: () => void;\n    onSetDefault?: (id: string) => Promise<void>;\n    onEdit: (calendar: VisualCalendar) => void;\n    onDelete: (id: string) => void;\n    onExport?: (calendar: VisualCalendar) => void;\n    canUpgradeLimit?: boolean;\n    calendarLimitReachedText: string;\n}\nconst CalendarsSection = ({\n    calendars = [],\n    defaultCalendarID,\n    user,\n    loading = false,\n    loadingMap,\n    canAdd,\n    isFeatureUnavailable = false,\n    add,\n    description,\n    onAdd,\n    onEdit,\n    onSetDefault,\n    onDelete,\n    onExport,\n    canUpgradeLimit = true,\n    calendarLimitReachedText,\n    ...rest\n}: CalendarsSectionProps) => (\n    <SettingsSection {...rest}>\n        {!canAdd && !isFeatureUnavailable && user.hasNonDelinquentScope && (\n            <Alert className=\"mb1\" type=\"warning\">\n                {calendarLimitReachedText}\n            </Alert>\n        )}\n        {user.isFree && canUpgradeLimit && !canAdd && !isFeatureUnavailable && (\n            <Card rounded className=\"mb1\">\n                <div className=\"flex flex-nowrap flex-align-items-center\">\n                    <p className=\"flex-item-fluid mt0 mb0 pr2\">\n                        {c('Upgrade notice').ngettext(\n                            msgid`Upgrade to a paid plan to create up to ${MAX_CALENDARS_PER_USER} calendar, allowing you to make calendars for work, to share with friends, and just for yourself.`,\n                            `Upgrade to a paid plan to create up to ${MAX_CALENDARS_PER_USER} calendars, allowing you to make calendars for work, to share with friends, and just for yourself.`,\n                            MAX_CALENDARS_PER_USER\n                        )}\n                    </p>\n                    <ButtonLike as={SettingsLink} path=\"/upgrade\" color=\"norm\" shape=\"solid\" size=\"small\">\n                        {c('Action').t`Upgrade`}\n                    </ButtonLike>\n                </div>\n            </Card>\n        )}\n        {description}\n        <div className=\"mb1\">\n            {isFeatureUnavailable ? (\n                <Tooltip title={c('Tooltip').t`This feature is unavailable for the moment`}>\n                    {/* a <span> is added artificially so that the disabled prop of the button does not hide the tooltip */}\n                    <span>\n                        <PrimaryButton data-test-id=\"calendar-setting-page:add-calendar\" disabled>\n                            {add}\n                        </PrimaryButton>\n                    </span>\n                </Tooltip>\n            ) : (\n                <PrimaryButton data-test-id=\"calendar-setting-page:add-calendar\" disabled={!canAdd} onClick={onAdd}>\n                    {add}\n                </PrimaryButton>\n            )}\n        </div>\n        {!!calendars.length && (\n            <CalendarsTable\n                calendars={calendars}\n                defaultCalendarID={defaultCalendarID}\n                user={user}\n                onEdit={onEdit}\n                onSetDefault={onSetDefault}\n                onDelete={onDelete}\n                onExport={onExport}\n                loadingMap={loadingMap}\n                actionsDisabled={loading}\n            />\n        )}\n    </SettingsSection>\n);\n\nexport default CalendarsSection;\n","import { ReactNode, useMemo, useState } from 'react';\nimport { c } from 'ttag';\n\nimport { removeCalendar, updateCalendarUserSettings } from '@proton/shared/lib/api/calendars';\nimport { getActiveAddresses } from '@proton/shared/lib/helpers/address';\nimport { MAX_CALENDARS_PER_FREE_USER, MAX_CALENDARS_PER_USER } from '@proton/shared/lib/calendar/constants';\nimport { Address, UserModel } from '@proton/shared/lib/interfaces';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { ModalWithProps } from '@proton/shared/lib/interfaces/Modal';\n\nimport { AlertModal, Button, useModalState } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\nimport { useModalsMap } from '../../../hooks/useModalsMap';\nimport { CalendarModal } from '../calendarModal/CalendarModal';\nimport { ExportModal } from '../exportModal/ExportModal';\nimport CalendarsSection from './CalendarsSection';\n\ntype ModalsMap = {\n    calendarModal: ModalWithProps<{\n        activeCalendars?: VisualCalendar[];\n        defaultCalendarID?: string;\n        calendar?: VisualCalendar;\n    }>;\n    exportCalendarModal: ModalWithProps<{\n        exportCalendar?: VisualCalendar;\n    }>;\n    deleteCalendarModal: ModalWithProps<{\n        defaultCalendarWarning?: ReactNode;\n        onClose: () => void;\n        onConfirm: () => void;\n    }>;\n};\n\nexport interface PersonalCalendarsSectionProps {\n    addresses: Address[];\n    calendars: VisualCalendar[];\n    activeCalendars: VisualCalendar[];\n    defaultCalendar?: VisualCalendar;\n    user: UserModel;\n}\n\nconst PersonalCalendarsSection = ({\n    addresses,\n    calendars = [],\n    defaultCalendar,\n    activeCalendars = [],\n    user,\n}: PersonalCalendarsSectionProps) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [loadingMap, setLoadingMap] = useState({});\n    const { modalsMap, updateModal, closeModal } = useModalsMap<ModalsMap>({\n        calendarModal: { isOpen: false },\n        exportCalendarModal: { isOpen: false },\n        deleteCalendarModal: { isOpen: false },\n    });\n\n    const activeAddresses = useMemo(() => {\n        return getActiveAddresses(addresses);\n    }, [addresses]);\n    const [{ open: isCalendarModalOpen, onExit: onExitCalendarModal, ...calendarModalProps }, setIsCalendarModalOpen] =\n        useModalState();\n    const [{ open: isExportModalOpen, onExit: onExitExportModal, ...exportModalProps }, setIsExportModalOpen] =\n        useModalState();\n\n    const defaultCalendarID = defaultCalendar?.ID;\n\n    const handleCreate = () => {\n        setIsCalendarModalOpen(true);\n        updateModal('calendarModal', {\n            isOpen: true,\n            props: { activeCalendars, defaultCalendarID },\n        });\n    };\n\n    const handleEdit = (calendar: VisualCalendar) => {\n        setIsCalendarModalOpen(true);\n        updateModal('calendarModal', {\n            isOpen: true,\n            props: { calendar },\n        });\n    };\n\n    const handleSetDefault = async (calendarID: string) => {\n        try {\n            setLoadingMap((old) => ({ ...old, [calendarID]: true }));\n            await api(updateCalendarUserSettings({ DefaultCalendarID: calendarID }));\n            await call();\n            createNotification({ text: c('Success').t`Default calendar updated` });\n        } finally {\n            setLoadingMap((old) => ({ ...old, [calendarID]: false }));\n        }\n    };\n\n    const handleDelete = async (id: string) => {\n        const isDeleteDefaultCalendar = id === defaultCalendarID;\n        const firstRemainingCalendar = activeCalendars.find(({ ID: calendarID }) => calendarID !== id);\n\n        // If deleting the default calendar, the new calendar to make default is either the first active calendar or null if there is none.\n        const newDefaultCalendarID = isDeleteDefaultCalendar\n            ? (firstRemainingCalendar && firstRemainingCalendar.ID) || null\n            : undefined;\n\n        await new Promise<void>((resolve, reject) => {\n            const calendarName = firstRemainingCalendar ? (\n                <span key=\"calendar-name\" className=\"text-break\">\n                    {firstRemainingCalendar.Name}\n                </span>\n            ) : (\n                ''\n            );\n            const defaultCalendarWarning =\n                isDeleteDefaultCalendar && firstRemainingCalendar ? (\n                    <div className=\"mb1\">{c('Info').jt`${calendarName} will be set as default calendar.`}</div>\n                ) : null;\n\n            updateModal('deleteCalendarModal', {\n                isOpen: true,\n                props: {\n                    onClose: () => {\n                        reject();\n                        closeModal('deleteCalendarModal');\n                    },\n                    onConfirm: () => {\n                        resolve();\n                        closeModal('deleteCalendarModal');\n                    },\n                    defaultCalendarWarning,\n                },\n            });\n        });\n        try {\n            setLoadingMap((old) => ({\n                ...old,\n                [newDefaultCalendarID || '']: true,\n                [id]: true,\n            }));\n            await api(removeCalendar(id));\n            // null is a valid default calendar id\n            if (newDefaultCalendarID !== undefined) {\n                await api(updateCalendarUserSettings({ DefaultCalendarID: newDefaultCalendarID }));\n            }\n            await call();\n            createNotification({ text: c('Success').t`Calendar removed` });\n        } finally {\n            setLoadingMap((old) => ({ ...old, [newDefaultCalendarID || '']: false, [id]: false }));\n        }\n    };\n\n    const handleExport = (exportCalendar: VisualCalendar) => {\n        setIsExportModalOpen(true);\n        updateModal('exportCalendarModal', {\n            isOpen: true,\n            props: { exportCalendar },\n        });\n    };\n\n    const calendarsLimit = user.isFree ? MAX_CALENDARS_PER_FREE_USER : MAX_CALENDARS_PER_USER;\n    const calendarLimitReachedText = c('Calendar limit warning')\n        .t`You have reached the maximum number of personal calendars you can create within your plan.`;\n    const isBelowLimit = calendars.length < calendarsLimit;\n\n    const { calendarModal, exportCalendarModal, deleteCalendarModal } = modalsMap;\n\n    return (\n        <>\n            <AlertModal\n                open={deleteCalendarModal.isOpen}\n                title={c('Title').t`Delete calendar`}\n                buttons={[\n                    <Button color=\"danger\" onClick={deleteCalendarModal.props?.onConfirm} type=\"submit\">{c('Action')\n                        .t`Delete`}</Button>,\n                    <Button onClick={deleteCalendarModal.props?.onClose} type=\"submit\">{c('Action').t`Cancel`}</Button>,\n                ]}\n                onClose={deleteCalendarModal.props?.onClose}\n            >\n                <div className=\"mb1\">{c('Info').t`Are you sure you want to delete this calendar?`}</div>\n                {deleteCalendarModal.props?.defaultCalendarWarning}\n            </AlertModal>\n            {!!exportCalendarModal.props?.exportCalendar && (\n                <ExportModal\n                    {...exportCalendarModal}\n                    {...exportModalProps}\n                    calendar={exportCalendarModal.props?.exportCalendar}\n                    isOpen={isExportModalOpen}\n                    onExit={() => {\n                        onExitCalendarModal?.();\n                        updateModal('exportCalendarModal', {\n                            isOpen: false,\n                            props: undefined,\n                        });\n                    }}\n                />\n            )}\n\n            {!!calendarModal.props && (\n                <CalendarModal\n                    {...calendarModal.props}\n                    {...calendarModalProps}\n                    isOpen={isCalendarModalOpen}\n                    onExit={() => {\n                        onExitCalendarModal?.();\n                        updateModal('calendarModal', {\n                            isOpen: false,\n                            props: undefined,\n                        });\n                    }}\n                />\n            )}\n\n            <CalendarsSection\n                calendars={calendars}\n                user={user}\n                defaultCalendarID={defaultCalendar?.ID}\n                loadingMap={loadingMap}\n                add={c('Action').t`Create calendar`}\n                calendarLimitReachedText={calendarLimitReachedText}\n                canAdd={activeAddresses.length > 0 && isBelowLimit && user.hasNonDelinquentScope}\n                onAdd={handleCreate}\n                onSetDefault={handleSetDefault}\n                onEdit={handleEdit}\n                onDelete={handleDelete}\n                onExport={handleExport}\n            />\n        </>\n    );\n};\n\nexport default PersonalCalendarsSection;\n","import { getSubscriptionParameters } from '@proton/shared/lib/api/calendars';\nimport {\n    getIsCalendarSubscriptionEventManagerUpdate,\n    getIsSubscribedCalendar,\n} from '@proton/shared/lib/calendar/subscribe/helpers';\nimport {\n    getIsCalendarEventManagerCreate,\n    getIsCalendarEventManagerDelete,\n    getIsCalendarEventManagerUpdate,\n    getIsCalendarMemberEventManagerCreate,\n    getIsCalendarMemberEventManagerDelete,\n    getIsCalendarMemberEventManagerUpdate,\n} from '@proton/shared/lib/eventManager/helpers';\nimport { findMemberIndices } from '@proton/shared/lib/models/calendarMembers';\nimport { useEffect, useMemo, useState } from 'react';\nimport { Address } from '@proton/shared/lib/interfaces';\nimport {\n    CalendarEventManager,\n    CalendarMemberEventManager,\n    CalendarSubscriptionEventManager,\n} from '@proton/shared/lib/interfaces/calendar/EventManager';\nimport { addItem, removeItem, updateItem } from '@proton/shared/lib/helpers/array';\nimport { getVisualCalendars } from '@proton/shared/lib/calendar/calendar';\nimport {\n    Calendar,\n    VisualCalendar,\n    CalendarSubscription,\n    CalendarSubscriptionResponse,\n    SubscribedCalendar,\n    CalendarWithMembers,\n    CalendarMember,\n} from '@proton/shared/lib/interfaces/calendar';\nimport useApi from './useApi';\nimport useLoading from './useLoading';\nimport useEventManager from './useEventManager';\nimport { useCalendarModelEventManager } from '../containers/eventManager/calendar/ModelEventManagerProvider';\n\nconst useSubscribedCalendars = (calendars: VisualCalendar[], addresses: Address[]) => {\n    const [subscribedCalendars, setSubscribedCalendars] = useState<SubscribedCalendar[]>([]);\n    const [loading, withLoading] = useLoading(true);\n    const api = useApi();\n\n    const calendarIDs = useMemo(() => calendars.map(({ ID }) => ID), [calendars]);\n\n    const { subscribe: standardSubscribe } = useEventManager();\n    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();\n\n    const handleAddCalendar = async (calendar: CalendarWithMembers) => {\n        if (!getIsSubscribedCalendar(calendar)) {\n            return;\n        }\n        const { CalendarSubscription } = await api<CalendarSubscriptionResponse>(\n            getSubscriptionParameters(calendar.ID)\n        );\n\n        setSubscribedCalendars((prevState = []) =>\n            getVisualCalendars(\n                [\n                    ...prevState,\n                    {\n                        ...calendar,\n                        SubscriptionParameters: CalendarSubscription,\n                    },\n                ],\n                addresses\n            )\n        );\n    };\n\n    const handleDeleteCalendar = (calendarID: string) => {\n        setSubscribedCalendars((subscribedCalendars) => {\n            const index = subscribedCalendars?.findIndex((calendar) => calendar.ID === calendarID);\n\n            return removeItem(subscribedCalendars, index);\n        });\n    };\n\n    const handleUpdateCalendar = (calendar: Calendar) => {\n        setSubscribedCalendars((subscribedCalendars) => {\n            const { ID } = calendar;\n            const index = subscribedCalendars?.findIndex((calendar) => calendar.ID === ID);\n\n            return updateItem(subscribedCalendars, index, {\n                ...subscribedCalendars[index],\n                ...calendar,\n            });\n        });\n    };\n\n    const handleDeleteMember = (memberID: string) => {\n        setSubscribedCalendars((subscribedCalendars) => {\n            const [calendarIndex, memberIndex] = findMemberIndices(memberID, subscribedCalendars);\n            if (calendarIndex === -1 || memberIndex === -1) {\n                return subscribedCalendars;\n            }\n            const oldCalendar = subscribedCalendars[calendarIndex];\n\n            return updateItem(subscribedCalendars, calendarIndex, {\n                ...oldCalendar,\n                Members: removeItem(oldCalendar.Members, memberIndex),\n            });\n        });\n    };\n\n    const handleCreateMember = (member: CalendarMember) => {\n        setSubscribedCalendars((subscribedCalendars) => {\n            const { ID: memberID, CalendarID } = member;\n            const [calendarIndex, memberIndex] = findMemberIndices(memberID, subscribedCalendars, CalendarID);\n            if (calendarIndex === -1 || memberIndex !== -1) {\n                return subscribedCalendars;\n            }\n            const oldCalendar = subscribedCalendars[calendarIndex];\n\n            return updateItem(subscribedCalendars, calendarIndex, {\n                ...oldCalendar,\n                Members: addItem(oldCalendar.Members, member),\n            });\n        });\n    };\n\n    const handleUpdateMember = (member: CalendarMember) => {\n        setSubscribedCalendars((subscribedCalendars) => {\n            const { ID: memberID, CalendarID } = member;\n            const [calendarIndex, memberIndex] = findMemberIndices(memberID, subscribedCalendars, CalendarID);\n            if (calendarIndex === -1 || memberIndex === -1) {\n                return subscribedCalendars;\n            }\n            const oldCalendar = subscribedCalendars[calendarIndex];\n\n            return getVisualCalendars(\n                updateItem(subscribedCalendars, calendarIndex, {\n                    ...oldCalendar,\n                    Members: updateItem(oldCalendar.Members, memberIndex, member),\n                }),\n                addresses\n            );\n        });\n    };\n\n    const handleUpdateSubscription = (calendarID: string, subscription: CalendarSubscription) => {\n        setSubscribedCalendars((subscribedCalendars) => {\n            const index = subscribedCalendars?.findIndex((calendar) => calendar.ID === calendarID);\n            const oldCalendar = subscribedCalendars[index];\n            return updateItem(subscribedCalendars, index, {\n                ...oldCalendar,\n                SubscriptionParameters: {\n                    ...oldCalendar.SubscriptionParameters,\n                    ...subscription,\n                },\n            });\n        });\n    };\n\n    useEffect(() => {\n        return standardSubscribe(\n            ({\n                Calendars: CalendarEvents = [],\n                CalendarMembers: CalendarMembersEvents = [],\n            }: {\n                Calendars?: CalendarEventManager[];\n                CalendarMembers?: CalendarMemberEventManager[];\n            }) => {\n                CalendarEvents.forEach((event) => {\n                    if (getIsCalendarEventManagerDelete(event)) {\n                        handleDeleteCalendar(event.ID);\n                    }\n\n                    if (getIsCalendarEventManagerCreate(event)) {\n                        // TODO: The code below is prone to race conditions. Namely if a new event manager update\n                        //  comes before this promise is resolved.\n                        void handleAddCalendar(event.Calendar);\n                    }\n\n                    if (getIsCalendarEventManagerUpdate(event)) {\n                        // TODO: The code below is prone to race conditions. Namely if a new event manager update\n                        //  comes before this promise is resolved.\n                        void handleUpdateCalendar(event.Calendar);\n                    }\n                });\n\n                CalendarMembersEvents.forEach((event) => {\n                    if (getIsCalendarMemberEventManagerDelete(event)) {\n                        handleDeleteMember(event.ID);\n                    } else if (getIsCalendarMemberEventManagerCreate(event)) {\n                        handleCreateMember(event.Member);\n                    } else if (getIsCalendarMemberEventManagerUpdate(event)) {\n                        handleUpdateMember(event.Member);\n                    }\n                });\n            }\n        );\n    }, []);\n\n    useEffect(() => {\n        return calendarSubscribe(\n            calendarIDs,\n            ({\n                CalendarSubscriptions: CalendarSubscriptionEvents = [],\n            }: {\n                CalendarSubscriptions?: CalendarSubscriptionEventManager[];\n            }) => {\n                CalendarSubscriptionEvents.forEach((calendarSubscriptionChange) => {\n                    if (getIsCalendarSubscriptionEventManagerUpdate(calendarSubscriptionChange)) {\n                        const { ID, CalendarSubscription } = calendarSubscriptionChange;\n                        handleUpdateSubscription(ID, CalendarSubscription);\n                    }\n                });\n            }\n        );\n    }, [calendarIDs]);\n\n    useEffect(() => {\n        const run = async () => {\n            const newSubscribedCalendars = await Promise.all(\n                calendars.map(async (calendar) => {\n                    const { CalendarSubscription } = await api<CalendarSubscriptionResponse>(\n                        getSubscriptionParameters(calendar.ID)\n                    );\n\n                    return {\n                        ...calendar,\n                        SubscriptionParameters: CalendarSubscription,\n                    };\n                })\n            );\n\n            void setSubscribedCalendars(newSubscribedCalendars);\n        };\n\n        void withLoading(run());\n    }, []);\n\n    return { subscribedCalendars, loading };\n};\n\nexport default useSubscribedCalendars;\n","import { ChangeEvent, useState } from 'react';\nimport { MAX_LENGTHS_API } from '@proton/shared/lib/calendar/constants';\nimport { truncateMore } from '@proton/shared/lib/helpers/string';\nimport { c } from 'ttag';\n\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { isURL } from '@proton/shared/lib/helpers/validators';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { getCalendarPayload, getCalendarSettingsPayload, getDefaultModel } from '../calendarModal/calendarModalState';\nimport { Href, InputFieldTwo, Loader, Button, BasicModal, Form } from '../../../components';\nimport { useLoading } from '../../../hooks';\nimport { GenericError } from '../../error';\nimport { classnames } from '../../../helpers';\nimport useGetCalendarSetup from '../hooks/useGetCalendarSetup';\nimport useGetCalendarActions from '../hooks/useGetCalendarActions';\n\nconst CALENDAR_URL_MAX_LENGTH = 10000;\n\ninterface Props {\n    onClose?: () => void;\n    onCreateCalendar?: (id: string) => void;\n    isOpen: boolean;\n}\n\nconst SubscribeCalendarModal = ({ isOpen, onClose, onCreateCalendar }: Props) => {\n    const [, setCalendar] = useState<VisualCalendar | undefined>();\n    const [calendarURL, setCalendarURL] = useState('');\n    const [model, setModel] = useState(() => getDefaultModel());\n    const [error, setError] = useState(false);\n\n    const [loadingAction, withLoadingAction] = useLoading();\n\n    const isGoogle = calendarURL.match(/^https?:\\/\\/calendar\\.google\\.com/);\n    const isOutlook = calendarURL.match(/^https?:\\/\\/outlook\\.live\\.com/);\n    const shouldProbablyHaveIcsExtension = (isGoogle || isOutlook) && !calendarURL.endsWith('.ics');\n    const googleWillPossiblyBeMakePublic = calendarURL.match(/\\/public\\/\\w+\\.ics/);\n    const warning = shouldProbablyHaveIcsExtension\n        ? c('Subscribed calendar extension warning').t`This link might be wrong`\n        : isGoogle && googleWillPossiblyBeMakePublic\n        ? c('Subscribed calendar extension warning')\n              .t`By using this link, Google will make the calendar you are subscribing to public`\n        : null;\n\n    const isURLValid = isURL(calendarURL);\n\n    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ setModel });\n    const handleClose = () => {\n        setCalendarURL('');\n        onClose?.();\n    };\n    const { handleCreateCalendar } = useGetCalendarActions({\n        setCalendar,\n        setError,\n        onClose: handleClose,\n        onCreateCalendar,\n        isSubscribedCalendar: true,\n    });\n\n    const handleProcessCalendar = async () => {\n        const formattedModel = {\n            ...model,\n            name: truncateMore({ string: calendarURL, charsToDisplay: MAX_LENGTHS_API.CALENDAR_NAME }),\n            url: calendarURL,\n        };\n        const calendarPayload = getCalendarPayload(formattedModel);\n        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModel);\n\n        return handleCreateCalendar(formattedModel.addressID, calendarPayload, calendarSettingsPayload);\n    };\n\n    const { length: calendarURLLength } = calendarURL;\n    const isURLMaxLength = calendarURLLength === CALENDAR_URL_MAX_LENGTH;\n\n    const {\n        title,\n        submitProps,\n        errorContent = null,\n        onSubmit,\n    } = (() => {\n        if (error || setupError) {\n            const onSubmitError = () => window.location.reload();\n\n            return {\n                title: c('Title').t`Error`,\n                errorContent: <GenericError />,\n                onSubmit: onSubmitError,\n                submitProps: {\n                    children: c('Action').t`Close`,\n                    disabled: !calendarURL || !isURLValid,\n                },\n            };\n        }\n\n        const loading = loadingSetup || loadingAction;\n        const onSubmit = () => withLoadingAction(handleProcessCalendar());\n        const titleAndSubmitCopy = c('Modal title and action').t`Add calendar`;\n\n        return {\n            title: titleAndSubmitCopy,\n            onSubmit,\n            submitProps: {\n                loading,\n                children: titleAndSubmitCopy,\n                disabled: !calendarURL || !isURLValid,\n            },\n        };\n    })();\n\n    const kbLink = (\n        <Href key=\"kbLink\" href={getKnowledgeBaseUrl('/subscribe-to-external-calendar')}>{c(\n            'Subscribe to calendar modal description'\n        ).t`Learn how to get a private calendar link.`}</Href>\n    );\n\n    return (\n        <BasicModal\n            title={title}\n            footer={\n                <>\n                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                    <Button type=\"submit\" color=\"norm\" {...submitProps} />\n                </>\n            }\n            isOpen={isOpen}\n            className=\"modal--shorter-labels w100\"\n            onClose={handleClose}\n            as={Form}\n            dense\n            onSubmit={() => {\n                if (!submitProps.loading) {\n                    onSubmit();\n                }\n            }}\n        >\n            {loadingSetup ? (\n                <Loader />\n            ) : (\n                errorContent || (\n                    <>\n                        <p className=\"mt0 text-pre-wrap\">{c('Subscribe to calendar modal')\n                            .jt`To subscribe to an external or public calendar and its updates, enter the URL. A read-only version of the calendar will be added to your Subscribed calendars.\n${kbLink}\n`}</p>\n                        <InputFieldTwo\n                            autoFocus\n                            hint={\n                                <span className={classnames([isURLMaxLength && 'color-warning'])}>\n                                    {calendarURLLength}/{CALENDAR_URL_MAX_LENGTH}\n                                </span>\n                            }\n                            error={calendarURL && !isURLValid && c('Error message').t`Invalid URL`}\n                            warning={warning}\n                            maxLength={CALENDAR_URL_MAX_LENGTH}\n                            label={c('Subscribe to calendar modal').t`Calendar URL`}\n                            value={calendarURL}\n                            onChange={(e: ChangeEvent<HTMLInputElement>) => setCalendarURL(e.target.value.trim())}\n                            data-test-id=\"input:calendar-subscription\"\n                        />\n                    </>\n                )\n            )}\n        </BasicModal>\n    );\n};\n\nexport default SubscribeCalendarModal;\n","import { ComponentPropsWithoutRef, useState, useRef, useMemo } from 'react';\nimport { c, msgid } from 'ttag';\n\nimport { removeCalendar } from '@proton/shared/lib/api/calendars';\nimport { getActiveAddresses } from '@proton/shared/lib/helpers/address';\nimport { MAX_SUBSCRIBED_CALENDARS_PER_USER } from '@proton/shared/lib/calendar/constants';\nimport { Address, UserModel } from '@proton/shared/lib/interfaces';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { ModalWithProps } from '@proton/shared/lib/interfaces/Modal';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { AlertModal, Button, Href, useModalState } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\nimport { CalendarModal } from '../calendarModal/CalendarModal';\nimport useSubscribedCalendars from '../../../hooks/useSubscribedCalendars';\nimport SubscribeCalendarModal from '../subscribeCalendarModal/SubscribeCalendarModal';\nimport CalendarsSection from './CalendarsSection';\nimport { SettingsParagraph } from '../../account';\nimport { useModalsMap } from '../../../hooks/useModalsMap';\n\ntype ModalsMap = {\n    calendarModal: ModalWithProps<{\n        editCalendar?: VisualCalendar;\n    }>;\n    subscribeCalendarModal: ModalWithProps;\n    deleteCalendarModal: ModalWithProps;\n};\n\nexport interface SubscribedCalendarsSectionProps extends ComponentPropsWithoutRef<'div'> {\n    addresses: Address[];\n    calendars: VisualCalendar[];\n    user: UserModel;\n    unavailable?: boolean;\n}\n\nconst SubscribedCalendarsSection = ({\n    addresses,\n    calendars = [],\n    user,\n    unavailable,\n    ...rest\n}: SubscribedCalendarsSectionProps) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [loadingMap, setLoadingMap] = useState({});\n    const { subscribedCalendars, loading } = useSubscribedCalendars(calendars, addresses);\n\n    const activeAddresses = useMemo(() => {\n        return getActiveAddresses(addresses);\n    }, [addresses]);\n    const [{ open: isCalendarModalOpen, onExit: onExitCalendarModal, ...calendarModalProps }, setIsCalendarModalOpen] =\n        useModalState();\n\n    const confirm = useRef<{ resolve: (param?: any) => any; reject: () => any }>();\n\n    const { modalsMap, updateModal, closeModal } = useModalsMap<ModalsMap>({\n        calendarModal: { isOpen: false },\n        subscribeCalendarModal: { isOpen: false },\n        deleteCalendarModal: { isOpen: false },\n    });\n\n    const handleCreate = () => {\n        updateModal('subscribeCalendarModal', { isOpen: true });\n    };\n\n    const handleEdit = (editCalendar: VisualCalendar) => {\n        setIsCalendarModalOpen(true);\n        updateModal('calendarModal', { isOpen: true, props: { editCalendar } });\n    };\n\n    const handleDelete = async (id: string) => {\n        await new Promise<void>((resolve, reject) => {\n            updateModal('deleteCalendarModal', { isOpen: true });\n            confirm.current = { resolve, reject };\n        });\n\n        try {\n            setLoadingMap((old) => ({\n                ...old,\n                [id]: true,\n            }));\n            await api(removeCalendar(id));\n            await call();\n            createNotification({ text: c('Success').t`Calendar removed` });\n        } finally {\n            setLoadingMap((old) => ({ ...old, [id]: false }));\n        }\n    };\n\n    const canAddCalendar =\n        user.hasNonDelinquentScope &&\n        activeAddresses.length > 0 &&\n        calendars.length < MAX_SUBSCRIBED_CALENDARS_PER_USER;\n\n    const { deleteCalendarModal, calendarModal, subscribeCalendarModal } = modalsMap;\n\n    return (\n        <>\n            <AlertModal\n                open={deleteCalendarModal.isOpen}\n                title={c('Title').t`Remove calendar`}\n                buttons={[\n                    <Button\n                        color=\"danger\"\n                        onClick={() => {\n                            confirm.current?.resolve();\n                            closeModal('deleteCalendarModal');\n                        }}\n                    >{c('Action').t`Remove calendar`}</Button>,\n                    <Button\n                        onClick={() => {\n                            confirm.current?.reject();\n                            closeModal('deleteCalendarModal');\n                        }}\n                    >{c('Action').t`Cancel`}</Button>,\n                ]}\n                onClose={() => confirm.current?.reject()}\n            >\n                {c('Info').t`The calendar will be removed from your account.`}\n            </AlertModal>\n\n            <SubscribeCalendarModal\n                isOpen={subscribeCalendarModal.isOpen}\n                onClose={() => closeModal('subscribeCalendarModal')}\n            />\n            {calendarModal.props?.editCalendar && (\n                <CalendarModal\n                    {...calendarModalProps}\n                    isOpen={isCalendarModalOpen}\n                    calendar={calendarModal.props.editCalendar}\n                    onExit={() => {\n                        onExitCalendarModal?.();\n                        updateModal('calendarModal', { isOpen: true, props: undefined });\n                    }}\n                />\n            )}\n            <CalendarsSection\n                calendars={loading ? calendars : subscribedCalendars}\n                user={user}\n                loading={loading}\n                loadingMap={loadingMap}\n                canAdd={canAddCalendar}\n                isFeatureUnavailable={unavailable}\n                add={c('Action').t`Add calendar`}\n                calendarLimitReachedText={c('Calendar limit warning').ngettext(\n                    msgid`You have reached the maximum of ${MAX_SUBSCRIBED_CALENDARS_PER_USER} subscribed calendar.`,\n                    `You have reached the maximum of ${MAX_SUBSCRIBED_CALENDARS_PER_USER} subscribed calendars.`,\n                    MAX_SUBSCRIBED_CALENDARS_PER_USER\n                )}\n                description={\n                    <SettingsParagraph>\n                        {c('Subscribed calendar section description')\n                            .t`Add public, external, or shared calendars using a URL.`}\n                        <br />\n                        <Href url={getKnowledgeBaseUrl('/subscribe-to-external-calendar')}>{c(\n                            'Knowledge base link label'\n                        ).t`Here's how`}</Href>\n                    </SettingsParagraph>\n                }\n                onAdd={handleCreate}\n                onEdit={handleEdit}\n                onDelete={handleDelete}\n                canUpgradeLimit={false}\n                {...rest}\n            />\n        </>\n    );\n};\n\nexport default SubscribedCalendarsSection;\n","import { c } from 'ttag';\nimport googleLogo from '@proton/styles/assets/img/import/providers/google.svg';\n\nimport { Button, ButtonProps } from '../button';\nimport { classnames } from '../../helpers';\n\nconst GoogleButton = ({ className, ...rest }: ButtonProps) => (\n    <Button className={classnames(['inline-flex flex-justify-center', className])} {...rest}>\n        <img src={googleLogo} alt=\"Google logo\" className=\"mr0-5 flex-align-self-center\" />\n        {c('Action').t`Continue with Google`}\n    </Button>\n);\n\nexport default GoogleButton;\n","import { useState } from 'react';\nimport { c } from 'ttag';\n\nimport { UserModel } from '@proton/shared/lib/interfaces';\nimport { EASY_SWITCH_SOURCE, EasySwitchFeatureFlag, ImportType } from '@proton/shared/lib/interfaces/EasySwitch';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { CALENDAR_APP_NAME } from '@proton/shared/lib/calendar/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { Alert, GoogleButton, Href, Loader, PrimaryButton } from '../../../components';\n\nimport { useAddresses, useFeature, useModals } from '../../../hooks';\n\nimport { ImportModal } from '../importModal';\nimport { SettingsParagraph, SettingsSection } from '../../account';\nimport { EasySwitchOauthModal } from '../../easySwitch';\nimport { FeatureCode } from '../../features';\n\ninterface Props {\n    defaultCalendar?: VisualCalendar;\n    activeCalendars: VisualCalendar[];\n    user: UserModel;\n}\n\nconst CalendarImportSection = ({ activeCalendars, defaultCalendar, user }: Props) => {\n    const { hasNonDelinquentScope } = user;\n    const { createModal } = useModals();\n    const [addresses, loadingAddresses] = useAddresses();\n\n    const easySwitchFeature = useFeature<EasySwitchFeatureFlag>(FeatureCode.EasySwitch);\n    const easySwitchFeatureLoading = easySwitchFeature.loading;\n    const easySwitchFeatureValue = easySwitchFeature.feature?.Value;\n\n    const showAlert = !activeCalendars.length && hasNonDelinquentScope;\n    const canManualImport = !!activeCalendars.length && hasNonDelinquentScope;\n\n    const [isImportModalOpen, setIsImportModalOpen] = useState(false);\n\n    const handleManualImport = () => {\n        if (canManualImport && defaultCalendar) {\n            setIsImportModalOpen(true);\n        }\n    };\n\n    const handleOAuthClick = () =>\n        createModal(\n            <EasySwitchOauthModal\n                source={EASY_SWITCH_SOURCE.IMPORT_CALENDAR_SETTINGS}\n                addresses={addresses}\n                defaultCheckedTypes={[ImportType.CALENDAR]}\n                featureMap={easySwitchFeatureValue}\n            />\n        );\n\n    const isLoading = easySwitchFeatureLoading || loadingAddresses;\n\n    return isLoading ? (\n        <Loader />\n    ) : (\n        <SettingsSection>\n            {isImportModalOpen && (\n                <ImportModal\n                    isOpen={isImportModalOpen}\n                    onClose={() => setIsImportModalOpen(false)}\n                    defaultCalendar={defaultCalendar!}\n                    calendars={activeCalendars}\n                />\n            )}\n\n            {showAlert ? (\n                <Alert className=\"mb1\" type=\"warning\">{c('Info')\n                    .t`You need to have an active personal calendar to import your events from .ics.`}</Alert>\n            ) : null}\n\n            <SettingsParagraph>\n                {c('Calendar import section description')\n                    .t`You can import ICS files from another calendar to ${CALENDAR_APP_NAME}. This lets you quickly import one event or your entire agenda.`}\n                <br />\n                <Href url={getKnowledgeBaseUrl('/how-to-import-calendar-to-proton-calendar')}>{c(\n                    'Knowledge base link label'\n                ).t`Here's how`}</Href>\n            </SettingsParagraph>\n\n            {!easySwitchFeatureLoading && easySwitchFeatureValue?.GoogleCalendar && (\n                <GoogleButton\n                    onClick={handleOAuthClick}\n                    disabled={isLoading || !hasNonDelinquentScope}\n                    className=\"mr1\"\n                />\n            )}\n\n            <PrimaryButton onClick={handleManualImport} disabled={!canManualImport}>\n                {c('Action').t`Import from .ics`}\n            </PrimaryButton>\n        </SettingsSection>\n    );\n};\n\nexport default CalendarImportSection;\n","import { arrayToBinaryString, arrayToHexString, binaryStringToArray, SHA256 } from 'pmcrypto';\nimport getRandomValues from '@proton/get-random-values';\n\nimport { stringToUint8Array, uint8ArrayToBase64String, uint8ArrayToString } from './encoding';\n\nexport const getSHA256String = async (data: string) => {\n    const value = await SHA256(binaryStringToArray(data));\n    return arrayToHexString(value);\n};\n\nexport const getSHA256BinaryString = async (data: string) => {\n    const value = await SHA256(binaryStringToArray(data));\n    return arrayToBinaryString(value);\n};\n\nexport const getSHA256Base64String = async (data: string) => {\n    const value = await SHA256(binaryStringToArray(data));\n    return uint8ArrayToBase64String(value);\n};\n\nexport const generateRandomBytes = (numberOfBytes: number) => getRandomValues(new Uint8Array(numberOfBytes));\n\nexport const xorEncryptDecrypt = ({ key, data }: { key: string; data: string }) => {\n    if (key.length !== data.length) {\n        throw new Error('The length of the key and data do not match.');\n    }\n\n    const Uint8Key = stringToUint8Array(key);\n    const Uint8Data = stringToUint8Array(data);\n\n    const xored = new Uint8Array(Uint8Data.length);\n\n    for (let j = 0; j < Uint8Data.length; j++) {\n        xored[j] = +Uint8Key[j] ^ +Uint8Data[j];\n    }\n\n    return uint8ArrayToString(xored);\n};\n","import { Calendar } from './Calendar';\nimport { Nullable } from '../utils';\n\nexport enum ACCESS_LEVEL {\n    LIMITED = 0,\n    FULL = 1,\n}\n\nexport interface CalendarUrl {\n    CalendarUrlID: string;\n    CalendarID: string;\n    PassphraseID?: string;\n    AccessLevel: ACCESS_LEVEL;\n    EncryptedPurpose: Nullable<string>;\n    EncryptedCacheKey: string;\n    EncryptedPassphrase: Nullable<string>;\n    CreateTime: number;\n}\n\nexport interface CalendarUrlResponse {\n    CalendarUrl: CalendarUrl;\n    Code: number;\n}\n\nexport interface CalendarUrlsResponse {\n    CalendarUrls: CalendarUrl[];\n    Code: number;\n}\n\nexport interface CalendarMap {\n    [key: string]: Calendar;\n}\n\nexport interface CalendarLink extends Omit<CalendarUrl, 'PassphraseID'> {\n    purpose: Nullable<string>;\n    link: string;\n}\n\nexport interface VisualCalendarLink extends CalendarLink {\n    calendarName: string;\n    color: string;\n}\n\nexport interface CopyLinkParams {\n    calendarID: string;\n    urlID: string;\n    accessLevel: ACCESS_LEVEL;\n    encryptedPassphrase: Nullable<string>;\n    encryptedCacheKey: string;\n}\n","import {\n    arrayToBinaryString,\n    createMessage,\n    decodeBase64,\n    decryptMessage,\n    encryptMessage,\n    generateSessionKey,\n    getMessage,\n    OpenPGPKey,\n} from 'pmcrypto';\nimport { AES256, EVENT_ACTIONS } from '../../constants';\nimport { encodeBase64 } from '../../helpers/base64';\nimport { generateRandomBytes, getSHA256Base64String, xorEncryptDecrypt } from '../../helpers/crypto';\nimport { stringToUint8Array, uint8ArrayToPaddedBase64URLString, uint8ArrayToString } from '../../helpers/encoding';\nimport { Nullable } from '../../interfaces';\nimport { ACCESS_LEVEL, CalendarLink, CalendarUrl } from '../../interfaces/calendar';\nimport {\n    CalendarUrlEventManager,\n    CalendarUrlEventManagerCreate,\n    CalendarUrlEventManagerDelete,\n    CalendarUrlEventManagerUpdate,\n} from '../../interfaces/calendar/EventManager';\n\nexport const getIsCalendarUrlEventManagerDelete = (\n    event: CalendarUrlEventManager\n): event is CalendarUrlEventManagerDelete => {\n    return event.Action === EVENT_ACTIONS.DELETE;\n};\nexport const getIsCalendarUrlEventManagerCreate = (\n    event: CalendarUrlEventManager\n): event is CalendarUrlEventManagerCreate => {\n    return event.Action === EVENT_ACTIONS.CREATE;\n};\nexport const getIsCalendarUrlEventManagerUpdate = (\n    event: CalendarUrlEventManager\n): event is CalendarUrlEventManagerUpdate => {\n    return event.Action === EVENT_ACTIONS.UPDATE;\n};\n\nexport const decryptPurpose = async ({\n    encryptedPurpose,\n    privateKeys,\n}: {\n    encryptedPurpose: string;\n    privateKeys: OpenPGPKey[];\n}) =>\n    (\n        await decryptMessage({\n            message: await getMessage(encryptedPurpose),\n            privateKeys,\n        })\n    ).data;\nexport const generateEncryptedPurpose = async ({\n    purpose,\n    publicKeys,\n}: {\n    purpose?: string;\n    publicKeys: OpenPGPKey[];\n}) => {\n    if (!purpose) {\n        return null;\n    }\n\n    return (await encryptMessage({ data: purpose, publicKeys })).data;\n};\nexport const generateEncryptedPassphrase = ({\n    passphraseKey,\n    passphrase,\n}: {\n    passphraseKey: Uint8Array;\n    passphrase: string;\n}) => encodeBase64(xorEncryptDecrypt({ key: uint8ArrayToString(passphraseKey), data: decodeBase64(passphrase) }));\n\nexport const generateCacheKey = () => uint8ArrayToPaddedBase64URLString(generateRandomBytes(16));\n\nexport const generateCacheKeySalt = () => encodeBase64(arrayToBinaryString(generateRandomBytes(8)));\n\nexport const getCacheKeyHash = ({ cacheKey, cacheKeySalt }: { cacheKey: string; cacheKeySalt: string }) =>\n    getSHA256Base64String(`${cacheKeySalt}${cacheKey}`);\n\nexport const generateEncryptedCacheKey = async ({\n    cacheKey,\n    publicKeys,\n}: {\n    cacheKey: string;\n    publicKeys: OpenPGPKey[];\n}) =>\n    (\n        await encryptMessage({\n            message: createMessage(cacheKey),\n            publicKeys,\n        })\n    ).data;\n\nexport const decryptCacheKey = async ({\n    encryptedCacheKey,\n    privateKeys,\n}: {\n    encryptedCacheKey: string;\n    privateKeys: OpenPGPKey[];\n}) =>\n    (\n        await decryptMessage({\n            message: await getMessage(encryptedCacheKey),\n            privateKeys,\n        })\n    ).data;\n\nexport const getPassphraseKey = ({\n    encryptedPassphrase,\n    calendarPassphrase,\n}: {\n    encryptedPassphrase: Nullable<string>;\n    calendarPassphrase: string;\n}) => {\n    if (!encryptedPassphrase) {\n        return null;\n    }\n\n    return stringToUint8Array(\n        xorEncryptDecrypt({ key: decodeBase64(calendarPassphrase), data: decodeBase64(encryptedPassphrase) })\n    );\n};\n\nexport const buildLink = ({\n    urlID,\n    accessLevel,\n    passphraseKey,\n    cacheKey,\n}: {\n    urlID: string;\n    accessLevel: ACCESS_LEVEL;\n    passphraseKey: Nullable<Uint8Array>;\n    cacheKey: string;\n}) => {\n    // calendar.proton.me must be hardcoded here as using getAppHref would produce links that wouldn't work\n    const baseURL = `https://calendar.proton.me/api/calendar/v1/url/${urlID}/calendar.ics`;\n    const encodedCacheKey = encodeURIComponent(cacheKey);\n\n    if (accessLevel === ACCESS_LEVEL.FULL && passphraseKey) {\n        const encodedPassphraseKey = encodeURIComponent(uint8ArrayToPaddedBase64URLString(passphraseKey));\n\n        return `${baseURL}?CacheKey=${encodedCacheKey}&PassphraseKey=${encodedPassphraseKey}`;\n    }\n\n    return `${baseURL}?CacheKey=${encodedCacheKey}`;\n};\n\nexport const getCreatePublicLinkPayload = async ({\n    accessLevel,\n    publicKeys,\n    passphrase,\n    passphraseID,\n}: {\n    accessLevel: ACCESS_LEVEL;\n    publicKeys: OpenPGPKey[];\n    passphrase: string;\n    passphraseID: string;\n}) => {\n    const encryptedPurpose = null;\n    const passphraseKey = await generateSessionKey(AES256);\n    const encryptedPassphrase =\n        accessLevel === ACCESS_LEVEL.FULL ? generateEncryptedPassphrase({ passphraseKey, passphrase }) : null;\n\n    const cacheKeySalt = generateCacheKeySalt();\n    const cacheKey = generateCacheKey();\n    const cacheKeyHash = await getCacheKeyHash({ cacheKey, cacheKeySalt });\n    const encryptedCacheKey = await generateEncryptedCacheKey({ cacheKey, publicKeys });\n\n    return {\n        payload: {\n            AccessLevel: accessLevel,\n            CacheKeySalt: cacheKeySalt,\n            CacheKeyHash: cacheKeyHash,\n            EncryptedPassphrase: encryptedPassphrase,\n            EncryptedPurpose: encryptedPurpose,\n            EncryptedCacheKey: encryptedCacheKey,\n            PassphraseID: accessLevel === ACCESS_LEVEL.FULL ? passphraseID : null,\n        },\n        passphraseKey,\n        cacheKey,\n    };\n};\n\nexport const transformLinkFromAPI = async ({\n    calendarUrl,\n    privateKeys,\n    calendarPassphrase,\n    onError,\n}: {\n    calendarUrl: CalendarUrl;\n    privateKeys: OpenPGPKey[];\n    calendarPassphrase: string;\n    onError: (e: Error) => void;\n}): Promise<CalendarLink> => {\n    const {\n        EncryptedPurpose: encryptedPurpose,\n        CalendarUrlID,\n        AccessLevel,\n        EncryptedCacheKey,\n        EncryptedPassphrase,\n    } = calendarUrl;\n    let purpose = null;\n    let link = '';\n\n    if (encryptedPurpose) {\n        try {\n            purpose = await decryptPurpose({\n                encryptedPurpose,\n                privateKeys,\n            });\n        } catch (e: any) {\n            onError(e);\n            purpose = encryptedPurpose;\n        }\n    }\n\n    try {\n        const cacheKey = await decryptCacheKey({ encryptedCacheKey: EncryptedCacheKey, privateKeys });\n        const passphraseKey = getPassphraseKey({ encryptedPassphrase: EncryptedPassphrase, calendarPassphrase });\n\n        link = buildLink({\n            urlID: CalendarUrlID,\n            accessLevel: AccessLevel,\n            passphraseKey,\n            cacheKey,\n        });\n    } catch (e: any) {\n        onError(e);\n        link = `Error building link: ${e.message}`;\n    }\n\n    return {\n        ...calendarUrl,\n        purpose,\n        link,\n    };\n};\n\nexport const transformLinksFromAPI = async ({\n    calendarUrls,\n    privateKeys,\n    calendarPassphrase,\n    onError,\n}: {\n    calendarUrls: CalendarUrl[];\n    privateKeys: OpenPGPKey[];\n    calendarPassphrase: string;\n    onError: (e: Error) => void;\n}) => {\n    return Promise.all(\n        calendarUrls.map((calendarUrl) =>\n            transformLinkFromAPI({\n                calendarUrl,\n                privateKeys,\n                calendarPassphrase,\n                onError,\n            })\n        )\n    );\n};\n","import { MouseEvent, useMemo } from 'react';\nimport { c } from 'ttag';\n\nimport { Nullable, SimpleMap } from '@proton/shared/lib/interfaces/utils';\nimport { ACCESS_LEVEL, CalendarLink, VisualCalendar, VisualCalendarLink } from '@proton/shared/lib/interfaces/calendar';\nimport { UserModel } from '@proton/shared/lib/interfaces';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\n\nimport { Table, TableHeader, TableBody, TableRow, Info, DropdownActions } from '../../../components';\nimport CalendarSelectIcon from '../../../components/calendarSelect/CalendarSelectIcon';\n\ninterface Props {\n    calendars: VisualCalendar[];\n    linksMap: SimpleMap<CalendarLink[]>;\n    onEdit: ({ calendarID, urlID, purpose }: { calendarID: string; urlID: string; purpose: Nullable<string> }) => void;\n    onCopyLink: (link: string, e: MouseEvent<HTMLButtonElement>) => void;\n    onDelete: ({ calendarID, urlID }: { calendarID: string; urlID: string }) => void;\n    isLoadingMap: SimpleMap<boolean>;\n    user: UserModel;\n}\n\nconst sortLinks = (links: VisualCalendarLink[]) => [...links].sort((a, b) => a.CreateTime - b.CreateTime);\n\nconst LinkTable = ({ calendars, linksMap, onCopyLink, onDelete, onEdit, isLoadingMap, user }: Props) => {\n    const sortedVisualLinks = useMemo(() => {\n        const visualLinkMap = Object.entries(linksMap).reduce<SimpleMap<VisualCalendarLink[]>>(\n            (acc, [calendarID, links]) => {\n                const calendar = calendars.find(({ ID }) => ID === calendarID);\n                if (!calendar || !links) {\n                    // should not happen\n                    return acc;\n                }\n                acc[calendarID] = links.map((link) => ({\n                    ...link,\n                    calendarName: calendar.Name,\n                    color: calendar.Color,\n                }));\n                return acc;\n            },\n            {}\n        );\n\n        return sortLinks(Object.values(visualLinkMap).filter(isTruthy).flat());\n    }, [linksMap, calendars]);\n\n    if (!sortedVisualLinks.length) {\n        return null;\n    }\n\n    return (\n        <>\n            <Table className=\"simple-table--has-actions\">\n                <TableHeader\n                    cells={[\n                        c('Header').t`Calendar`,\n                        <>\n                            <span className=\"mr0-5\">{c('Header').t`Label`}</span>\n                            <Info title={c('Info').t`Only you can see the labels.`} />\n                        </>,\n                        c('Header').t`Actions`,\n                    ]}\n                />\n                <TableBody>\n                    {sortedVisualLinks.map(\n                        ({\n                            CalendarID,\n                            CalendarUrlID,\n                            AccessLevel: accessLevel,\n                            link,\n                            color,\n                            calendarName,\n                            purpose,\n                        }) => {\n                            const list = [\n                                user.hasNonDelinquentScope && {\n                                    text: c('Action').t`Copy link`,\n                                    onClick: (e: MouseEvent<HTMLButtonElement>) => onCopyLink(link, e),\n                                },\n                                user.hasNonDelinquentScope && {\n                                    text: c('Action').t`Edit label`,\n                                    onClick: () => onEdit({ calendarID: CalendarID, urlID: CalendarUrlID, purpose }),\n                                },\n                                {\n                                    text: c('Action').t`Delete`,\n                                    actionType: 'delete',\n                                    onClick: () => onDelete({ calendarID: CalendarID, urlID: CalendarUrlID }),\n                                } as const,\n                            ].filter(isTruthy);\n\n                            return (\n                                <TableRow\n                                    key={CalendarUrlID}\n                                    cells={[\n                                        <div key=\"calendar\">\n                                            <div className=\"grid-align-icon\">\n                                                <CalendarSelectIcon\n                                                    color={color}\n                                                    className=\"flex-item-noshrink mr0-75 keep-left\"\n                                                />\n                                                <div className=\"text-ellipsis\" title={calendarName}>\n                                                    {calendarName}\n                                                </div>\n                                                <div className=\"text-sm color-weak m0\">\n                                                    {accessLevel === ACCESS_LEVEL.FULL\n                                                        ? c('Access level').t`Full`\n                                                        : c('Access level').t`Limited`}\n                                                </div>\n                                            </div>\n                                        </div>,\n                                        <div key=\"label\" className=\"text-ellipsis\" title={purpose || ''}>\n                                            {purpose}\n                                        </div>,\n                                        <DropdownActions\n                                            loading={isLoadingMap[CalendarUrlID]}\n                                            size=\"small\"\n                                            key=\"actions\"\n                                            list={list}\n                                        />,\n                                    ]}\n                                />\n                            );\n                        }\n                    )}\n                </TableBody>\n            </Table>\n        </>\n    );\n};\n\nexport default LinkTable;\n","import { MAX_LINKS_PER_CALENDAR } from '@proton/shared/lib/calendar/constants';\nimport { useEffect, useRef, useState } from 'react';\nimport { c } from 'ttag';\nimport { VisualCalendar, ACCESS_LEVEL, CalendarLink } from '@proton/shared/lib/interfaces/calendar';\nimport { SimpleMap } from '@proton/shared/lib/interfaces/utils';\n\nimport { UserModel } from '@proton/shared/lib/interfaces';\nimport { useLocation } from 'react-router-dom';\nimport {\n    Icon,\n    Table,\n    TableHeader,\n    TableBody,\n    TableRow,\n    Button,\n    Info,\n    SelectTwo,\n    Option,\n    Alert,\n} from '../../../components';\nimport CalendarSelect from '../../../components/calendarSelect/CalendarSelect';\n\ninterface Props {\n    calendars: VisualCalendar[];\n    defaultCalendar?: VisualCalendar;\n    linksMap: SimpleMap<CalendarLink[]>;\n    onCreateLink: ({ accessLevel, calendarID }: { accessLevel: ACCESS_LEVEL; calendarID: string }) => Promise<void>;\n    isLoadingCreate: boolean;\n    disabled: boolean;\n    user: UserModel;\n}\n\nconst ShareTable = ({\n    calendars = [],\n    defaultCalendar,\n    linksMap,\n    onCreateLink,\n    isLoadingCreate,\n    disabled,\n    user,\n}: Props) => {\n    const fallbackCalendar = defaultCalendar || calendars[0];\n    const [selectedCalendarID, setSelectedCalendarID] = useState(fallbackCalendar?.ID);\n    const [accessLevel, setAccessLevel] = useState<ACCESS_LEVEL>(ACCESS_LEVEL.LIMITED);\n    const maxLinksPerCalendarReached = linksMap[selectedCalendarID]?.length === MAX_LINKS_PER_CALENDAR;\n    const shouldDisableCreateButton = disabled || maxLinksPerCalendarReached || !user.hasNonDelinquentScope;\n    const { search } = useLocation();\n    const shareTableWrapperRef = useRef<HTMLDivElement>(null);\n    const options = calendars.map(({ ID, Name, Color }) => ({ id: ID, name: Name, color: Color }));\n\n    useEffect(() => {\n        const searchParams = new URLSearchParams(search);\n        const shareParam = searchParams.get('share');\n\n        if (shareParam) {\n            setTimeout(() => {\n                setSelectedCalendarID(shareParam);\n                shareTableWrapperRef?.current?.scrollIntoView();\n            }, 0);\n        }\n    }, []);\n\n    useEffect(() => {\n        // if the selected calendar gets deleted, use next preferred one\n        if (!calendars.find(({ ID }) => ID === selectedCalendarID)) {\n            setSelectedCalendarID(fallbackCalendar?.ID);\n        }\n    }, [calendars]);\n\n    if (!fallbackCalendar) {\n        return null;\n    }\n\n    return (\n        <div ref={shareTableWrapperRef}>\n            <Table>\n                <TableHeader\n                    cells={[\n                        c('Header').t`Calendar`,\n                        <div className=\"flex flex-align-items-center\">\n                            <span className=\"mr0-5\">{c('Header').t`What others see`}</span>\n                            <Info\n                                title={c('Info')\n                                    .t`Limited view: others see if you're busy. Full view: shows all event details, including name, location, or participants.`}\n                            />\n                        </div>,\n                        null,\n                    ]}\n                />\n                <TableBody>\n                    <TableRow\n                        cells={[\n                            <div key=\"id\" className=\"flex flex-nowrap flex-align-items-center\">\n                                <CalendarSelect\n                                    calendarID={selectedCalendarID}\n                                    options={options}\n                                    onChange={({ value }) => setSelectedCalendarID(value)}\n                                    disabled={disabled}\n                                />\n                            </div>,\n                            <div key=\"what-others-see\">\n                                <SelectTwo\n                                    disabled={disabled}\n                                    value={accessLevel}\n                                    onChange={({ value }) => setAccessLevel(value)}\n                                >\n                                    <Option value={0} title={c('Access level').t`Limited view`} />\n                                    <Option value={1} title={c('Access level').t`Full view`} />\n                                </SelectTwo>\n                            </div>,\n                            <Button\n                                color=\"norm\"\n                                loading={isLoadingCreate}\n                                disabled={shouldDisableCreateButton}\n                                onClick={() => onCreateLink({ accessLevel, calendarID: selectedCalendarID })}\n                            >\n                                <Icon name=\"link\" className=\"mr0-75\" />\n                                {c('Action').t`Create link`}\n                            </Button>,\n                        ]}\n                    />\n                </TableBody>\n            </Table>\n            {maxLinksPerCalendarReached && (\n                <Alert className=\"mb1\" type=\"warning\">{c('Info')\n                    .t`You can create up to ${MAX_LINKS_PER_CALENDAR} links per calendar. To create a new link to this calendar, delete one from the list below.`}</Alert>\n            )}\n        </div>\n    );\n};\n\nexport default ShareTable;\n","import { MouseEvent } from 'react';\nimport { c } from 'ttag';\n\nimport { ACCESS_LEVEL } from '@proton/shared/lib/interfaces/calendar';\n\nimport { BasicModal, Button, InputTwo } from '../../../components';\n\ninterface Props {\n    link: string;\n    onSubmit: (e: MouseEvent<HTMLButtonElement>) => void;\n    onClose: () => void;\n    accessLevel: ACCESS_LEVEL;\n    isOpen: boolean;\n}\n\nconst ShareLinkSuccessModal = ({ link, onSubmit, onClose, accessLevel, isOpen }: Props) => {\n    return (\n        <BasicModal\n            title={c('Title').t`Your calendar link`}\n            footer={<Button className=\"mlauto\" onClick={onSubmit} color=\"norm\">{c('Action').t`Copy link`}</Button>}\n            size=\"medium\"\n            onClose={onClose}\n            isOpen={isOpen}\n        >\n            {accessLevel === ACCESS_LEVEL.FULL ? (\n                <>\n                    <p className=\"mt0\">{c('Info')\n                        .t`By sharing the full event details of this calendar, you accept to grant Proton access to this calendar's encrypted information.`}</p>\n                    <p>{c('Info')\n                        .t`Anyone with this link can see all the event details of this calendar such as title, location or participants.`}</p>\n                </>\n            ) : (\n                <p className=\"mt0\">\n                    {c('Info')\n                        .t`Anyone with this link can see whether you’re free or busy on your calendar. They can’t see event details, such as title, location, or participants.`}\n                </p>\n            )}\n            <label htmlFor=\"your-calendar-url\" className=\"sr-only\">\n                {c('Label').t`Your calendar URL`}\n            </label>\n            <InputTwo id=\"your-calendar-url\" value={link} />\n        </BasicModal>\n    );\n};\n\nexport default ShareLinkSuccessModal;\n","import { c } from 'ttag';\nimport { AlertModal, Button } from '../../../components';\n\ninterface DeleteLinkConfirmationModalProps {\n    onClose: () => void;\n    onConfirm: () => void;\n    isOpen: boolean;\n}\n\nconst DeleteLinkConfirmationModal = ({ onClose, onConfirm, isOpen }: DeleteLinkConfirmationModalProps) => (\n    <AlertModal\n        open={isOpen}\n        onClose={onClose}\n        buttons={[\n            <Button color=\"danger\" type=\"submit\" onClick={onConfirm}>{c('Action').t`Delete link`}</Button>,\n            <Button onClick={onClose}>{c(`Action`).t`Cancel`}</Button>,\n        ]}\n        title={c('Info').t`Delete link?`}\n    >\n        {c('Info')\n            .t`Anyone with this link won't be able to sync or get future updates for your calendar. If you want to give them access again, you will have to create a new link.`}\n    </AlertModal>\n);\n\nexport default DeleteLinkConfirmationModal;\n","import { useState } from 'react';\nimport { Nullable } from '@proton/shared/lib/interfaces/utils';\nimport { c } from 'ttag';\n\nimport { BasicModal, InputTwo, Button, Form } from '../../../components';\nimport { useLoading, useNotifications } from '../../../hooks';\n\ninterface Props {\n    decryptedPurpose: Nullable<string>;\n    onClose: () => void;\n    onSubmit: (purpose: string) => Promise<void>;\n    isOpen: boolean;\n}\n\nconst EditLinkModal = ({ decryptedPurpose, onClose, onSubmit, isOpen }: Props) => {\n    const [purpose, setPurpose] = useState(decryptedPurpose || '');\n    const [isLoading, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n\n    const handleSubmit = async () => {\n        const text = (() => {\n            if (!decryptedPurpose && purpose) {\n                return c('Calendar link purpose update success message').t`Label added`;\n            }\n\n            if (decryptedPurpose && purpose) {\n                return c('Calendar link purpose update success message').t`Label edited`;\n            }\n\n            if (decryptedPurpose && !purpose) {\n                return c('Calendar link purpose update success message').t`Label deleted`;\n            }\n\n            return null;\n        })();\n\n        if (text) {\n            await onSubmit(purpose);\n\n            createNotification({ text });\n        }\n\n        onClose();\n    };\n\n    return (\n        <BasicModal\n            title={decryptedPurpose ? c('Info').t`Edit label` : c('Info').t`Add label`}\n            footer={\n                <>\n                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                    <Button color=\"norm\" type=\"submit\" loading={isLoading}>{c('Action').t`Save`}</Button>\n                </>\n            }\n            isOpen={isOpen}\n            size=\"medium\"\n            onSubmit={() => {\n                if (!isLoading) {\n                    withLoading(handleSubmit());\n                }\n            }}\n            onClose={onClose}\n            as={Form}\n        >\n            <p className=\"mt0\">{c('Info').t`Only you can see the labels.`}</p>\n            <label htmlFor=\"your-calendar-url-label\" className=\"sr-only\">\n                {c('Label').t`Your calendar URL label`}\n            </label>\n            <InputTwo\n                id=\"your-calendar-url-label\"\n                maxLength={50}\n                autoFocus\n                value={purpose}\n                onChange={({ target: { value } }) => setPurpose(value)}\n            />\n        </BasicModal>\n    );\n};\n\nexport default EditLinkModal;\n","import { getPublicLinks } from '@proton/shared/lib/api/calendars';\nimport createCache from '@proton/shared/lib/helpers/cache';\nimport { CalendarUrlsResponse } from '@proton/shared/lib/interfaces/calendar';\nimport { useCallback } from 'react';\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport { getPromiseValue } from './useCachedModelResult';\n\nexport const KEY = 'CALENDAR_PUBLIC_LINKS';\n\nexport const useGetCalendarPublicLinks = () => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(\n        (calendarID: string) => {\n            if (!calendarID) {\n                return Promise.resolve();\n            }\n            return api<CalendarUrlsResponse>(getPublicLinks(calendarID));\n        },\n        [api]\n    );\n\n    return useCallback(\n        (calendarID: string) => {\n            if (!cache.has(KEY)) {\n                cache.set(KEY, createCache());\n            }\n            return getPromiseValue(cache.get(KEY), calendarID, miss);\n        },\n        [cache, miss]\n    );\n};\n","import {\n    getIsCalendarUrlEventManagerCreate,\n    getIsCalendarUrlEventManagerDelete,\n    getIsCalendarUrlEventManagerUpdate,\n    transformLinkFromAPI,\n    transformLinksFromAPI,\n} from '@proton/shared/lib/calendar/shareUrl/helpers';\nimport { updateItem } from '@proton/shared/lib/helpers/array';\nimport { SimpleMap } from '@proton/shared/lib/interfaces';\nimport { VisualCalendar, CalendarLink, CalendarUrl } from '@proton/shared/lib/interfaces/calendar';\nimport {\n    CalendarEventManager,\n    CalendarUrlEventManager,\n    CalendarUrlEventManagerDelete,\n} from '@proton/shared/lib/interfaces/calendar/EventManager';\nimport { splitKeys } from '@proton/shared/lib/keys';\nimport { useEffect, useMemo, useState } from 'react';\nimport { getIsCalendarEventManagerDelete } from '@proton/shared/lib/eventManager/helpers';\nimport { useEventManager, useGetCalendarInfo, useLoading, useNotifications } from '../../../hooks';\nimport { useGetCalendarPublicLinks } from '../../../hooks/useGetCalendarPublicLinks';\nimport { useCalendarModelEventManager } from '../../eventManager';\n\nconst useCalendarShareUrls = (calendars: VisualCalendar[]) => {\n    const { createNotification } = useNotifications();\n    const getCalendarInfo = useGetCalendarInfo();\n    const getPublicLinks = useGetCalendarPublicLinks();\n    const { subscribe: standardSubscribe } = useEventManager();\n    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();\n\n    const [linksMap, setLinksMap] = useState<SimpleMap<CalendarLink[]>>({});\n    const [loading, withLoading] = useLoading(true);\n    const calendarIDs = useMemo(() => calendars.map(({ ID }) => ID), [calendars]);\n\n    const handleError = ({ message }: Error) => createNotification({ type: 'error', text: message });\n\n    const handleDeleteCalendar = (calendarID: string) => {\n        setLinksMap((linksMap) => {\n            const newMap = { ...linksMap };\n            delete newMap[calendarID];\n            return newMap;\n        });\n    };\n\n    const handleDeleteLink = ({ ID }: CalendarUrlEventManagerDelete) => {\n        setLinksMap((linksMap) => {\n            return Object.fromEntries(\n                Object.entries(linksMap).map(([calendarID, links]) => {\n                    const newLinks = links?.filter(({ CalendarUrlID }) => CalendarUrlID !== ID);\n                    return [calendarID, newLinks];\n                })\n            );\n        });\n    };\n\n    const handleAddOrUpdateLink = async (calendarUrl: CalendarUrl) => {\n        const { CalendarID } = calendarUrl;\n        const calendar = calendars.find(({ ID }) => ID === CalendarID);\n        if (!calendar) {\n            return;\n        }\n        const { calendarKeys, passphrase } = await getCalendarInfo(CalendarID);\n        const { privateKeys } = splitKeys(calendarKeys);\n        const link = await transformLinkFromAPI({\n            calendarUrl,\n            privateKeys,\n            calendarPassphrase: passphrase,\n            onError: handleError,\n        });\n        setLinksMap((linksMap) => {\n            const previousLinks = linksMap[CalendarID] || [];\n            const linkIndex = previousLinks.findIndex(\n                ({ CalendarUrlID }) => CalendarUrlID === calendarUrl.CalendarUrlID\n            );\n            const newLinks = linkIndex === -1 ? [...previousLinks, link] : updateItem(previousLinks, linkIndex, link);\n            return {\n                ...linksMap,\n                [CalendarID]: newLinks,\n            };\n        });\n    };\n\n    // load links\n    useEffect(() => {\n        const getAllLinks = async () => {\n            const map: SimpleMap<CalendarLink[]> = {};\n            await Promise.all(\n                calendars.map(async (calendar) => {\n                    const calendarID = calendar.ID;\n                    const { calendarKeys, passphrase } = await getCalendarInfo(calendarID);\n                    const { privateKeys } = splitKeys(calendarKeys);\n                    try {\n                        const { CalendarUrls } = await getPublicLinks(calendarID);\n                        map[calendarID] = await transformLinksFromAPI({\n                            calendarUrls: CalendarUrls,\n                            privateKeys,\n                            calendarPassphrase: passphrase,\n                            onError: handleError,\n                        });\n                    } catch (e: any) {\n                        handleError(e);\n                    }\n                })\n            );\n            setLinksMap(map);\n        };\n        void withLoading(getAllLinks());\n    }, []);\n\n    // subscribe to general event loop\n    useEffect(() => {\n        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {\n            Calendars.forEach((event) => {\n                if (getIsCalendarEventManagerDelete(event)) {\n                    handleDeleteCalendar(event.ID);\n                }\n            });\n        });\n    }, []);\n\n    // subscribe to calendar event loop\n    useEffect(() => {\n        return calendarSubscribe(\n            calendarIDs,\n            ({ CalendarURL: CalendarURLEvents = [] }: { CalendarURL?: CalendarUrlEventManager[] }) => {\n                CalendarURLEvents.forEach((event) => {\n                    if (getIsCalendarUrlEventManagerDelete(event)) {\n                        handleDeleteLink(event);\n                    }\n                    if (getIsCalendarUrlEventManagerCreate(event) || getIsCalendarUrlEventManagerUpdate(event)) {\n                        // TODO: The code below is prone to race conditions. Namely if a new event manager update\n                        //  comes before this promise is resolved.\n                        void handleAddOrUpdateLink(event.CalendarUrl);\n                    }\n                });\n            }\n        );\n    }, [calendarIDs]);\n\n    return {\n        linksMap,\n        isLoadingLinks: loading,\n    };\n};\n\nexport default useCalendarShareUrls;\n","import { textToClipboard } from '@proton/shared/lib/helpers/browser';\nimport { ComponentPropsWithoutRef, MouseEvent, useState } from 'react';\nimport { c } from 'ttag';\nimport { VisualCalendar, ACCESS_LEVEL, CalendarUrlResponse } from '@proton/shared/lib/interfaces/calendar';\n\nimport {\n    buildLink,\n    generateEncryptedPurpose,\n    getCreatePublicLinkPayload,\n} from '@proton/shared/lib/calendar/shareUrl/helpers';\nimport { createPublicLink, deletePublicLink, editPublicLink } from '@proton/shared/lib/api/calendars';\nimport { splitKeys } from '@proton/shared/lib/keys';\nimport { Nullable } from '@proton/shared/lib/interfaces/utils';\nimport { ModalWithProps } from '@proton/shared/lib/interfaces/Modal';\nimport { UserModel } from '@proton/shared/lib/interfaces';\nimport { useApi, useGetCalendarInfo, useNotifications } from '../../../hooks';\nimport { useModalsMap } from '../../../hooks/useModalsMap';\nimport { useCalendarModelEventManager } from '../../eventManager';\n\nimport LinkTable from './LinkTable';\nimport ShareTable from './ShareTable';\nimport ShareLinkSuccessModal from './ShareLinkSuccessModal';\nimport DeleteLinkConfirmationModal from './DeleteLinkConfirmationModal';\nimport EditLinkModal from './EditLinkModal';\nimport { Alert, Loader } from '../../../components';\nimport useCalendarShareUrls from './useCalendarShareUrls';\nimport { SettingsParagraph, SettingsSection } from '../../account';\n\ntype ModalsMap = {\n    shareLinkSuccessModal: ModalWithProps<{\n        onSubmit: (e: MouseEvent<HTMLButtonElement>) => void;\n        accessLevel: ACCESS_LEVEL;\n        link: string;\n    }>;\n    deleteLinkConfirmationModal: ModalWithProps<{ calendarID: string; urlID: string }>;\n    editLinkModal: ModalWithProps<{ calendarID: string; urlID: string; purpose: Nullable<string> }>;\n};\n\ninterface Props extends ComponentPropsWithoutRef<'div'> {\n    defaultCalendar?: VisualCalendar;\n    calendars: VisualCalendar[];\n    user: UserModel;\n}\n\nconst ShareSection = ({ calendars, defaultCalendar, user, ...rest }: Props) => {\n    const { linksMap, isLoadingLinks } = useCalendarShareUrls(calendars);\n    const [isLoadingCreate, setIsLoadingCreate] = useState(false);\n    const [isLoadingMap, setIsLoadingMap] = useState<Partial<Record<string, boolean>>>({});\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const getCalendarInfo = useGetCalendarInfo();\n    const { call } = useCalendarModelEventManager();\n    const notifyLinkCopied = () => {\n        createNotification({ type: 'info', text: c('Info').t`Link copied to clipboard` });\n    };\n\n    const { modalsMap, closeModal, updateModal } = useModalsMap<ModalsMap>({\n        shareLinkSuccessModal: { isOpen: false },\n        deleteLinkConfirmationModal: { isOpen: false },\n        editLinkModal: { isOpen: false },\n    });\n\n    const handleCreateLink = async ({ accessLevel, calendarID }: { accessLevel: ACCESS_LEVEL; calendarID: string }) => {\n        setIsLoadingCreate(true);\n        const { calendarKeys, passphrase, passphraseID } = await getCalendarInfo(calendarID);\n        const { publicKeys } = splitKeys(calendarKeys);\n\n        const { payload, passphraseKey, cacheKey } = await getCreatePublicLinkPayload({\n            accessLevel,\n            publicKeys,\n            passphrase,\n            passphraseID,\n        });\n\n        const {\n            CalendarUrl: { CalendarUrlID },\n        } = await api<CalendarUrlResponse>(createPublicLink(calendarID, payload));\n        const link = buildLink({\n            urlID: CalendarUrlID,\n            accessLevel,\n            passphraseKey,\n            cacheKey,\n        });\n\n        await call([calendarID]);\n        createNotification({ type: 'success', text: c('Info').t`Link created` });\n        setIsLoadingCreate(false);\n\n        updateModal('shareLinkSuccessModal', {\n            isOpen: true,\n            props: {\n                onSubmit: (e: MouseEvent<HTMLButtonElement>) => {\n                    textToClipboard(link, e.currentTarget);\n                    notifyLinkCopied();\n                },\n                accessLevel,\n                link,\n            },\n        });\n    };\n\n    const toggleLinkLoading = (urlID: string, value: boolean) => {\n        setIsLoadingMap((prevIsLoadingMap) => ({ ...prevIsLoadingMap, [urlID]: value }));\n    };\n\n    const tryLoadingAction = async (urlID: string, fn: () => Promise<void>) => {\n        try {\n            toggleLinkLoading(urlID, true);\n            await fn();\n        } catch (error: any) {\n            createNotification({ type: 'error', text: error.message });\n        } finally {\n            toggleLinkLoading(urlID, false);\n        }\n    };\n\n    const handleCopyLink = (link: string, e: MouseEvent<HTMLButtonElement>) => {\n        textToClipboard(link, e.currentTarget);\n        notifyLinkCopied();\n    };\n\n    const handleEdit = ({\n        calendarID,\n        urlID,\n        purpose,\n    }: {\n        calendarID: string;\n        urlID: string;\n        purpose: Nullable<string>;\n    }) => {\n        updateModal('editLinkModal', {\n            isOpen: true,\n            props: { calendarID, urlID, purpose },\n        });\n    };\n\n    const handleDelete = ({ calendarID, urlID }: { calendarID: string; urlID: string }) => {\n        updateModal('deleteLinkConfirmationModal', {\n            isOpen: true,\n            props: { calendarID, urlID },\n        });\n    };\n\n    const infoParagraph = (\n        <SettingsParagraph>{c('Info')\n            .t`Create a link to your calendar and share it with anyone outside Proton. Only you can add or remove events.`}</SettingsParagraph>\n    );\n\n    const { editLinkModal, shareLinkSuccessModal, deleteLinkConfirmationModal } = modalsMap;\n    const editLinkModalProps = editLinkModal.props;\n\n    return (\n        <SettingsSection {...rest}>\n            {!!editLinkModalProps && (\n                <EditLinkModal\n                    isOpen={editLinkModal.isOpen}\n                    onSubmit={async (untrimmedPurpose) => {\n                        const { calendarID, urlID } = editLinkModalProps;\n\n                        return tryLoadingAction(urlID, async () => {\n                            const { calendarKeys } = await getCalendarInfo(calendarID);\n                            const { publicKeys } = splitKeys(calendarKeys);\n                            const purpose = untrimmedPurpose.trim();\n                            const encryptedPurpose = purpose\n                                ? await generateEncryptedPurpose({ purpose, publicKeys })\n                                : null;\n\n                            await api<void>(editPublicLink({ calendarID, urlID, encryptedPurpose }));\n                            await call([calendarID]);\n\n                            closeModal('editLinkModal');\n                        });\n                    }}\n                    decryptedPurpose={editLinkModalProps.purpose}\n                    onClose={() => {\n                        closeModal('editLinkModal');\n                    }}\n                />\n            )}\n            {!!shareLinkSuccessModal.props && (\n                <ShareLinkSuccessModal\n                    isOpen={shareLinkSuccessModal.isOpen}\n                    onClose={() => closeModal('shareLinkSuccessModal')}\n                    {...shareLinkSuccessModal.props}\n                />\n            )}\n            {!!deleteLinkConfirmationModal.props && (\n                <DeleteLinkConfirmationModal\n                    isOpen={deleteLinkConfirmationModal.isOpen}\n                    onConfirm={() => {\n                        const { calendarID, urlID } = deleteLinkConfirmationModal.props!;\n\n                        return tryLoadingAction(urlID, async () => {\n                            await api<void>(deletePublicLink({ calendarID, urlID }));\n                            await call([calendarID]);\n                            closeModal('deleteLinkConfirmationModal');\n                            createNotification({ type: 'success', text: c('Info').t`Link deleted` });\n                        });\n                    }}\n                    onClose={() => closeModal('deleteLinkConfirmationModal')}\n                />\n            )}\n            {calendars.length ? (\n                <>\n                    {infoParagraph}\n                    <ShareTable\n                        linksMap={linksMap}\n                        isLoadingCreate={isLoadingCreate}\n                        disabled={!!isLoadingLinks}\n                        calendars={calendars}\n                        onCreateLink={handleCreateLink}\n                        defaultCalendar={defaultCalendar}\n                        user={user}\n                    />\n                </>\n            ) : (\n                <>\n                    <Alert className=\"mb1\" type=\"warning\">{c('Info')\n                        .t`You need to have a personal calendar to create a link.`}</Alert>\n                    {infoParagraph}\n                </>\n            )}\n            {isLoadingLinks ? (\n                <div className=\"text-center\">\n                    <Loader />\n                </div>\n            ) : (\n                <LinkTable\n                    calendars={calendars}\n                    isLoadingMap={isLoadingMap}\n                    linksMap={linksMap}\n                    onCopyLink={handleCopyLink}\n                    onEdit={handleEdit}\n                    onDelete={handleDelete}\n                    user={user}\n                />\n            )}\n        </SettingsSection>\n    );\n};\n\nexport default ShareSection;\n","import { getClosestLocaleCode } from '@proton/shared/lib/i18n/helper';\nimport { Nullable } from '@proton/shared/lib/interfaces';\nimport { TtagLocaleMap } from '@proton/shared/lib/interfaces/Locale';\nimport { c } from 'ttag';\n\nimport { SelectTwo, Option } from '../../../components';\nimport { useConfig, useUserSettings } from '../../../hooks';\n\ninterface Props {\n    id: string;\n    className?: string;\n    loading: boolean;\n    disabled?: boolean;\n    locale: Nullable<string>;\n    locales: TtagLocaleMap;\n    onChange: (locale: Nullable<string>) => void;\n}\n\nconst InviteLocaleSelector = ({\n    className = 'field w100',\n    loading = false,\n    disabled = false,\n    locale,\n    locales,\n    onChange,\n    ...rest\n}: Props) => {\n    const { LOCALES = {} } = useConfig();\n    const [userSettings] = useUserSettings();\n\n    const defaultLanguage = LOCALES[getClosestLocaleCode(userSettings?.Locale, locales)];\n    const options: { text: string; value: Nullable<string> }[] = Object.keys(LOCALES).map((value) => ({\n        text: LOCALES[value],\n        value,\n    }));\n\n    options.unshift({\n        text: c('Label').t`Default language (${defaultLanguage})`,\n        value: null,\n    });\n\n    const handleChange = async (locale: Nullable<string>) => {\n        const localeCode = locale === null ? null : getClosestLocaleCode(locale, locales);\n        onChange(localeCode);\n    };\n\n    return (\n        <SelectTwo\n            disabled={loading || disabled}\n            className={className}\n            title={c('Action').t`Select language for invitation emails`}\n            value={locale}\n            onChange={({ value }) => handleChange(value)}\n            {...rest}\n        >\n            {options.map(({ text, value }) => (\n                <Option key={value} value={value} title={text} />\n            ))}\n        </SelectTwo>\n    );\n};\n\nexport default InviteLocaleSelector;\n","import { updateCalendarUserSettings } from '@proton/shared/lib/api/calendars';\nimport { getClosestLocaleCode } from '@proton/shared/lib/i18n/helper';\nimport { CalendarUserSettings } from '@proton/shared/lib/interfaces/calendar';\nimport { TtagLocaleMap } from '@proton/shared/lib/interfaces/Locale';\nimport React from 'react';\nimport { c } from 'ttag';\nimport { Info, Toggle } from '../../../components';\n\nimport { useApi, useEventManager, useLoading, useNotifications } from '../../../hooks';\n\nimport { SettingsSection } from '../../account';\nimport SettingsLayout from '../../account/SettingsLayout';\nimport SettingsLayoutLeft from '../../account/SettingsLayoutLeft';\nimport SettingsLayoutRight from '../../account/SettingsLayoutRight';\n\nimport InviteLocaleSelector from './InviteLocaleSelector';\n\ninterface Props {\n    calendarUserSettings: CalendarUserSettings;\n    locales: TtagLocaleMap;\n    hasInviteLocaleFeature: boolean;\n    hasAutoImportInviteFeature: boolean;\n}\n\nconst CalendarInvitationsSection = ({\n    calendarUserSettings: { InviteLocale, AutoImportInvite },\n    locales,\n    hasInviteLocaleFeature,\n    hasAutoImportInviteFeature,\n}: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n\n    const [loadingInviteLocale, withLoadingInviteLocale] = useLoading();\n    const [loadingAutoImportInvite, withLoadingAutoImportInvite] = useLoading();\n\n    const handleChange = async (data: Partial<CalendarUserSettings>) => {\n        await api(updateCalendarUserSettings(data));\n        await call();\n        createNotification({ text: c('Success').t`Preference saved` });\n    };\n\n    const displayedLocale = InviteLocale === null ? null : getClosestLocaleCode(InviteLocale, locales);\n\n    return (\n        <SettingsSection>\n            {hasInviteLocaleFeature && (\n                <SettingsLayout>\n                    <SettingsLayoutLeft>\n                        <label className=\"text-semibold\" htmlFor=\"invite-locale\">\n                            {\n                                // translator: the full sentence will be \"Send invites in [LANGUAGE]\", where [LANGUAGE] is a dropdown with language options. E.g. \"Send invites in [ENGLISH]\"\n                                c('Label').t`Send in`\n                            }{' '}\n                            <Info\n                                buttonClass=\"ml0-5 inline-flex\"\n                                title={c('Info').t`Event invitations and RSVPs will be sent in this language.`}\n                            />\n                        </label>\n                    </SettingsLayoutLeft>\n                    <SettingsLayoutRight>\n                        <InviteLocaleSelector\n                            id=\"invite-locale\"\n                            locale={displayedLocale}\n                            locales={locales}\n                            loading={loadingInviteLocale}\n                            onChange={(InviteLocale) => withLoadingInviteLocale(handleChange({ InviteLocale }))}\n                        />\n                    </SettingsLayoutRight>\n                </SettingsLayout>\n            )}\n            {hasAutoImportInviteFeature && (\n                <SettingsLayout>\n                    <SettingsLayoutLeft>\n                        <label className=\"text-semibold inline-block\" htmlFor=\"auto-import-invitations\">\n                            <span>{c('Auto import invitations setting').jt`Add to calendar and mark as pending`}</span>\n                            <Info\n                                buttonClass=\"ml0-5 inline-flex\"\n                                title={c('Info')\n                                    .t`You still need to reply to invitations for the host to see your response.`}\n                            />\n                        </label>\n                    </SettingsLayoutLeft>\n                    <SettingsLayoutRight className=\"pt0-5 flex flex-align-items-center\">\n                        <Toggle\n                            id=\"auto-import-invitations\"\n                            aria-describedby=\"auto-import-invitations\"\n                            loading={loadingAutoImportInvite}\n                            checked={!!AutoImportInvite}\n                            onChange={({ target }) =>\n                                withLoadingAutoImportInvite(\n                                    handleChange({\n                                        AutoImportInvite: +target.checked,\n                                    })\n                                )\n                            }\n                        />\n                    </SettingsLayoutRight>\n                </SettingsLayout>\n            )}\n        </SettingsSection>\n    );\n};\n\nexport default CalendarInvitationsSection;\n","import { ReactNode, useMemo } from 'react';\nimport { Switch, Route, useRouteMatch, useLocation } from 'react-router-dom';\nimport { c } from 'ttag';\n\nimport { UserModel } from '@proton/shared/lib/interfaces';\nimport { Card } from '@proton/atoms';\nimport {\n    ButtonLike,\n    CalendarImportSection,\n    CalendarLayoutSection,\n    CalendarShareSection,\n    CalendarTimeSection,\n    PersonalCalendarsSection,\n    PrivateMainSettingsArea,\n    SettingsLink,\n    SettingsSection,\n    SubscribedCalendarsSection,\n    ThemesSection,\n    useAddresses,\n    useCalendars,\n    useCalendarsInfoListener,\n    useCalendarUserSettings,\n} from '@proton/components';\nimport {\n    DEFAULT_CALENDAR_USER_SETTINGS,\n    getDefaultCalendar,\n    getProbablyActiveCalendars,\n    getVisualCalendars,\n} from '@proton/shared/lib/calendar/calendar';\nimport { locales } from '@proton/shared/lib/i18n/locales';\nimport { partition } from '@proton/shared/lib/helpers/array';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { getIsPersonalCalendar } from '@proton/shared/lib/calendar/subscribe/helpers';\nimport CalendarInvitationsSection from '@proton/components/containers/calendar/settings/CalendarInvitationsSection';\nimport { getSectionPath } from '@proton/components/containers/layout/helper';\n\nimport PrivateMainAreaLoading from '../../components/PrivateMainAreaLoading';\nimport { getCalendarAppRoutes } from './routes';\n\ninterface Props {\n    user: UserModel;\n    loadingFeatures: boolean;\n    calendarAppRoutes: ReturnType<typeof getCalendarAppRoutes>;\n    redirect: ReactNode;\n    calendarSubscribeUnavailable: boolean;\n    hasInviteLocaleFeature: boolean;\n    hasAutoImportInviteFeature: boolean;\n}\n\nconst CalendarSettingsRouter = ({\n    user,\n    calendarSubscribeUnavailable,\n    hasInviteLocaleFeature,\n    hasAutoImportInviteFeature,\n    loadingFeatures,\n    calendarAppRoutes,\n    redirect,\n}: Props) => {\n    const { path } = useRouteMatch();\n    const location = useLocation();\n\n    const [addresses, loadingAddresses] = useAddresses();\n    const memoizedAddresses = useMemo(() => addresses || [], [addresses]);\n\n    const [calendars, loadingCalendars] = useCalendars();\n    const memoizedCalendars = useMemo(\n        () => getVisualCalendars(calendars || [], memoizedAddresses),\n        [calendars, memoizedAddresses]\n    );\n\n    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS, loadingCalendarUserSettings] =\n        useCalendarUserSettings();\n    const { activeCalendars, allCalendarIDs } = useMemo(() => {\n        return {\n            calendars: memoizedCalendars,\n            activeCalendars: getProbablyActiveCalendars(memoizedCalendars),\n            allCalendarIDs: memoizedCalendars.map(({ ID }) => ID),\n        };\n    }, [calendars]);\n    const [personalCalendars, otherCalendars] = partition<VisualCalendar>(\n        memoizedCalendars || [],\n        getIsPersonalCalendar\n    );\n    const [personalActiveCalendars] = partition<VisualCalendar>(activeCalendars, getIsPersonalCalendar);\n\n    const defaultCalendar = getDefaultCalendar(activeCalendars, calendarUserSettings.DefaultCalendarID);\n\n    useCalendarsInfoListener(allCalendarIDs);\n\n    if (loadingAddresses || loadingCalendars || loadingCalendarUserSettings || loadingFeatures) {\n        return <PrivateMainAreaLoading />;\n    }\n\n    const {\n        routes: { general, calendars: calendarsRoute },\n    } = calendarAppRoutes;\n\n    return (\n        <Switch>\n            <Route path={getSectionPath(path, general)}>\n                <PrivateMainSettingsArea config={general} location={location}>\n                    <CalendarTimeSection calendarUserSettings={calendarUserSettings} />\n                    <CalendarLayoutSection calendarUserSettings={calendarUserSettings} />\n                    <CalendarInvitationsSection\n                        calendarUserSettings={calendarUserSettings}\n                        locales={locales}\n                        hasInviteLocaleFeature={hasInviteLocaleFeature}\n                        hasAutoImportInviteFeature={hasAutoImportInviteFeature}\n                    />\n                    <ThemesSection />\n                </PrivateMainSettingsArea>\n            </Route>\n            <Route path={getSectionPath(path, calendarsRoute)}>\n                <PrivateMainSettingsArea config={calendarsRoute} location={location}>\n                    <PersonalCalendarsSection\n                        addresses={memoizedAddresses}\n                        calendars={personalCalendars}\n                        activeCalendars={personalActiveCalendars}\n                        defaultCalendar={defaultCalendar}\n                        user={user}\n                    />\n                    <SubscribedCalendarsSection\n                        addresses={memoizedAddresses}\n                        calendars={otherCalendars}\n                        user={user}\n                        unavailable={calendarSubscribeUnavailable}\n                    />\n                    <CalendarImportSection\n                        activeCalendars={personalActiveCalendars}\n                        defaultCalendar={defaultCalendar}\n                        user={user}\n                    />\n                    {user.isFree ? (\n                        <SettingsSection>\n                            <Card rounded className=\"mb1\" data-test-id=\"card:upgrade\">\n                                <div className=\"flex flex-nowrap flex-align-items-center\">\n                                    <p className=\"flex-item-fluid mt0 mb0 pr2\">\n                                        {c('Upgrade notice')\n                                            .t`Upgrade to a paid plan to share your personal calendar via link with anyone.`}\n                                    </p>\n                                    <ButtonLike\n                                        as={SettingsLink}\n                                        path=\"/upgrade\"\n                                        color=\"norm\"\n                                        shape=\"solid\"\n                                        size=\"small\"\n                                    >\n                                        {c('Action').t`Upgrade`}\n                                    </ButtonLike>\n                                </div>\n                            </Card>\n                        </SettingsSection>\n                    ) : (\n                        <CalendarShareSection\n                            id=\"calendar-share-section\"\n                            calendars={personalCalendars}\n                            defaultCalendar={defaultCalendar}\n                            user={user}\n                        />\n                    )}\n                </PrivateMainSettingsArea>\n            </Route>\n            {redirect}\n        </Switch>\n    );\n};\n\nexport default CalendarSettingsRouter;\n","import { useEffect, useState, useMemo, useRef, ChangeEvent, MouseEvent } from 'react';\nimport { c, msgid } from 'ttag';\nimport { Locale, addMinutes, startOfDay, format, parse } from 'date-fns';\nimport { dateLocale } from '@proton/shared/lib/i18n';\nimport { findLongestMatchingIndex } from '@proton/shared/lib/helpers/string';\nimport { withDecimalPrecision } from '@proton/shared/lib/helpers/math';\n\nimport Input, { Props as InputProps } from './Input';\nimport Dropdown from '../dropdown/Dropdown';\nimport { usePopperAnchor } from '../popper';\nimport { generateUID } from '../../helpers';\nimport DropdownMenu from '../dropdown/DropdownMenu';\nimport DropdownMenuButton from '../dropdown/DropdownMenuButton';\nimport { useHotkeys } from '../../hooks';\n\nconst toFormatted = (value: Date, locale: Locale) => {\n    return format(value, 'p', { locale });\n};\n\nconst fromFormatted = (value: string, locale: Locale) => {\n    return parse(value, 'p', new Date(), { locale });\n};\n\nconst formatDuration = (label: string, minutes: number) => {\n    const hours = withDecimalPrecision(minutes / 60, 1);\n    const hoursInt = Math.ceil(hours);\n    return hours >= 1\n        ? c('Time unit').ngettext(msgid`${hours} hour`, `${hours} hours`, hoursInt)\n        : c('Time unit').ngettext(msgid`${minutes} minute`, `${minutes} minutes`, minutes);\n};\n\nconst getMinutes = (date: Date) => date.getHours() * 60 + date.getMinutes();\n\n// Get minutes from midnight to prevent having options going further than 11:30 PM (when prevent preventNextDayOverflow prop is active)\nconst getBaseDateMinutes = (baseDate: Date, interval: number) => {\n    const baseMinutes = baseDate.getMinutes();\n    let minutes = 0;\n    if (baseMinutes > interval) {\n        // calculate minutes to remove depending on the interval\n        minutes = Math.floor(baseMinutes / interval) * interval;\n    }\n\n    return (24 - baseDate.getHours()) * 60 - minutes;\n};\n\nconst MAX_MINUTES = 24 * 60;\n\ninterface Props extends Omit<InputProps, 'onChange' | 'min' | 'max' | 'value'> {\n    value: Date;\n    min?: Date;\n    max?: Date;\n    onChange: (date: Date) => void;\n    displayDuration?: boolean;\n    base?: Date;\n    interval?: number;\n    preventNextDayOverflow?: boolean; // If we have a min hour, we may want to avoid having calculated options overflowing on the next day\n}\n\nconst TimeInput = ({\n    onChange,\n    value,\n    interval = 30,\n    min,\n    displayDuration = false,\n    max,\n    preventNextDayOverflow = false,\n    ...rest\n}: Props) => {\n    const [uid] = useState(generateUID('dropdown'));\n    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLInputElement>();\n    const [temporaryInput, setTemporaryInput] = useState(() => toFormatted(value, dateLocale));\n\n    useEffect(() => {\n        setTemporaryInput(toFormatted(value, dateLocale));\n    }, [value]);\n\n    const base = useMemo(() => min || startOfDay(value), [min, value]);\n\n    const minMinutes = getMinutes(base);\n    const valueMinutes = getMinutes(value);\n    const normalizedMinutes = valueMinutes - minMinutes;\n\n    const handleSelectDate = (newDate: Date) => {\n        const newMinutes = getMinutes(newDate);\n\n        if (valueMinutes === newMinutes) {\n            return;\n        }\n\n        const diffMinutes = newMinutes - minMinutes;\n\n        const normalizedDate = new Date(\n            base.getFullYear(),\n            base.getMonth(),\n            base.getDate(),\n            0,\n            minMinutes + (diffMinutes < 0 && !preventNextDayOverflow ? diffMinutes + MAX_MINUTES : diffMinutes)\n        );\n\n        onChange(normalizedDate);\n    };\n\n    const parseAndSetDate = (temporaryInput: string) => {\n        try {\n            const newDate = fromFormatted(temporaryInput, dateLocale);\n            const newDateTime = +newDate;\n            if (!Number.isNaN(newDateTime)) {\n                handleSelectDate(newDate);\n            }\n            // eslint-disable-next-line no-empty\n        } catch (e: any) {}\n\n        setTemporaryInput(toFormatted(value, dateLocale));\n    };\n\n    const handleBlur = () => {\n        parseAndSetDate(temporaryInput);\n        close();\n    };\n\n    useHotkeys(anchorRef, [\n        [\n            'Escape',\n            (e) => {\n                if (isOpen) {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    parseAndSetDate(temporaryInput);\n                    close();\n                }\n            },\n        ],\n        [\n            'Enter',\n            (e) => {\n                parseAndSetDate(temporaryInput);\n                if (isOpen) {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    close();\n                } else {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    open();\n                }\n            },\n        ],\n        [\n            'ArrowDown',\n            (e) => {\n                if (isOpen) {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    handleSelectDate(addMinutes(value, interval));\n                }\n            },\n        ],\n        [\n            'ArrowUp',\n            (e) => {\n                if (isOpen) {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    handleSelectDate(addMinutes(value, -1 * interval));\n                }\n            },\n        ],\n    ]);\n\n    const scrollRef = useRef<HTMLDivElement>(null);\n    const listRef = useRef<HTMLUListElement>(null);\n\n    const options = useMemo(() => {\n        const totalMinutes = preventNextDayOverflow ? getBaseDateMinutes(base, interval) : MAX_MINUTES;\n        const length = Math.floor(totalMinutes / interval);\n        const minutes = Array.from({ length }, (a, i) => i * interval);\n\n        return minutes.map((minutes) => {\n            const value = addMinutes(base, minutes);\n            const label = toFormatted(value, dateLocale);\n            return {\n                minutes,\n                value,\n                label: displayDuration ? `${label} (${formatDuration(label, minutes)})` : label,\n            };\n        });\n    }, [normalizedMinutes, base]);\n\n    const filteredOptions = useMemo(() => {\n        return options.filter(({ value }) => {\n            const minCondition = min ? value >= min : true;\n            const maxCondition = max ? value <= max : true;\n            return minCondition && maxCondition;\n        });\n    }, [options, min, max]);\n\n    const matchingIndex = useMemo(() => {\n        const idx = findLongestMatchingIndex(\n            filteredOptions.map(({ label }) => label),\n            temporaryInput\n        );\n        return idx === -1 ? undefined : idx;\n    }, [filteredOptions, temporaryInput]);\n\n    const scrollToSelection = () => {\n        if (!isOpen) {\n            return;\n        }\n        if (!listRef.current || !scrollRef.current || matchingIndex === undefined) {\n            return;\n        }\n        const matchingEl = listRef.current.children[matchingIndex] as HTMLLIElement;\n        if (matchingEl) {\n            scrollRef.current.scrollTop =\n                matchingEl.offsetTop - (scrollRef.current.clientHeight - matchingEl.clientHeight) / 2;\n        }\n    };\n\n    useEffect(() => {\n        // RAF needed due to our portal behavior in dropdown\n        requestAnimationFrame(scrollToSelection);\n    }, [isOpen]);\n\n    useEffect(() => {\n        scrollToSelection();\n    }, [matchingIndex]);\n\n    return (\n        <>\n            <Input\n                type=\"text\"\n                ref={anchorRef}\n                onFocus={() => open()}\n                onBlur={handleBlur}\n                onClick={() => open()}\n                value={temporaryInput}\n                onChange={({ target: { value } }: ChangeEvent<HTMLInputElement>) => setTemporaryInput(value)}\n                {...rest}\n            />\n            <Dropdown\n                id={uid}\n                isOpen={isOpen}\n                anchorRef={anchorRef}\n                onClose={close}\n                disableFocusTrap\n                autoClose={false}\n                autoCloseOutside={false}\n                contentProps={{\n                    onMouseDown: (event: MouseEvent<HTMLDivElement>) => {\n                        // Prevent default to stop the input getting blurred.\n                        event.preventDefault();\n                    },\n                    ref: scrollRef,\n                }}\n                disableDefaultArrowNavigation\n            >\n                <DropdownMenu listRef={listRef}>\n                    {filteredOptions.map(({ label, value: otherValue }, i) => {\n                        // Only highlight if the text includes the input (where 13:05 is centered but not highlighted)\n                        const isSelected = i === matchingIndex && label.includes(temporaryInput);\n                        return (\n                            <DropdownMenuButton\n                                key={i}\n                                isSelected={isSelected}\n                                style={{ pointerEvents: 'auto' }} // Lets the user select the time during typing\n                                onClick={() => {\n                                    handleSelectDate(otherValue);\n                                    close();\n                                }}\n                            >\n                                {label}\n                            </DropdownMenuButton>\n                        );\n                    })}\n                </DropdownMenu>\n            </Dropdown>\n        </>\n    );\n};\n\nexport default TimeInput;\n","import { c } from 'ttag';\n\nimport { Button } from '../../components';\nimport { classnames } from '../../helpers';\nimport './ThemeCard.scss'; // just for proper sizing when zooming\n\ninterface Props {\n    label: string;\n    id: string;\n    src: string;\n    selected: boolean;\n    onChange: () => void;\n    disabled?: boolean;\n}\n\nconst ThemeCard = ({ label, id, src, selected, onChange, disabled }: Props) => {\n    return (\n        <Button\n            name=\"themeCard\"\n            shape=\"outline\"\n            color={selected ? 'norm' : 'weak'}\n            id={id}\n            fullWidth\n            className={classnames(['theme-card-button', selected && 'is-active no-pointer-events text-bold'])}\n            aria-pressed={selected}\n            onClick={onChange}\n            disabled={disabled}\n            type=\"button\"\n            aria-label={c('Action').t`Use ${label} theme`}\n            title={c('Action').t`Use ${label} theme`}\n        >\n            <span className=\"flex flex-nowrap flex-column flex-align-items-center\">\n                <img alt=\"\" src={src} className=\"mb0-5 theme-card-image on-rtl-mirror\" />\n                <div className=\"py0-25\">{label}</div>\n            </span>\n        </Button>\n    );\n};\n\nexport default ThemeCard;\n","import { ThemeTypes } from '@proton/shared/lib/themes/themes';\n\nimport ThemeCard from './ThemeCard';\nimport { classnames } from '../../helpers';\n\nexport interface Theme {\n    label: string;\n    identifier: ThemeTypes;\n    src: { medium: string; small: string };\n}\n\ninterface Props {\n    themeIdentifier: ThemeTypes;\n    className?: string;\n    liClassName?: string;\n    onChange: (themeType: ThemeTypes) => void;\n    disabled?: boolean;\n    list: Theme[];\n    size?: 'small' | 'medium';\n}\n\nconst ThemeCards = ({ themeIdentifier, onChange, disabled, className, liClassName, list, size = 'medium' }: Props) => {\n    return (\n        <ul className={classnames(['unstyled m0', className])}>\n            {list.map(({ identifier, label, src }) => {\n                const id = `id_${identifier}`;\n                return (\n                    <li className={liClassName} key={label}>\n                        <ThemeCard\n                            label={label}\n                            id={id}\n                            src={src[size]}\n                            selected={themeIdentifier === identifier}\n                            onChange={() => onChange(identifier)}\n                            disabled={disabled}\n                        />\n                    </li>\n                );\n            })}\n        </ul>\n    );\n};\n\nexport default ThemeCards;\n","import { c } from 'ttag';\nimport { updateThemeType } from '@prot