from pathlib import Path
for base in ('packages','applications'):
 for p in Path(base).rglob('*'):
  if p.suffix not in ('.ts','.tsx','.js') or any(x in p.parts for x in ('dist','node_modules')): continue
  s=p.read_text(errors='ignore')
  if 'ResizeObserver' in s or ('useGetCalendarSetup' in s and ('mock' in str(p) or 'spec' in str(p))):
   for n,l in enumerate(s.splitlines(),1):
    if 'ResizeObserver' in l or 'useGetCalendarSetup' in l: print(f'{p}:{n}:{l[:180]}')
PY"

